                                                soChietKhau = match.Groups[2].Value;
                                            }
                                            soChietKhau = soChietKhau.Replace(",", ".");
                                            percent = double.Parse(soChietKhau);
                                            //Tìm thằng nào có tổng tiền phù hợp
                                            foreach (var ftt in it.fileImportDetails.Where(m => m.TKCo != "711"))
                                            {
                                                var sodu = Math.Round(ftt.TTien * percent / 100) - i7.TTien;
                                                if (sodu >= 0 && sodu <= 1)
                                                {
                                                    finddata += 1;
                                                    ftt.TTien = ftt.TTien - i7.TTien;

                                                    var qrq = "UPDATE tbimportdetail SET TTien=? WHERE ID=?";
                                                    var parametersss = new OleDbParameter[]
                                                    {
                                                new OleDbParameter("?", ftt.TTien),
                                                new OleDbParameter("?", ftt.ID),
                                                    };
                                                    ExecuteQueryResult(qrq, parametersss);

                                                    //Xoá đi dòng 711
                                                    var qrqd = "delete from tbimportdetail  WHERE ID=?";
                                                    var parameters = new OleDbParameter[]
                                                    {
                                                new OleDbParameter("?", i7.ID),
                                                    };
                                                    ExecuteQueryResult(qrqd, parameters);
                                                }
                                            }
                                            //Trường hợp ko tìm dc thì tìm % r phân bổ ra

                                        }
                                        it.fileImportDetails.Remove(i7);
                                    }
                                    //Trường hợp ko tìm dc thì buộc phải tìm % để phân bổ
                                    if (finddata != get771s.Count)
