            var kq = ExecuteQuery(queryCheckVatTu, parameterss);

            //Duyệt trong hoa don chung tu
            var joinedLookup = existingTbHoadon.AsEnumerable()
                .Join(existingTbChungtu.AsEnumerable(),
                      h => RemoveLeadingZeros(h.Field<string>("SoHD")),           // Key hoadon
                      c => RemoveLeadingZeros(c.Field<string>("SoHieu")),         // Key chungtu  
                      (h, c) => new {                         // Kết quả join
                          HoaDon = h,
                          ChungTu = c
                      })
                .ToLookup(x => new {                          // Lookup key
                    SoHD = RemoveLeadingZeros(x.ChungTu.Field<string>("SoHieu")).TrimEnd('.'), 
