                                }
                               
                            }
                            //Trường hợp có nhiều 711
                            else
                            {
                                var get771s = getlist711.Where(m => m.TKCo == "711").ToList();
                                int finddata = 0;
                                foreach(var i7 in get771s)
                                {
                                    string pattern = @"(\d+[,.]?\d*)%|chiết khấu\s*(\d+)";

                                     
                                    var match = Regex.Match(i7.Ten, pattern);
                                    double percent = 0;
                                    //Kiển tra xem có phải chiết khấu có % không
                                    if (match.Success)
                                    {
                                        string soChietKhau = match.Groups[1].Value;
                                        if(string.IsNullOrEmpty(soChietKhau) )
                                        {
                                            soChietKhau = match.Groups[2].Value;
                                        }
                                        soChietKhau = soChietKhau.Replace(",", ".");
                                        percent = double.Parse(soChietKhau);
                                        //Tìm thằng nào có tổng tiền phù hợp
                                        foreach(var ftt in it.fileImportDetails.Where(m => m.TKCo != "711"))
                                        {
                                            var sodu = Math.Round(ftt.TTien * percent / 100) - i7.TTien;
                                            if (sodu>=0 && sodu<=1 )
                                            {
                                                finddata += 1;
                                                ftt.TTien = ftt.TTien - i7.TTien;

                                                var qrq = "UPDATE tbimportdetail SET TTien=? WHERE ID=?";
                                                var parametersss = new OleDbParameter[]
                                                {
                                                new OleDbParameter("?", ftt.TTien),
                                                new OleDbParameter("?", ftt.ID),
                                                };
                                                ExecuteQueryResult(qrq, parametersss);

                                                //Xoá đi dòng 711
                                                var qrqd = "delete from tbimportdetail  WHERE ID=?";
                                                var parameters = new OleDbParameter[]
                                                {
                                                new OleDbParameter("?", i7.ID),
                                                };
                                                ExecuteQueryResult(qrqd, parameters); 
                                            }
                                        }
                                        //Trường hợp ko tìm dc thì tìm % r phân bổ ra

                                    }
                                    it.fileImportDetails.Remove(i7);
                                }
                                //Trường hợp ko tìm dc thì buộc phải tìm % để phân bổ
                                if (finddata != get771s.Count)
                                { 

                                    //Tính lại giá tiền cho các dòng
                                    var remainlist = it.fileImportDetails.Where(m => m.TKCo!="711" && !string.IsNullOrEmpty(m.DVT) && m.Dongia != 0).ToList();
                                    double totalth = remainlist.Sum(m => m.TTien);
                                    double total711 = get771s.Sum(m => m.TTien);
                                    int index = 0;
                                    foreach (var it2 in remainlist)
                                    {
                                       
                                        if (index < remainlist.Count - 1)
                                        {
                                            it2.TTien = Math.Round(it2.TTien - (total711 * it2.TTien / totalth));
                                        }
                                        else
                                        { 
                                             it2.TTien = Math.Round(it2.TTien - (total711 * it2.TTien / totalth));
                                             double reTotal= Math.Round(it.TgTCThue - remainlist.Sum(m => m.TTien));
                                            it2.TTien += reTotal;
                                        }
                                        //Cập nhật vô database
                                        var qrq = "UPDATE tbimportdetail SET TTien=? WHERE ID=?";
                                        var parametersss = new OleDbParameter[]
                                        {
                                                new OleDbParameter("?", it2.TTien),
                                                new OleDbParameter("?", it2.ID),
                                        };
                                        ExecuteQueryResult(qrq, parametersss);
                                        index += 1;
                                    }
                                    foreach(var dt7 in get771s)
