        private void MatdinhdanhmucvattuVao(FileImportDetail fileImportDetail)
        {
            string tensp = fileImportDetail.SoHieu;
            var findvt = lstvt.Where(m => m.SoHieu.ToLower() == tensp.ToLower()).FirstOrDefault();
            if (findvt != null)
            {
                var findpl = PLHH.AsEnumerable().Where(m => m.Field<int>("MaSo") == findvt.MaPhanLoai).FirstOrDefault();
                if (findpl != null && !string.IsNullOrEmpty(findpl.Field<string>("TKNo")))
                {
                    fileImportDetail.TKNo = findpl.Field<string>("TKNo") ?? fileImportDetail.TKNo;
                    //Update trong database
                    string query = @"UPDATE tbimportdetail SET TKNo=?  WHERE ID=?";
                    var parameters = new OleDbParameter[]
             {
                                   new OleDbParameter("?",fileImportDetail.TKNo),
                                   new OleDbParameter("?",fileImportDetail.ID),
             };
                    int rowsAffected = ExecuteQueryResult(query, parameters);
                }
            }
        }
        private void Matdinhdanhmucvattu(FileImportDetail fileImportDetail)
        {
            string tensp = fileImportDetail.SoHieu;
            var findvt = lstvt.Where(m => m.SoHieu.ToLower() == tensp.ToLower()).FirstOrDefault();
            if (findvt != null)
            {
                var findpl = PLHH.AsEnumerable().Where(m => m.Field<int>("MaSo") == findvt.MaPhanLoai).FirstOrDefault();
                if (findpl != null && !string.IsNullOrEmpty(findpl.Field<string>("TKCo")))
                {
                    if (fileImportDetail.TKNo.StartsWith("51"))
                        return;
                    fileImportDetail.TKCo = findpl.Field<string>("TKCo") ?? fileImportDetail.TKCo;
                    //Update trong database
                    string query = @"UPDATE tbimportdetail SET TKCo=?  WHERE ID=?";
                    var parameters = new OleDbParameter[]
             {
                                   new OleDbParameter("?",fileImportDetail.TKCo),
                                   new OleDbParameter("?",fileImportDetail.ID),
             };
                    int rowsAffected = ExecuteQueryResult(query, parameters);
                }
            }
        }

