        private void ReceiveData()
        {
            byte[] buffer = new byte[1024];
            while (true)
            {
                try
                {
                    int bytesRead = stream.Read(buffer, 0, buffer.Length);
                    if (bytesRead == 0) break;

                    string message = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                    Invoke((MethodInvoker)delegate
                    {
                        XtraMessageBox.Show("Server: " + message);
                    });
                }
                catch
                {
                    //Invoke((MethodInvoker)delegate
                    //{
                    //    XtraMessageBox.Show("Server ngắt kết nối.");
                    //});
                    break;
                }
            }
        }
        private void ConnectToServer()
        {
            try
            {
                string ip = "192.168.1.159";
                int port = 8888;

                client = new TcpClient();
                client.Connect(ip, port);
                stream = client.GetStream();

                // HIỂN THỊ THÔNG BÁO KẾT NỐI
                XtraMessageBox.Show($"Đã kết nối đến server {ip}:{port}");

                // === QUAN TRỌNG: KHỞI ĐỘNG THREAD NHẬN TRƯỚC ===
                receiveThread = new Thread(ReceiveData);
                receiveThread.IsBackground = true;
                receiveThread.Start();

                //AppendLog("Đã kết nối và thread nhận tin đã chạy.");

                // === SAU ĐÓ MỚI GỬI TIN NHẮN CHÀO ===
                string computerName = Environment.MachineName;  // Lấy tên máy tính
                SendMessage($"LOGIN|{computerName}");
            }
            catch (Exception ex)
            {
                XtraMessageBox.Show("Lỗi kết nối: " + ex.Message);
            }
        }
