        private void LoadDataModel()
        {
            // Khởi tạo MLContext mới
            var mlContext = new MLContext();

            // Tải mô hình từ file
            ITransformer loadedModel;
            DataViewSchema modelSchema;
            using (var stream = new FileStream("ProductMatchModel.zip", FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                // mlContext.Model.Load() sẽ trả về cả mô hình và bản thiết kế (schema)
                loadedModel = mlContext.Model.Load(stream, out modelSchema);
            }

            // Tạo Prediction Engine từ mô hình đã tải
            var predictionEngine = mlContext.Model.CreatePredictionEngine<ProductPair, ProductPairPrediction>(loadedModel);

            // Sử dụng predictionEngine để kiểm tra
            var testProductPair = new ProductPair
            {
                ProductName1 = "Quả na Thái",
                ProductName2 = "mãng cầu Thái"
            };

            // Luôn tính toán thuộc tính IsIdentical trước khi dự đoán

            TestPrediction(predictionEngine, "Quả na Thái", "mãng cầu Thái");

        }
        private void TrainningData()
        {
            // Khởi tạo MLContext
            var mlContext = new MLContext(seed: 0);

            // Bước 1: Chuẩn bị dữ liệu huấn luyện
            var trainingData = new List<ProductPair>
    {
        new ProductPair { ProductName1 = "Kem đánh răng", ProductName2 = "Kem đánh răng", IsSame = true },
         new ProductPair { ProductName1 = "Kem đánh răng 100g", ProductName2 = "Kem đánh răng 100g", IsSame = true },
         new ProductPair { ProductName1 = "Kem đánh răng 100g", ProductName2 = "Kem đánh răng 200g", IsSame = false },
           new ProductPair { ProductName1 = "Kem đánh răng 200g", ProductName2 = "Kem đánh răng 200g", IsSame = true },
             new ProductPair { ProductName1 = "Kem đánh răng 200g", ProductName2 = "Kem đánh răng 300g", IsSame = false },
    };

            var dataView = mlContext.Data.LoadFromEnumerable(trainingData);

            // Bước 2: Xây dựng Pipeline với cải tiến
            var pipeline = mlContext.Transforms.CopyColumns("Label", "IsSame")
                .Append(mlContext.Transforms.Text.FeaturizeText(
                    outputColumnName: "Features1",
                    inputColumnName: nameof(ProductPair.ProductName1)))
                .Append(mlContext.Transforms.Text.FeaturizeText(
                    outputColumnName: "Features2",
                    inputColumnName: nameof(ProductPair.ProductName2)))
                .Append(mlContext.Transforms.Concatenate(
                    outputColumnName: "Features",
                    "Features1", "Features2"))
                .Append(mlContext.Transforms.NormalizeMinMax("Features"))
                .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
                    labelColumnName: "Label",
                    featureColumnName: "Features"));

            // Bước 3: Huấn luyện mô hình
            var model = pipeline.Fit(dataView);

            // Bước 4: Tạo Prediction Engine
            var predictionEngine = mlContext.Model.CreatePredictionEngine<ProductPair, ProductPairPrediction>(model);

            // Bước 5: Kiểm tra với cặp sản phẩm giống hệt nhau
            var testIdenticalPair = new ProductPair
            {
                ProductName1 = "Áo thun nam",
                ProductName2 = "Áo thun nam"
            };

            var prediction = predictionEngine.Predict(testIdenticalPair);

            Console.WriteLine($"\nSo sánh '{testIdenticalPair.ProductName1}' và '{testIdenticalPair.ProductName2}'");
            Console.WriteLine($"Kết quả dự đoán: {(prediction.Prediction ? "Giống nhau" : "Khác nhau")}");
            Console.WriteLine($"Mức độ tin cậy: {prediction.Probability:P2}");
            Console.WriteLine($"Score: {prediction.Score}");

            // Kiểm tra thêm một số cặp khác
            // 1. Từ đồng nghĩa: thun ↔ phông
            TestPrediction(predictionEngine, "Kem đánh răng 400g", "Kem đánh răng 400g");
            TestPrediction(predictionEngine, "Kem đánh răng 400g", "Kem đánh răng 500g");
            TestPrediction(predictionEngine, "Kem đánh răng", "Kem đánh răng 500g");



            // Lưu mô hình
            Console.WriteLine("Lưu mô hình đã huấn luyện...");
            mlContext.Model.Save(model, dataView.Schema, "ProductMatchModel.zip");
            Console.WriteLine("Đã lưu mô hình thành công tại 'ProductMatchModel.zip'");
        }

        // Hàm hỗ trợ test prediction
        private void TestPrediction(PredictionEngine<ProductPair, ProductPairPrediction> engine, string product1, string product2)
        {
            var testPair = new ProductPair
            {
                ProductName1 = product1,
                ProductName2 = product2
            };

            var prediction = engine.Predict(testPair);

            Console.WriteLine($"\nSo sánh '{product1}' và '{product2}'");
            Console.WriteLine($"Kết quả dự đoán: {(prediction.Prediction ? "Giống nhau" : "Khác nhau")}");
            Console.WriteLine($"Mức độ tin cậy: {prediction.Probability:P2}");
            Console.WriteLine($"Score: {prediction.Score}");
        }
        static string GetChromeVersion()
        {
            // Đường dẫn đến Registry của Google Chrome
            string registryKey = @"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe";

            using (RegistryKey key = Registry.LocalMachine.OpenSubKey(registryKey))
            {
                if (key != null)
                {
                    string chromePath = key.GetValue(string.Empty) as string;
                    if (!string.IsNullOrEmpty(chromePath))
                    {
                        // Lấy phiên bản từ file thực thi
                        var versionInfo = System.Diagnostics.FileVersionInfo.GetVersionInfo(chromePath);
                        return versionInfo.FileVersion;
                    }
                }
            }
            return null;
        }
