        private const string Units = @"ml|cl|dl|l|hl|cm|mm|km|g|kg|mg|t|lb|oz|m|ft|in|yd|mi|s|min|h|d|wk|mo|yr|°C|°F|K|\$|€|£|¥|%|‰";

        private static readonly Regex _unitRx = new Regex(
            $@"(?<=\d)(?:{Units})\b|\b(?:{Units})\b",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        public static string RemoveUnits(string input)
        {
            if (string.IsNullOrWhiteSpace(input)) return input;
            return _unitRx.Replace(input, string.Empty);
        }
