        private void SafeAlterColumn(string table, string column, string newType)
        {
            try
            {
                string sql = string.Format(
                    "ALTER TABLE {0} ALTER COLUMN {1} {2}",
                    table, column, newType
                );

                ExecuteQueryResult(sql);
            }
            catch (Exception ex)
            {
                // GHI LOG, KHÔNG NUỐT
                Console.WriteLine(
                    "Không alter được {0}.{1}: {2}",
                    table, column, ex.Message
                );
            }
        }
                    private bool IsSameAccessType(string accessType, string expectedType)
                    {
                        // DATA_TYPE trong schema là số (OleDbType)
                        // nhưng thường trả về string số → map đơn giản

                        switch (expectedType.ToUpper())
                        {
                            case "DATETIME":
                                return accessType == "7";   // DBTYPE_DATE

                            case "DOUBLE":
                                return accessType == "5";   // DBTYPE_R8

                            case "TEXT":
                                return accessType == "130"; // DBTYPE_WSTR

                            default:
                                return false;
                        }
                    }

                    private void EnsureColumnType(
                 OleDbConnection conn,
                 DataTable schemaColumns,
                 string table,
                 string column,
                 string expectedType)
                    {
                        foreach (DataRow row in schemaColumns.Rows)
                        {
                            if (!row["TABLE_NAME"].ToString()
                                .Equals(table, StringComparison.OrdinalIgnoreCase))
                                continue;

                            if (!row["COLUMN_NAME"].ToString()
                                .Equals(column, StringComparison.OrdinalIgnoreCase))
                                continue;

                            string dataType = row["DATA_TYPE"].ToString();

                            if (IsSameAccessType(dataType, expectedType))
                                return; // ✅ ĐÃ ĐÚNG → KHÔNG LÀM GÌ

                            string sql = $"ALTER TABLE {table} ALTER COLUMN {column} {expectedType}";
                            ExecuteQueryResult(sql, null);
                            return;
                        }
                    }
        private void EnsureColumnTypes(
    OleDbConnection conn,
    DataTable schemaColumns)
