        private void EnsureDbVersionTable(OleDbConnection conn)
        {
            // Kiểm tra bảng DbVersion đã tồn tại chưa
            if (!TableExists(conn, "DbVersion"))
            {
                // Tạo bảng
                ExecuteQueryResult(
                    "CREATE TABLE DbVersion (VersionNumber NUMBER)",
                    null
                );

                // Insert version mặc định = 0
                ExecuteQueryResult(
                    "INSERT INTO DbVersion (VersionNumber) VALUES (0)",
                    null
                );
            }
        }
        private void UpdateDbVersion(OleDbConnection conn, int newVersion)
        {
            OleDbCommand cmd = null;
            try
            {
                cmd = new OleDbCommand(
                    "UPDATE DbVersion SET VersionNumber = ?",
                    conn
                );

                cmd.Parameters.AddWithValue("?", newVersion);
                cmd.ExecuteNonQuery();
            }
            finally
            {
                if (cmd != null)
                    cmd.Dispose();
            }
        }

