        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (client != null && client.Connected)
            {
                try
                {
                    // Gửi tín hiệu bye để server nhận ngay mà không cần đợi
                    string computerName = Environment.MachineName;  // Lấy tên máy tính 
                    byte[] bye = Encoding.UTF8.GetBytes($"BYE|{computerName}");
                    stream.Write(bye, 0, bye.Length);
                    stream.Flush();
                }
                catch { }

                try
                {
                    stream?.Close();
                    client?.Close();
                }
                catch { }
            }

            base.OnFormClosing(e);
        }
        static string ConvertToChrW(string s)
        {
            StringBuilder sb = new StringBuilder();

            for (int i = 0; i < s.Length; i++)
            {
                int code = char.ConvertToUtf32(s, i);

                // nếu ký tự là surrogate pair → nhảy qua
                if (code > 0xFFFF) i++;

                sb.Append("ChrW(");
                sb.Append(code);
                sb.Append(")");

                if (i < s.Length - 1)
                    sb.Append(" & ");
            }

            return sb.ToString();
        }
