        private void XoaNLTP(int index)
        {
            //Thêm repsnsive button cho Import thành phẩm
            RepositoryItemButtonEdit btn2 = new RepositoryItemButtonEdit();

            // ✅ Giữ lại text trong cell
            btn2.TextEditStyle = DevExpress.XtraEditors.Controls.TextEditStyles.Standard;

            // ❌ Xóa nút mặc định
            btn2.Buttons.Clear();

            // ✅ Thêm nút X nhỏ bên phải
            var deleteBtn = new DevExpress.XtraEditors.Controls.EditorButton(
                DevExpress.XtraEditors.Controls.ButtonPredefines.Delete
            );

            deleteBtn.ToolTip = "Xoá";

            // (tuỳ chọn) làm nút nhỏ gọn
            deleteBtn.Width = 20;

            btn2.Buttons.Add(deleteBtn);

            // Gán vào column
            gridView6.Columns[$"nl{index}"].ColumnEdit = btn2;
            btn2.ButtonClick += (s, e2) =>
            {
                int row = gridView6.FocusedRowHandle;
                Nhapkhotp selectedRow = gridView6.GetRow(row) as Nhapkhotp;
                if (row >= 0)
                {
                    //Lấy ID
                    string getTpSoHieu = selectedRow.TenThanhPham.Split('|')[1];
                    var getlsttpnl = existtbNguyenLieuThanhPham.AsEnumerable().Where(m => m.Field<string>("TPSoHieu") == getTpSoHieu && m["stt"].ToString()==index.ToString()).FirstOrDefault();
                    if (getlsttpnl != null)
                    {
                        //Lấy ra danh sách đằng sau nếu có
                        var getListTpAfter = existtbNguyenLieuThanhPham.AsEnumerable().Where(m => m.Field<string>("TPSoHieu") == getTpSoHieu && int.Parse(m["stt"].ToString()) > index).ToList();
                        string qrqd = "delete from tbNguyenLieuThanhPham  WHERE ID=?";
                        var parameters = new OleDbParameter[]
                        {
                            new OleDbParameter("?", getlsttpnl["ID"]),
                        };
                        ExecuteQueryResult(qrqd, parameters);

                        //Thực hiện list đằng sau
                        if (getListTpAfter != null && getListTpAfter.Count > 0)
                        {
                            foreach (var item in getListTpAfter)
                            {
                                string qrqd2 = "update tbNguyenLieuThanhPham set stt=? WHERE ID=?";
                                var parameters2 = new OleDbParameter[]
                                {
                                    new OleDbParameter("?", int.Parse(item["stt"].ToString())-1),
                                    new OleDbParameter("?", item["ID"]),
                                };
                                ExecuteQueryResult(qrqd2, parameters2);
                            }
                        }
                    }
                }
            };
        }
        private void CopyReport()
        {
            string thuMucMang = @"\\192.168.1.90\Ke toan 2025 New\2 Copi vao dung 3\REPORTS";
            string thuMucLocal = savedPath.Replace("Hoadon", "").Trim();
            thuMucLocal=Path.Combine(thuMucLocal, "Reports");
            try
            {
                // Bước 1: Kiểm tra thư mục mạng có tồn tại và truy cập được không
                if (!Directory.Exists(thuMucMang))
                {
                    //MessageBox.Show($"Không thể kết nối đến thư mục mạng:\n{thuMucMang}\n\n" +
                    //                "Kiểm tra lại:\n- Mạng LAN\n- Máy chủ 192.168.1.90 đang bật\n- Quyền truy cập thư mục chia sẻ",
                    //                "Lỗi kết nối", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }

                // Bước 2: Tạo thư mục Reports local nếu chưa có
                if (!Directory.Exists(thuMucLocal))
                {
                    Directory.CreateDirectory(thuMucLocal);
                }

                // Bước 3: Lấy tất cả file .rpt trong thư mục mạng
                string[] fileRptMang = Directory.GetFiles(thuMucMang, "*.rpt", SearchOption.TopDirectoryOnly);

                if (fileRptMang.Length == 0)
                {
                    MessageBox.Show("Không tìm thấy file .rpt nào trong thư mục mạng.", "Thông báo",
                                    MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                // Bước 4: Copy từng file vào thư mục local, ghi đè nếu tồn tại
                int soFileCopy = 0;
                foreach (string filePath in fileRptMang)
                {
                    string fileName = Path.GetFileName(filePath);
                    string destPath = Path.Combine(thuMucLocal, fileName);

                    try
                    {
                        File.Copy(filePath, destPath, true); // true = overwrite (ghi đè)
                        soFileCopy++;
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Lỗi khi copy file {fileName}:\n{ex.Message}", "Lỗi copy",
                                        MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    }
                }

                //MessageBox.Show($"Cập nhật thành công!\nĐã copy {soFileCopy} file .rpt vào thư mục Reports.",
                //                "Thành công", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (UnauthorizedAccessException)
            {
                //MessageBox.Show("Lỗi quyền truy cập!\nBạn không có quyền đọc thư mục mạng hoặc ghi vào thư mục local.\n" +
                //                "Hãy chạy chương trình với quyền Administrator hoặc kiểm tra quyền share.",
                //                "Lỗi quyền", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            catch (Exception ex)
            {
                //MessageBox.Show($"Lỗi không xác định:\n{ex.Message}", "Lỗi",
                //                MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
