        private void TinhLaiSTT(string sohieu)
        {
            CapnhatNguyenlieuthanhphams();
            var getlistnltp = existtbNguyenLieuThanhPham.AsEnumerable().Where(m => m.Field<string>("TPSoHieu") == sohieu).ToList();
            int stt = 1;
            foreach(DataRow row in getlistnltp.OrderBy(m=>m.Field<double>("stt")))
            {
                var updateQr = @"UPDATE tbNguyenLieuThanhPham  SET stt = ? WHERE ID =?";
                var updateParameters = new OleDbParameter[]
                {
        new OleDbParameter("?", stt), // Cập nhật giá trị TiLe
        new OleDbParameter("?", row.Field<int>("ID").ToString()),  

                };
                stt += 1;
                var updateRowsAffected = ExecuteQueryResult(updateQr, updateParameters);
            }
        }
        private void AddButtonColumnNKTP()
        {
            RepositoryItemButtonEdit buttonEdit = new RepositoryItemButtonEdit();
            buttonEdit.Buttons[0].Kind = DevExpress.XtraEditors.Controls.ButtonPredefines.Glyph;
            buttonEdit.Buttons[0].Caption = "Xoá";
            gridView6.Columns["nl1"].ColumnEdit = buttonEdit;
            gridView6.Columns["nl2"].ColumnEdit = buttonEdit;
            gridView6.Columns["nl3"].ColumnEdit = buttonEdit;
            gridView6.Columns["nl4"].ColumnEdit = buttonEdit;
            gridView6.Columns["nl5"].ColumnEdit = buttonEdit;
            buttonEdit.ButtonClick += (sender, e) =>
            {
                GridView grv = gridControl4.MainView as GridView;
                int rowHandle = grv.FocusedRowHandle;
                if (rowHandle >= 0)
                {
                    if (grv.GetRowCellValue(rowHandle, grv.FocusedColumn.FieldName) == null)
                        return;
                    //Xoá nguyên liệu thành phẩm nếu có
                    string getcurrentdat = grv.GetRowCellValue(rowHandle, grv.FocusedColumn.FieldName).ToString();
                    string sohieu = grv.GetRowCellValue(rowHandle, "TenThanhPham").ToString().Split('|')[1];
                    var queryDelete = @"DELETE FROM tbNguyenLieuThanhPham WHERE TPSoHieu=? and SoHieuNguyenLieu=?";
                    var parametersDelete = new OleDbParameter[]
                    {
                                    new OleDbParameter("?",sohieu),
                                     new OleDbParameter("?",getcurrentdat)
                    };
                    var result = ExecuteQueryResult(queryDelete, parametersDelete); // Xóa trong database
                    TinhLaiSTT(sohieu);

                    // Lấy tên cột (ví dụ cột đầu tiên)
                    string columnName = grv.FocusedColumn.FieldName;
                    Nhapkhotp dt = grv.GetRow(rowHandle) as Nhapkhotp;
                    // Mảng để chứa tên các trường
                    // Mảng để chứa tên các trường
                    // Mảng để chứa tên các trường
                    // Mảng để chứa tên các trường
                    var fieldNames = new[] { "nl1", "nl2", "nl3", "nl4", "nl5" };
                    var psNames = new[] { "ps1", "ps2", "ps3", "ps4", "ps5" };
                    var dgNames = new[] { "dg1", "dg2", "dg3", "dg4", "dg5" };

                    // Lặp qua các trường
                    for (int i = 0; i < fieldNames.Length; i++)
                    {
                        if (columnName == fieldNames[i])
                        {
                            // Nếu trường hiện tại không phải là trường cuối cùng
                            for (int j = i; j < fieldNames.Length - 1; j++)
                            {
                                // Gán giá trị từ trường kế tiếp cho trường hiện tại
                                dt.GetType().GetProperty(fieldNames[j]).SetValue(dt, dt.GetType().GetProperty(fieldNames[j + 1]).GetValue(dt));
                                dt.GetType().GetProperty(psNames[j]).SetValue(dt, dt.GetType().GetProperty(psNames[j + 1]).GetValue(dt));
                                dt.GetType().GetProperty(dgNames[j]).SetValue(dt, dt.GetType().GetProperty(dgNames[j + 1]).GetValue(dt));
                            }

                            // Gán giá trị mặc định cho trường cuối cùng
                            dt.GetType().GetProperty(fieldNames[fieldNames.Length - 1]).SetValue(dt, ""); // Trường cuối cùng được gán giá trị rỗng
                            dt.GetType().GetProperty(psNames[psNames.Length - 1]).SetValue(dt, 0);
                            dt.GetType().GetProperty(dgNames[dgNames.Length - 1]).SetValue(dt, 0);
                        }
                    }
                    gridView6.RefreshData();
                  
                }


            };
        }
