        private void Capnhatnguyenlieuthanhpham()
        {
            string queryct = "SELECT * FROM tbNguyenLieuThanhPham"; // Giả sử bạn muốn lấy tất cả dữ liệu từ bảng KhachHang
            existtbNguyenLieuThanhPham = ExecuteQuery(queryct);
            //Kiểm tra xem co phải lần đầu import
           
            //SẮp xếp và group by theo ngày
            //Lọc ra danh sách thành phẩm
            var lastInvoices = existingTbChungtu
            .AsEnumerable()
            .Where(m => m.Field<string>("DienGiai").Contains("Xuaát nguyeân lieäu") || m.Field<string>("DienGiai").Contains("Xuaát kho nguyeân lieäu"))
            .GroupBy(m => m.Field<int>("MaTP")) // Nhóm theo MaTP
            .Select(g => g.OrderByDescending(m => m.Field<DateTime>("NgayCT")) // Sắp xếp theo ngày chứng từ
                           .FirstOrDefault()) // Lấy hóa đơn mới nhất
            .ToList();
            if (lastInvoices.Count > 0)
            {
                foreach(var item in lastInvoices)
                {
                    string sohieu = "";
                    try
                    {
                         sohieu = item["SoHieu"].ToString();
                        if(sohieu== "XVT1/41")
                        {
                            int a = 10;
                        }
                        int matp = item.Field<int>("MaTP");
                        //Tìm thành phẩm từ mã công trình
                        var findtp = existingTbChungtu
                .AsEnumerable()
                 .Where(m => (m.Field<string>("DienGiai").Contains("Nhaäp kho") || m.Field<string>("DienGiai").Contains("Nhaïp kho")) && m.Field<int>("MaTP") == matp).LastOrDefault();
                        if (findtp == null)
                            continue;
                        int idthanhpham = findtp.Field<int>("MaVattu");
                        //Tìm so hiệu thành phẩm
                        string sohieutp = lstvt.Where(m => m.MaSo == idthanhpham).FirstOrDefault().SoHieu;

                        //Tìm các rows của hoá đơn này
                        var getlisthd = existingTbChungtu.AsEnumerable().Where(m => m.Field<string>("SoHieu") == sohieu).ToList();
                        //Tìm thành phẩm 
                        double sumTP = getlisthd.Sum(m => m.Field<double>("SoPS"));
                        double totalpercent = 100;
                        double tile = 0;
                        List<string> lstsohieu = new List<string>();
                        foreach (var it in getlisthd)
                        {

                            var index = getlisthd.IndexOf(it);
                            //Tìm nguyên liệu
                            var findnl = lstvt.Where(m => m.MaSo == it.Field<int>("MaVattu")).FirstOrDefault();
                           
                            if (lstsohieu.Any(m =>m == findnl.SoHieu))
                                continue;
                            lstsohieu.Add(findnl.SoHieu);
                            //Tính tỷ lệ %
                            double currentsosp = it.Field<double>("SoPS");

                            if (index < (getlisthd.Count() - 1))
                            {
                                tile = Math.Round(currentsosp / sumTP * 100);
                                totalpercent -= tile;
                            }
                            else
                                tile = totalpercent;

                          
                            string query = "INSERT INTO tbNguyenLieuThanhPham(TPSoHieu,IDNguyenLieu,SoHieuNguyenLieu,TiLe)  VALUES(?,?,?,?,?)";

                            var parameters = new OleDbParameter[]
                            {
                                 new OleDbParameter("?",sohieutp),
                                 new OleDbParameter("?",findnl.MaSo),
                                 new OleDbParameter("?",findnl.SoHieu),
                                 new OleDbParameter("?","0"),
                                 new OleDbParameter("?","0"),
                            };
                            try
                            {
                                ExecuteQueryResult(query, parameters);
                            }
                            catch (Exception ex)
                            {
                                XtraMessageBox.Show(ex.Message);
                            }

                            //Kiểm tra xem đã có nguyên liệu hay chưa
                        }
                    }
                    catch(Exception ex)
                    {
                        XtraMessageBox.Show(ex.Message +"   "+ sohieu);
                    }
                 
                }
            }
        }
