                    {
                        xmlDoc.Load(reader); // Tải file XML
                    }
                    catch (XmlException ex)
                    {
                        Console.WriteLine($"Lỗi khi tải file XML: {ex.Message}");
                        return;
                    }
                    XmlNode root = xmlDoc.DocumentElement;
                    XmlNode nTTChungNode = root.SelectSingleNode("//TTChung");
