                        parameters = new OleDbParameter[]
               {
        new OleDbParameter("TKNo", detail.TKNo),   // Đặt tên tham số rõ ràng
        new OleDbParameter("TKCo", detail.TKCo),   // Đặt tên tham số rõ ràng
        new OleDbParameter("ParentId", detail.ID),  // Đặt tên tham số rõ ràng
         new OleDbParameter("TKNo", "711")   // Đặt tên tham số rõ ràng
               };

                        try
