        private void UpdateMatdinhOptimized(FileImport item, OleDbConnection conn, OleDbTransaction tran)
        {
            // 1. Cập nhật master (tbimport)
                string queryMaster = @"
            UPDATE tbimport
            SET TKNo = ?, TKCo = ?, Noidung = ?, Macdinhstatus = ?
            WHERE ID = ?";

            using (var cmd = new OleDbCommand(queryMaster, conn, tran))
            {
                cmd.Parameters.AddWithValue("TKNo", item.TKNo);
                cmd.Parameters.AddWithValue("TKCo", item.TKCo);
                cmd.Parameters.AddWithValue("Noidung", Helpers.ConvertUnicodeToVni(item.Noidung));
                cmd.Parameters.AddWithValue("Macdinhstatus", "1");
                cmd.Parameters.AddWithValue("ID", item.ID);
                cmd.ExecuteNonQuery();
            }

            // 2. Cập nhật tất cả chi tiết trong 1 query (batch update)
            foreach (var it in item.fileImportDetails)
            {
                // Chỉ update nếu chi tiết đã có TKCo (theo logic cũ)
                if (string.IsNullOrEmpty(it.TKCo)) continue;
                string queryDetail = @"
                UPDATE tbimportdetail d
                SET d.TKNo = ?, d.TKCo = ?
                WHERE d.ID = ?";

                using (var cmd = new OleDbCommand(queryDetail, conn, tran))
                {
                    cmd.Parameters.AddWithValue("TKNo", it.TKNo);  // tất cả chi tiết dùng cùng TKNo
                    cmd.Parameters.AddWithValue("TKCo", it.TKCo);  // cùng TKCo
                    cmd.Parameters.AddWithValue("ParentID", it.ID);

                    cmd.ExecuteNonQuery(); // Cập nhật tất cả chi tiết cùng lúc
                }
            }
        }
        private void ApplyDefaultAndRuleBasedAccountsNew(FileImport item, System.Data.DataTable dinhDanhChung, System.Data.DataTable dinhDanhUuTien, int Loai)
        { // Tạo transaction
           
            Application.DoEvents();
            dinhDanhChung = dinhDanhChung.AsEnumerable().Where(m => m.Field<string>("Loai") == Loai.ToString()).CopyToDataTable();
            using (var connection = new OleDbConnection(connectionString))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    try
                    {
                        foreach (DataRow row in dinhDanhChung.Rows)
                        {
                            string keyValue = row.Field<string>("KeyValue");
                            string uTkNo = row.Field<string>("TKNo");
                            string uTkCo = row.Field<string>("TKCo");

                            bool isPriorityIn = item.Type == 1 && keyValue.Contains("Ưu tiên vào");
                            bool isPriorityOut = item.Type == 2 && keyValue.Contains("Ưu tiên ra");

                            if (!isPriorityIn && !isPriorityOut) continue;

                            bool changed = false;

                            if (item.TKNo != uTkNo)
                            {
                                item.TKNo = uTkNo;
                                changed = true;
                            }
                            if (item.TKCo != uTkCo)
                            {
                                item.TKCo = uTkCo;
                                changed = true;
                            }

                            if (!changed) continue;

                            // Cập nhật master và tất cả chi tiết trong 1 transaction
                            UpdateMatdinhOptimized(item, connection, transaction);
                        }

                        transaction.Commit();
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        XtraMessageBox.Show("Lỗi: " + ex.Message, "Lỗi", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                }
            }
            return;
            if (item.Macdinhstatus == "1")
                return;
            foreach (DataRow row in dinhDanhChung.Rows)
            {
                if (row.Field<string>("Loai") != Loai.ToString())
                {
                    continue;
                }
                string keyvalue = row.Field<string>("KeyValue");
                if (!keyvalue.Contains("Ưu tiên vào") && !keyvalue.Contains("Ưu tiên ra"))
                {
                    string uTkNo = row.Field<string>("TKNo");
                    string uTkCo = row.Field<string>("TKCo");
                    string Noidung = row.Field<string>("Type");
                    bool changeData = false;
                    //Loc split
                    var getNd = keyvalue.ToLower().Split(',').ToList();
                    foreach (var md in getNd)
                    {
                        if ((item.Noidung != null && item.Noidung.ToLower().Contains(md)) || item.fileImportDetails.Any(m => m.Ten.ToLower().Contains(md)))
                        {
                            if (item.Noidung != null && item.Noidung.ToLower().Contains(md))
                            {
                                item.TKNo = uTkNo;
                                item.TKCo = uTkCo;

                                if (!string.IsNullOrEmpty(Noidung))
                                {
                                    item.Noidung = Noidung;
                                }

                            }
                            foreach (var it in item.fileImportDetails)
                            {
                                if (it.ID == 1879)
                                {
                                    int a = 10;
                                }
                                if (it.Ten.ToLower().Contains(md.ToLower()))
                                {
                                    it.TKNo = uTkNo;
                                    it.TKCo = uTkCo;
                                    it.IsMacdinh = 1;
                                }
                                else
                                {
                                    if (it.TKNo != "5211" && !it.TKNo.StartsWith("51") && it.IsMacdinh == 0)
                                    {
                                        it.TKNo = item.TKNo;
                                        it.TKCo = item.TKCo;
                                    }
                                }
                            }

                            changeData = true;
                            UpdateMatdinh(item);
                        }
                    }
                    //Trường hợp ko có từ khoá, tìm theo MST
                    if (changeData == false)
                    {
                        foreach (var md in getNd)
                        {
                            if (item.Mst == md)
                            {
                                item.TKNo = uTkNo;
                                item.TKCo = uTkCo;
                                foreach (var it in item.fileImportDetails)
                                {
                                    it.TKNo = item.TKNo;
                                    it.TKCo = item.TKCo;
                                }
                                if (!string.IsNullOrEmpty(Noidung))
                                {
                                    item.Noidung = Noidung;
                                }
                                UpdateMatdinh(item);
                            }
                        }
                    }
                }
            }


            return;
           
            foreach (DataRow row in dinhDanhChung.Rows)
            {
                string[] conditions = row["KeyValue"].ToString().Split('&');
                int hasMatch = 0;
                foreach (string condition in conditions)
                {
                    string[] parts = Regex.Split(condition, @"([><=%]+)");
                    if (parts.Length == 3)
                    {
                        string key = parts[0];
                        string operatorStr = parts[1];
                        string valueStr = parts[2].Trim('"');
                        string chuoiBinhThuong = Helpers.ConvertUnicodeToVni(valueStr);

                        foreach (var detail in item.fileImportDetails)
                        {
                            if (key == "Ten" && !string.IsNullOrEmpty(detail.Ten) && detail.Ten.IndexOf(chuoiBinhThuong, StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                hasMatch++;
                                break; // Chỉ cần một chi tiết thỏa mãn
                            }
                        }
                        if (key == "TongTien" && double.TryParse(valueStr, out var val) && EvaluateCondition(item.TongTien, operatorStr, val))
                        {
                            hasMatch++;
                        }
                        if (key == "MST" && item.Mst?.Equals(valueStr, StringComparison.OrdinalIgnoreCase) == true)
                        {
                            hasMatch++;
                        }
                        if (key == "Ghichu")
                        {
                            //
                            var getNd = valueStr.ToLower().Split(',').ToList();
                            foreach (var md in getNd)
                            {
                                if (item.Noidung.ToLower().Contains(md))
                                {
                                    hasMatch++;
                                }
                            }

                        }
                    }
                }

                if (hasMatch == conditions.Length)
                {
                    item.TKNo = row["TKNo"].ToString();
                    item.TKCo = row["TKCo"].ToString();
                    item.TkThue = int.Parse(row["TkThue"].ToString());
                    if (conditions.Any(c => c.StartsWith("MST")) && item.TKNo.Contains("642"))
                    {
                        item.Noidung = row["Type"].ToString();
                    }
                    if (conditions.Any(c => c.StartsWith("Ghichu")))
                    {
                        item.Noidung = row["Type"].ToString();
                    }
                    //Cập nhật database
                    string query = @"UPDATE tbimport SET TKNo=?,TKCo=?,Noidung=?  WHERE ID=?";
                    var parameters = new OleDbParameter[]
             {
                                new OleDbParameter("?",item.TKNo),
                                   new OleDbParameter("?",item.TKCo),
                                   new OleDbParameter("?",Helpers.ConvertUnicodeToVni(item.Noidung)),
                                   new OleDbParameter("?",item.ID),
             };
                    int rowsAffected = ExecuteQueryResult(query, parameters);
                    //Cap nhat con
                    query = @"UPDATE tbimportdetail SET TKNo=?,TKCo=?  WHERE ParentId=?";
                    parameters = new OleDbParameter[]
            {
                                new OleDbParameter("?",item.TKNo),
                                   new OleDbParameter("?",item.TKCo),
                                   new OleDbParameter("?",item.ID),
            };
                    rowsAffected = ExecuteQueryResult(query, parameters);
                    return; // Tìm thấy quy tắc phù hợp, thoát
                }
            }
            // Áp dụng quy tắc ưu tiên
            if (dinhDanhUuTien.Rows.Count > 0)
            {
                foreach (DataRow row in dinhDanhUuTien.Rows)
                {
                    if (string.IsNullOrEmpty(item.TKNo) || item.TKNo == "0") item.TKNo = row["TKNo"].ToString();
                    if (string.IsNullOrEmpty(item.TKCo) || item.TKCo == "0") item.TKCo = row["TKCo"].ToString();
                    if (item.TkThue == 0) item.TkThue = int.Parse(row["TkThue"].ToString());
                    if (item.TKNo == "331")
                    {
                        // Ví dụ về logic đặc biệt cho TKNo = 331
                        // item.TKNo = "711";
                        // item.TKCo = "3311";
                    }
                }
            }
        }
        private void ApplyDefaultAndRuleBasedAccounts(FileImport item, System.Data.DataTable dinhDanhChung, System.Data.DataTable dinhDanhUuTien,int Loai)
        {
            if (item.Macdinhstatus == "1")
                return;
            foreach (DataRow row in dinhDanhChung.Rows)
            {
                if (row.Field<string>("Loai") != Loai.ToString())
                {
                    continue;
                }
                string keyvalue = row.Field<string>("KeyValue");
                if (!keyvalue.Contains("Ưu tiên vào") && !keyvalue.Contains("Ưu tiên ra"))
                {
                    string uTkNo = row.Field<string>("TKNo");
                    string uTkCo = row.Field<string>("TKCo");
                    string Noidung = row.Field<string>("Type");
                    bool changeData = false;
                    //Loc split
                    var getNd = keyvalue.ToLower().Split(',').ToList();
                    foreach (var md in getNd)
                    {
                        if ((item.Noidung != null && item.Noidung.ToLower().Contains(md)) || item.fileImportDetails.Any(m=>m.Ten.ToLower().Contains(md)))
                        {
                            if(item.Noidung != null && item.Noidung.ToLower().Contains(md)){
                                item.TKNo = uTkNo;
                                item.TKCo = uTkCo;
                               
                                if (!string.IsNullOrEmpty(Noidung))
                                {
                                    item.Noidung = Noidung;
                                }

                            }
                            foreach (var it in item.fileImportDetails)
                            {
                                if(it.ID== 1879)
                                {
                                    int a = 10;
                                }
                                if (it.Ten.ToLower().Contains(md.ToLower()))
                                {
                                    it.TKNo = uTkNo;
                                    it.TKCo = uTkCo;
                                    it.IsMacdinh = 1;
                                }
                                else
                                {
                                    if (it.TKNo != "5211" && !it.TKNo.StartsWith("51") && it.IsMacdinh==0)
                                    {
                                        it.TKNo = item.TKNo;
                                        it.TKCo = item.TKCo;
                                    }
                                }
                            }

                            changeData = true;
                            UpdateMatdinh(item);
                        }
                    }
                    //Trường hợp ko có từ khoá, tìm theo MST
                    if (changeData == false)
                    {
                        foreach (var md in getNd)
                        {
                            if (item.Mst == md)
                            {
                                item.TKNo = uTkNo;
                                item.TKCo = uTkCo;
                                foreach (var it in item.fileImportDetails)
                                {
                                    it.TKNo = item.TKNo;
                                    it.TKCo = item.TKCo;
                                }
                                if (!string.IsNullOrEmpty(Noidung))
                                {
                                    item.Noidung = Noidung;
                                }
                                UpdateMatdinh(item);
                            }
                        }
                    }
                }
            }


            return;
            foreach (DataRow row in dinhDanhChung.Rows)
            {
                //Xử lý từ khoá, nếu có rồi thì thôi

                //Xử lý ưu tiên ra vào, ra
                string keyvalue = row.Field<string>("KeyValue");
                if ((item.Type == 1 && keyvalue.Contains("Ưu tiên vào")) || (item.Type == 2 && keyvalue.Contains("Ưu tiên ra")))
                {
                    //Lấy tkNo, tkco
                    string uTkNo = row.Field<string>("TKNo");
                    string uTkCo = row.Field<string>("TKCo");
                    bool changeData = false;
                    if (item.TKNo != uTkNo)
                    {
                        item.TKNo = uTkNo;
                        foreach (var it in item.fileImportDetails)
                        {
                            it.TKNo = item.TKNo;
                        }
                        changeData = true;
                    }
                    if (item.TKCo != uTkCo)
                    {
                        item.TKCo = uTkCo;
                        foreach (var it in item.fileImportDetails)
                        {
                            it.TKCo = item.TKCo;
                        }
                        changeData = true;
                    }
                    if (changeData)
                        UpdateMatdinh(item);
                }
            }
            foreach (DataRow row in dinhDanhChung.Rows)
            {
                string[] conditions = row["KeyValue"].ToString().Split('&');
                int hasMatch = 0;
                foreach (string condition in conditions)
                {
                    string[] parts = Regex.Split(condition, @"([><=%]+)");
                    if (parts.Length == 3)
                    {
                        string key = parts[0];
                        string operatorStr = parts[1];
                        string valueStr = parts[2].Trim('"');
                        string chuoiBinhThuong = Helpers.ConvertUnicodeToVni(valueStr);

                        foreach (var detail in item.fileImportDetails)
                        {
                            if (key == "Ten" && !string.IsNullOrEmpty(detail.Ten) && detail.Ten.IndexOf(chuoiBinhThuong, StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                hasMatch++;
                                break; // Chỉ cần một chi tiết thỏa mãn
                            }
                        }
                        if (key == "TongTien" && double.TryParse(valueStr, out var val) && EvaluateCondition(item.TongTien, operatorStr, val))
                        {
                            hasMatch++;
                        }
                        if (key == "MST" && item.Mst?.Equals(valueStr, StringComparison.OrdinalIgnoreCase) == true)
                        {
                            hasMatch++;
                        }
                        if (key == "Ghichu")
                        {
                            //
                            var getNd = valueStr.ToLower().Split(',').ToList();
                            foreach (var md in getNd)
                            {
                                if (item.Noidung.ToLower().Contains(md))
                                {
                                    hasMatch++;
                                }
                            }

                        }
                    }
                }

                if (hasMatch == conditions.Length)
                {
                    item.TKNo = row["TKNo"].ToString();
                    item.TKCo = row["TKCo"].ToString();
                    item.TkThue = int.Parse(row["TkThue"].ToString());
                    if (conditions.Any(c => c.StartsWith("MST")) && item.TKNo.Contains("642"))
                    {
                        item.Noidung = row["Type"].ToString();
                    }
                    if (conditions.Any(c => c.StartsWith("Ghichu")))
                    {
                        item.Noidung = row["Type"].ToString();
                    }
                    //Cập nhật database
                    string query = @"UPDATE tbimport SET TKNo=?,TKCo=?,Noidung=?  WHERE ID=?";
                    var parameters = new OleDbParameter[]
             {
                                new OleDbParameter("?",item.TKNo),
                                   new OleDbParameter("?",item.TKCo),
                                   new OleDbParameter("?",Helpers.ConvertUnicodeToVni(item.Noidung)),
                                   new OleDbParameter("?",item.ID),
             };
                    int rowsAffected = ExecuteQueryResult(query, parameters);
                    //Cap nhat con
                    query = @"UPDATE tbimportdetail SET TKNo=?,TKCo=?  WHERE ParentId=?";
                    parameters = new OleDbParameter[]
            {
                                new OleDbParameter("?",item.TKNo),
                                   new OleDbParameter("?",item.TKCo),
                                   new OleDbParameter("?",item.ID),
            };
                    rowsAffected = ExecuteQueryResult(query, parameters);
                    return; // Tìm thấy quy tắc phù hợp, thoát
                }
            }
            // Áp dụng quy tắc ưu tiên
            if (dinhDanhUuTien.Rows.Count > 0)
            {
                foreach (DataRow row in dinhDanhUuTien.Rows)
                {
                    if (string.IsNullOrEmpty(item.TKNo) || item.TKNo == "0") item.TKNo = row["TKNo"].ToString();
                    if (string.IsNullOrEmpty(item.TKCo) || item.TKCo == "0") item.TKCo = row["TKCo"].ToString();
                    if (item.TkThue == 0) item.TkThue = int.Parse(row["TkThue"].ToString());
                    if (item.TKNo == "331")
                    {
                        // Ví dụ về logic đặc biệt cho TKNo = 331
                        // item.TKNo = "711";
                        // item.TKCo = "3311";
                    }
                }
            }
        }
