        public async Task GetdetailXML3(string nbmst, string khhdon, string shdon, string token, int invoiceType, FileImport fileImport, string Khmshdon)
        {
            string url = GetInvoiceUrl(invoiceType, nbmst, khhdon, shdon, Khmshdon);
            string pathravao = fileImport.Type == 1 ? "HDVao" : "HDRa";
            string filename = $"{fileImport.SHDon}_{fileImport.KHHDon}.zip";
            string path = Path.Combine(savedPath, pathravao, fileImport.NLap.Month.ToString(), filename);

            using (var client = new HttpClient())
            {
                client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token);
                client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/octet-stream"));

                try
                {
                    await Task.Delay(300); // Thay thế Thread.Sleep bằng Task.Delay

                    HttpResponseMessage response = await client.GetAsync(url);
                    response.EnsureSuccessStatusCode(); // Ném ngoại lệ nếu không thành công

                    // Đọc nội dung phản hồi dưới dạng byte
                    var fileBytes = await response.Content.ReadAsByteArrayAsync();

                    // Lưu file ZIP bằng FileStream
                    using (var fileStream = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize: 4096, useAsync: true))
                    {
                        await fileStream.WriteAsync(fileBytes, 0, fileBytes.Length);
                    }

                    Console.WriteLine($"File ZIP đã được lưu tại: {path}");
                    ExtractZipXML(path, fileImport); // Giải nén file ZIP
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Đã xảy ra lỗi: {ex.Message}");
                }
            }
        }

