        // Hàm hỗ trợ tính điểm khớp (giữ nguyên như cũ của bạn)
        private double CalculateMatchScore(dynamic vt, string tenSP)
        {
            if (string.IsNullOrEmpty(tenSP)) return 0;
            string a = Helpers.RemoveVietnameseDiacritics(vt.TenVattu?.ToString() ?? "").ToLower().Replace(".", " ").Replace("-", " ");
            string b = Helpers.RemoveVietnameseDiacritics(Helpers.NormalizeVietnameseString(tenSP)).ToLower().Replace(".", " ").Replace("-", " ");

            int fuzzScore = Fuzz.Ratio(a, b);
            double levScore = CalculateSimilarity(a, b);

            // Ưu tiên tên phụ nếu có
            if (fuzzScore < 100 && vt.TenVattu2 != null)
            {
                string a2 = Helpers.RemoveVietnameseDiacritics(vt.TenVattu2.ToString()).ToLower();
                int fuzz2 = Fuzz.Ratio(a2, b);
                if (fuzz2 > fuzzScore) fuzzScore = fuzz2;
            }

            return 0.7 * fuzzScore + 0.3 * levScore;
        }


        public void GetdetailXML2(string nbmst, string khhdon, string shdon, string tokken, int invoiceType, FileImport fileImport, string khmshdon)
        {
            if (string.IsNullOrEmpty(khmshdon))
                khmshdon = "1";
            string mst = "";
            if (string.IsNullOrEmpty(CCCD) || CCCD == "...")
            {
                mst = nbmst;
            }
            else
            {
                mst = CCCD;
            }
            string url = "";
            if (invoiceType == 4 || invoiceType == 6 || invoiceType == 8)
                url = $"https://hoadondientu.gdt.gov.vn/query/invoices/detail?nbmst={nbmst}&khhdon={khhdon}&shdon={shdon}&khmshdon={khmshdon}";
            if (invoiceType == 5 || invoiceType == 10)
                url = $"https://hoadondientu.gdt.gov.vn/sco-query/invoices/detail?nbmst={mst}&khhdon={khhdon}&shdon={shdon}&khmshdon={khmshdon}";
            using (var client = new WebClient())
            {
                client.Encoding = Encoding.UTF8;
                client.Headers[HttpRequestHeader.Authorization] = "Bearer " + tokken;
                client.Headers[HttpRequestHeader.Accept] = "application/json; charset=utf-8";
                client.Headers[HttpRequestHeader.ContentType] = "application/json; charset=utf-8";
                // client.Timeout = TimeSpan.FromSeconds(10); // Ví dụ: 30 giây

                string responseBody = "";
                int retryCount = 0;
                const int maxRetries = 3;

                while (retryCount < maxRetries)
                {
                    try
                    {
                        // Download string đồng bộ - không async
                        responseBody = client.DownloadString(url);

                        // Kiểm tra status code (WebClient ném exception cho lỗi HTTP)
                        break; // Thành công, thoát vòng lặp
                    }
                    catch (WebException ex) when ((ex.Response as HttpWebResponse)?.StatusCode == HttpStatusCode.InternalServerError)
                    {
                        retryCount++;
                        Thread.Sleep(400); // Thay Task.Delay bằng Thread.Sleep
                        Console.WriteLine($"Lỗi 500, thử lại lần {retryCount}...");
                        if (retryCount >= maxRetries)
                            throw;
                    }
                    catch (Exception ex)
                    {
                        // Xử lý các exception khác
                        if (retryCount >= maxRetries - 1)
                        {
                           // XtraMessageBox.Show(ex.Message);
                        }
                        retryCount++;
                        Thread.Sleep(400);
                    }
                }
                var rootObject = JsonConvert.DeserializeObject<Invoice>(responseBody);
                VietnameseProductMatcher vietnameseProductMatcher = new VietnameseProductMatcher();
                if (rootObject == null)
