        private async Task TainewData2()
        {
           
            // 1. Khởi tạo danh sách
            if (taihoddon)
            {
                taihoddon = false;
            }
            else
            {
                lstdsVao = new List<TbImport>();
                lstdsRa = new List<TbImport>();
            }

            string pathType = chkDauvao.Checked ? "HDVao" : "HDRa";
            int fromMonth = dtTungay.DateTime.Month;
            int toMonth = dtDenngay.DateTime.Month;

            List<string> allFiles = new List<string>();
            string pathYear = $"HD{dtTungay.DateTime.Year}";
            // 2. Gom tất cả file XML
            for (int m = fromMonth; m <= toMonth; m++)
            {
                string monthFolder = Path.Combine(savedPath, pathYear, pathType, m.ToString());
                // Kiểm tra xem folder có tồn tại
                try
                {
                    if (Directory.Exists(monthFolder))
                    {
                        // Kiểm tra xem có thư mục nào trong thư mục tháng
                        string[] directories = Directory.GetDirectories(monthFolder);
                        if (directories.Length > 0)
                        {
                            // Nếu có thư mục, xóa tất cả
                            foreach (string dir in directories)
                            {
                                Directory.Delete(dir, true); // true để xóa toàn bộ nội dung
                                Console.WriteLine($"Đã xóa thư mục: {dir}");
                            }
                            // Có thể xóa cả monthFolder nếu muốn
                            // Directory.Delete(monthFolder, true); 
                        }
                        else
                        {
                            Console.WriteLine("Không có thư mục nào bên trong thư mục tháng.");
                        }
                        // Tìm và xóa các file .rar trong monthFolder
                        string[] rarFiles = Directory.GetFiles(monthFolder, "*.zip", SearchOption.TopDirectoryOnly);
                        if (rarFiles.Length > 0)
                        {
                            foreach (string rarFile in rarFiles)
                            {
                                File.Delete(rarFile);
                                Console.WriteLine($"Đã xóa file: {rarFile}");
                            }
                        }
                        else
                        {
                            Console.WriteLine("Không có file .rar nào trong thư mục tháng.");
                        }
                    }
                }
                catch(Exception ex)
                {
                  
                }   

                if (Directory.Exists(monthFolder))
                {
                    var filesInMonth = Directory.GetFiles(monthFolder, "*.xml", SearchOption.TopDirectoryOnly);
                    allFiles.AddRange(filesInMonth);
                }
            }

            tongfile = allFiles.Count;
            sothutu = 1;
            if (tongfile == 0)
            {
                XtraMessageBox.Show("Đã hoàn thành tải hóa đơn");
                return;
            }
            // Danh sách tạm để gom hàng lưu vào DB
            List<TbImport> allInvoicesToSave = new List<TbImport>();

            // 3. XỬ LÝ SONG SONG THEO BATCH
                int batchSize = 10;
                for (int i = 0; i < allFiles.Count; i += batchSize)
                {
                    var batch = allFiles.Skip(i).Take(batchSize);

                    // Tạo các task đọc file
                    var tasks = batch.Select(file => DocfileXmlOne(file, 1));

                    // --- ĐOẠN QUAN TRỌNG: Hứng kết quả từ các file vừa đọc ---
                    TbImport[] results = await Task.WhenAll(tasks);

                    foreach (var item in results)
                    {
                        if (item != null) // Chỉ lấy những file bóc tách thành công và không trùng
                        {
                            allInvoicesToSave.Add(item);

                            // Cập nhật vào danh sách hiển thị trên giao diện (Grid)
                            if (chkDauvao.Checked) lstdsVao.Add(item);
                            else lstdsRa.Add(item);
                        }
                    }

                    // Cập nhật UI
                    Application.DoEvents();
                }

            // 4. LƯU HÀNG LOẠT (Chỉ gọi 1 lần duy nhất sau khi xong vòng lặp)
            if (allInvoicesToSave.Count > 0)
            {
                await SaveAllInvoicesBulk(allInvoicesToSave, chkDauvao.Checked ? 1 : 2);

            }
            else
            {
                if(chkDauvao.Checked)
                {
                    if (lstImportVao.Count == 0)
                        XtraMessageBox.Show("Đã hoàn thành tải hóa đơn");
                }
                else
                {
                    if (lstImportRa.Count == 0)
                        XtraMessageBox.Show("Đã hoàn thành tải hóa đơn");
                }
                   
            }
        }
        private async Task SaveAllInvoicesBulk(List<TbImport> invoices, int type)
        {
            XtraMessageBox.Show("Đã vào hàm SaveAllInvoicesBulk");

            using (SqlConnection conn = new SqlConnection(connectionStringSQL))
            {
                XtraMessageBox.Show("Đã tạo SqlConnection");

                await conn.OpenAsync();
                using (SqlTransaction trans = conn.BeginTransaction())
                {
                    try
                    {
                        string sqlParent = @"INSERT INTO tbImport (SHDon, KHHDon, NLap, Ten, Noidung, TKNo, TKCo, TkThue, Mst, [Status], Ngaytao, TongTien, Vat, TPhi, TgTCThue, TgTThue, [Type], InvoiceType, IsHaschild, TVat, Vat2, TVat2, Vat3, TVat3, TgTCThue1, TgTCThue2, TgTCThue3, Khmshdon, hdon, [Path]) 
                              VALUES (@SHDon, @KHHDon, @NLap, @Ten, @Noidung, @TKNo, @TKCo, @TkThue, @Mst, @Status, @Ngaytao, @TongTien, @Vat, @TPhi, @TgTCThue, @TgTThue, @Type, @InvoiceType, @IsHaschild, @TVat, @Vat2, @TVat2, @Vat3, @TVat3, @TgTCThue1, @TgTCThue2, @TgTCThue3, @Khmshdon, @hdon, @Path)";

                        string sqlDetail = @"INSERT INTO tbimportdetail (ParentId, SoHieu, SoLuong, DonGia, DVT, Ten, MaCT, TKNo, TKCo, TTien, [Percent], Tchat, SoPSGoc, VAT) 
                              VALUES (@ParentId, @SoHieu, @SoLuong, @DonGia, @DVT, @Ten, @MaCT, @TKNo, @TKCo, @TTien, @Percent, @Tchat, @SoPSGoc, @VAT)";

                        string sqlGetIdentity = "SELECT SCOPE_IDENTITY()";

                        foreach (var item in invoices)
                        {
                            int parentID = 0;

                            // 1. Lưu Hóa đơn chính (Parent)
                            using (SqlCommand cmdParent = new SqlCommand(sqlParent, conn, trans))
                            {
                                cmdParent.Parameters.AddWithValue("@SHDon", item.SHDon ?? "");
                                cmdParent.Parameters.AddWithValue("@KHHDon", item.KHHDon ?? "");
                                cmdParent.Parameters.AddWithValue("@NLap", item.NLap);
                                cmdParent.Parameters.AddWithValue("@Ten", item.Ten ?? "");
                                cmdParent.Parameters.AddWithValue("@Noidung", item.Noidung ?? "");
                                cmdParent.Parameters.AddWithValue("@TKNo", item.TKNo ?? "");
                                cmdParent.Parameters.AddWithValue("@TKCo", item.TKCo ?? "");
                                cmdParent.Parameters.AddWithValue("@TkThue", item.TkThue ?? "");
                                cmdParent.Parameters.AddWithValue("@Mst", item.Mst ?? "");
                                cmdParent.Parameters.AddWithValue("@Status", "0");
                                cmdParent.Parameters.AddWithValue("@Ngaytao", DateTime.Now);
                                cmdParent.Parameters.AddWithValue("@TongTien", item.TongTien);
                                cmdParent.Parameters.AddWithValue("@Vat", item.Vat);
                                cmdParent.Parameters.AddWithValue("@TPhi", item.TPhi ?? "0");
                                cmdParent.Parameters.AddWithValue("@TgTCThue", Math.Round(item.TgTCThue));
                                cmdParent.Parameters.AddWithValue("@TgTThue", Math.Round(item.TgTThue));
                                cmdParent.Parameters.AddWithValue("@Type", type);
                                cmdParent.Parameters.AddWithValue("@InvoiceType", "0");
                                cmdParent.Parameters.AddWithValue("@IsHaschild", "1");
                                cmdParent.Parameters.AddWithValue("@TVat", item.TVat);
                                cmdParent.Parameters.AddWithValue("@Vat2", item.Vat2 ?? "0");
                                cmdParent.Parameters.AddWithValue("@TVat2", item.TVat2);
                                cmdParent.Parameters.AddWithValue("@Vat3", item.Vat3 ?? "0");
                                cmdParent.Parameters.AddWithValue("@TVat3", item.TVat3);
                                cmdParent.Parameters.AddWithValue("@TgTCThue1", item.TgTCThue1);
                                cmdParent.Parameters.AddWithValue("@TgTCThue2", item.TgTCThue2);
                                cmdParent.Parameters.AddWithValue("@TgTCThue3", item.TgTCThue3);
                                cmdParent.Parameters.AddWithValue("@Khmshdon", item.Khmshdon ?? "");
                                cmdParent.Parameters.AddWithValue("@hdon", item.hdon ?? "");
                                cmdParent.Parameters.AddWithValue("@Path", item.Path ?? "");

                                await cmdParent.ExecuteNonQueryAsync();
                            }

                            // 2. Lấy ID tự tăng vừa tạo (SQL Server)
                            string sqlGetMaxId = "SELECT ISNULL(MAX(ID), 0) FROM tbImport";
                            using (SqlCommand cmdMax = new SqlCommand(sqlGetMaxId, conn, trans))
                            {
                                parentID = (int)await cmdMax.ExecuteScalarAsync(); 
                            }

                            // 3. Lưu chi tiết hàng hóa (Details)
                            foreach (var dt in item.tbImportDetails)
                            {
                                using (SqlCommand cmdDetail = new SqlCommand(sqlDetail, conn, trans))
                                {
                                    cmdDetail.Parameters.AddWithValue("@ParentId", parentID);
                                    cmdDetail.Parameters.AddWithValue("@SoHieu", dt.SoHieu ?? "");
                                    cmdDetail.Parameters.AddWithValue("@SoLuong", dt.Soluong);
                                    cmdDetail.Parameters.AddWithValue("@DonGia", dt.Dongia);
                                    cmdDetail.Parameters.AddWithValue("@DVT", string.IsNullOrEmpty(dt.DVT) ? "xxx" : dt.DVT); 
                                    cmdDetail.Parameters.AddWithValue("@Ten", dt.Ten ?? "");
                                    cmdDetail.Parameters.AddWithValue("@MaCT", DBNull.Value); 
                                    cmdDetail.Parameters.AddWithValue("@TKNo", dt.TKNo ?? "");
                                    cmdDetail.Parameters.AddWithValue("@TKCo", dt.TKCo ?? "");
                                    cmdDetail.Parameters.AddWithValue("@TTien", dt.TTien);
                                    cmdDetail.Parameters.AddWithValue("@Percent", dt.Percent);
                                    cmdDetail.Parameters.AddWithValue("@Tchat", dt.Tchat);
                                    cmdDetail.Parameters.AddWithValue("@SoPSGoc", dt.TTien);
                                    cmdDetail.Parameters.AddWithValue("@VAT", dt.Vat);
                                    await cmdDetail.ExecuteNonQueryAsync();
                                }
                            }
                        }

                        trans.Commit();
                    }
                    catch (Exception ex)
                    {
                        trans.Rollback();
                        XtraMessageBox.Show("Lỗi hệ thống khi lưu hàng loạt: " + ex.Message, "Lỗi Database");
                    }
                }
            }
        }
