                //string qury = @"SELECT TOP 1 * FROM KhachHang AS kh
                //         WHERE MST = ?"; // Sử dụng ? thay cho @mst trong OleDb
                //DataTable rs = ExecuteQuery(qury, new OleDbParameter("?",Mst));
