                connection.Open();
                Console.WriteLine("Kết nối đến cơ sở dữ liệu thành công!" + query);

                using (OleDbCommand command = new OleDbCommand(query, connection))
                {
                    // Thêm các tham số vào command
                    if (parameters != null)
                    {
                        command.Parameters.AddRange(parameters);
                    }

                    int rowsAffected = command.ExecuteNonQuery(); // Thực thi câu lệnh
                    return rowsAffected;
                }
            }

            return -1;
        }

        public int ExecuteBatchUpdate(List<(int ID, int Status)> updates)
        {
            if (!updates.Any()) return 0;

            using (var conn = new OleDbConnection(connectionString))
            {
                conn.Open();
                using (var trans = conn.BeginTransaction())
                {
                    using (var cmd = new OleDbCommand("UPDATE tbimport SET Status = ? WHERE ID = ?", conn, trans))
                    {
                        var paramStatus = new OleDbParameter("?", OleDbType.Integer);
                        var paramID = new OleDbParameter("?", OleDbType.Integer);
                        cmd.Parameters.Add(paramStatus);
                        cmd.Parameters.Add(paramID);

                        foreach (var item in updates)
                        {
                            paramStatus.Value = item.Status;  // 0 : 3;
                            paramID.Value = item.ID;
                            cmd.ExecuteNonQuery();
                        }
                    }
                    trans.Commit();
                }
            }
            return updates.Count;
        }
