        private void btnRefresh_Click(object sender, EventArgs e)
        {
            if (chkDauvao.Checked)
            {
                progressPanel1.Visible = true;
                progressPanel1.Caption = "Đang xoá hoá đơn ...";
            }
            else
            {
                progressPanel2.Visible = true;
                progressPanel2.Caption = "Đang xoá hoá đơn ...";
            }
                Application.DoEvents();
            try
            {
                string query = "DELETE FROM tbimportdetail";
                ExecuteNonQuery2(query, null);

                // Xóa dữ liệu từ tbimport
                query = "DELETE FROM tbimport";
                ExecuteNonQuery2(query);
                //XtraMessageBox.Show("Đã xoá dữ liệu thành công");
            }
            catch(Exception ex)
            {
                XtraMessageBox.Show(ex.Message);
            }
            LoadTbImportData();
            lookupTbImport
           = new HashSet<(string MST, string SHDon, DateTime NLap,int Type)>();
            lookupTbImportCQT
         = new HashSet<(string MST, string SHDon, DateTime NLap,int Type)>();
            // Loadtbimport();
            progressPanel1.Visible = false;
            progressPanel2.Visible = false;
            lstImportVao = new BindingList<FileImport>();
            lstImportRa = new BindingList<FileImport>();
            gridControl1.DataSource = lstImportVao;
            gridControl2.DataSource = lstImportRa;
            gridControl1.Refresh();
            gridControl2.Refresh();
            gridView1.RefreshData();
            gridView3.RefreshData();
            _cacheToanCuc.Clear();
            _fuzzyCache.Clear();    
            // btnChonthang.PerformClick();
        }
        public int ExecuteNonQuery2(string query, params SqlParameter[] parameters)
        {
            int rowsAffected = 0;
            using (SqlConnection connection = new SqlConnection(connectionStringSQL))
            {
                connection.Open();
                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    if (parameters != null)
                        command.Parameters.AddRange(parameters);
                    rowsAffected = command.ExecuteNonQuery();
                }
            }
            return rowsAffected;
        }

