        private void gridView1_MouseDown(object sender, MouseEventArgs e)
        {
            var hitInfo = gridView1.CalcHitInfo(e.Location);
            if (hitInfo.InColumn)
            {
                var column = hitInfo.Column;
                if (column.ToString() == "Chọn")
                {
                    if (checkedCtype == 0)
                    {
                        checkedCtype = 1;
                        //Bỏ check tất cả
                        foreach (var item in lstImportVao)
                        {
                            item.Checked = false;
                        }
                    }
                    else
                    {
                        checkedCtype = 0;
                        foreach (var item in lstImportVao)
                        {
                            item.Checked = true;
                        }
                    }
                    gridControl1.DataSource = lstImportVao;
                    gridControl1.RefreshDataSource();
                }
                if (column.ToString() == "Không KT Thuế")
                {
                    if (checkedCtype2 == 0)
                    {
                        checkedCtype2 =1;
                        //Bỏ check tất cả
                        foreach (var item in lstImportVao)
                        {
                            item.Khautruthue = true; 
                        }
                    }
                    else
                    {
                        checkedCtype2 = 0;
                        foreach (var item in lstImportVao)
                        {
                            item.Khautruthue = false; 
                        }
                    }
                   
                    gridControl1.DataSource = lstImportVao;
                    gridControl1.RefreshDataSource();
                }
            }

            if (e.Button == MouseButtons.Right) 
            {
                resetKey();
                GridView view = sender as GridView;
                hitInfo = view.CalcHitInfo(e.Location);
                int rowHandle = hitInfo.RowHandle; // Lấy chỉ số hàng
                string fieldName = hitInfo.Column.FieldName; // Lấy tên cột
                if (fieldName == "Mst")
                {
                    
                    var cellValue = view.GetRowCellValue(rowHandle, fieldName);
                    keyMST = cellValue.ToString();
                    frmDinhdanh frmDinhdanh = new frmDinhdanh();
                    frmDinhdanh.frmMain = this;
                    frmDinhdanh.ShowDialog();
                }
                if (fieldName == "Noidung")
                {

                    var cellValue = view.GetRowCellValue(rowHandle, fieldName);
                    KeyDG = cellValue.ToString();
                    frmDinhdanh frmDinhdanh = new frmDinhdanh();
                    frmDinhdanh.frmMain = this;
                    frmDinhdanh.ShowDialog();
                }
            }
        }
