                    {
                        //if (currentColumnName.ToString() == "SoHieu")
                        //{
                        //    gridView = sender as DevExpress.XtraGrid.Views.Grid.GridView;
                        //    ToogleVattucontrol(gridView, cellValue,1);
                        //}

                        if (currentColumnName.ToString() == "SoHieu")
                        {
