                                                };
                                                var rowsAffected = ExecuteQueryResult(query, parameters);
                                                //Insert thêm cho lstvt

                                            }
                                        }
                                    }
                                    lstrowSohieu = new List<int>();
                                }

                            }

                        }
                    }
                }

            }

            if (e.KeyCode.ToString() == "Delete")
            {
