        private async void VattuControl_ItemSelectednl(object sender, string seletedItem)
        { 
            lstvt = await LoadDataVattuAsync();
            var findkh = lstvt.Where(row => row.SoHieu == seletedItem).FirstOrDefault();
            if (findkh != null)
            {
                int currentRowHandle = gridView.FocusedRowHandle;
                var focusedColumn = gridView.FocusedColumn;

                gridView.SetRowCellValue(currentRowHandle, focusedColumn, seletedItem);

                //Tính số lượng
                var getvt = lstvt.Where(m => m.SoHieu == seletedItem).FirstOrDefault();
                if (getvt != null)
                { 
                    //Tìm chứng từ cuối cùng
                    var findlastCt = existingTbChungtu.AsEnumerable().Where(m => m.Field<int>("MaVattu") == getvt.MaSo && m["SoPS2No"].ToString() != "0").LastOrDefault();
                    if (findlastCt != null)
                    {
                        double getSoPS = double.Parse(findlastCt["SoPS"].ToString());
                        double SoPSNo = double.Parse(findlastCt["SoPS2No"].ToString());
                        double DonGia = getSoPS / SoPSNo;
                        for (int i = 1; i <= 5; i++)
                        {
                            if (focusedColumn.ToString() == $"Nguyên liệu {i}")
                            {
                                double tt = double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, "DonGia").ToString()) *
                                             double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, "SoLuongTon").ToString());
                                double percent2 = double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, $"ps{i}").ToString());
                                var tt1 = (tt * percent2 / 100);
                                double sL = Math.Round(tt1 / DonGia, 2);
                                sL = sL < 0 ? sL * -1 : sL;

                                gridView6.SetRowCellValue(gridView6.FocusedRowHandle, $"sl{i}", sL);
                                gridView6.SetRowCellValue(gridView6.FocusedRowHandle, $"dg{i}", DonGia);
                                break; // Kết thúc vòng lặp nếu tìm thấy trường hợp phù hợp
                            }
                        }
                       
                    }
                    else
                    {
                       //XtraMessageBox.Show("Không tìm thấy chứng từ!");
                    }
                }
                else
                {
                    //  XtraMessageBox.Show("Không tìm thấy vật tư!");
                }

                vattuControlnl.Hide(); // Ẩn UserControl  
            }
        }
