        private void gridView1_CellValueChanging(object sender, DevExpress.XtraGrid.Views.Base.CellValueChangedEventArgs e)
        {
            gridControl1.ToolTipController = toolTipController1;
            DevExpress.XtraGrid.Views.Grid.GridView view = sender as DevExpress.XtraGrid.Views.Grid.GridView;
            var newValue = e.Value;
            int rowindex = view.FocusedRowHandle;
            //if (newValue.ToString().Length < 3)
            //{
            //    toolTipController.HideHint();
            //    return;
            //}
            if (view.FocusedColumn.FieldName == "TKNos") // Thay đổi tên cột theo nhu cầu
            {
                // Hiển thị tooltip
                string querydinhdanh = @"SELECT * FROM HeThongTK WHERE SoHieu LIKE ?";
                var resultkm = ExecuteQuery(querydinhdanh, new OleDbParameter("?", newValue + "%"));
                var str = "";
                var strBuilder = new System.Text.StringBuilder();

                if (resultkm.Rows.Count > 0)
                {
                    for (int i = 0; i < resultkm.Rows.Count; i++)
                    {
                        strBuilder.AppendLine(resultkm.Rows[i]["SoHieu"].ToString() + "-" + Helpers.ConvertVniToUnicode(resultkm.Rows[i]["Ten"].ToString())); // Thêm xuống dòng
                    }
                }
                if (resultkm.Rows.Count > 1)
                {
                    string tooltipText = strBuilder.ToString().Trim(); // Loại bỏ dòng trống cuối cùng (nếu có)

                    var gridViewInfo = view.GetViewInfo() as GridViewInfo;

                    GridCellInfo cellInfo = gridViewInfo.GetGridCellInfo(e.RowHandle, view.FocusedColumn);

                    int rowHandle = view.FocusedRowHandle;
                    System.Drawing.Rectangle cellRect = cellInfo.Bounds;
                    System.Drawing.Point screenPoint = view.GridControl.PointToScreen(
                        new System.Drawing.Point(cellRect.X, cellRect.Bottom + 2)
                    );

                    toolTipController.ShowHint(tooltipText, screenPoint);
                }

            }

            if (view.FocusedColumn.FieldName == "TKCo" || view.FocusedColumn.FieldName == "TKNo") // Thay đổi tên cột theo nhu cầu
            {
                if (e.Value.ToString() == "154")
                {
                    // Cập nhật lại ô để hiển thị nút
                    gridView1.RefreshRowCell(e.RowHandle, e.Column);
                }

                string querydinhdanh = @"SELECT * FROM HeThongTK WHERE SoHieu LIKE ?";
                var resultkm = ExecuteQuery(querydinhdanh, new OleDbParameter("?", newValue + "%"));
                if (resultkm.Rows.Count < 2)
                {
                    suggestionControl1.Hide();
                    return;
                }
                List<HeThongTK> lstHethongtk = new List<HeThongTK>();
                foreach (DataRow dt in resultkm.Rows)
                {
                    HeThongTK HeThongTK = new HeThongTK();
                    HeThongTK.MaSo = int.Parse(dt["MaSo"].ToString());
                    HeThongTK.SoHieu = dt["SoHieu"].ToString();
                    HeThongTK.Ten = dt["Ten"].ToString();
                    lstHethongtk.Add(HeThongTK);
                }
                suggestionControl1.UpdateSuggestions(lstHethongtk.ToList());


                // Đặt vị trí cho UserControl 
                // Lấy thông tin về GridView
                var gridViewInfo = view.GetViewInfo() as GridViewInfo;
                GridCellInfo cellInfo = gridViewInfo.GetGridCellInfo(e.RowHandle, view.FocusedColumn);

                if (cellInfo != null)
                {
                    // Lấy vị trí của cell
                    System.Drawing.Rectangle cellRect = cellInfo.Bounds;

                    // Chuyển đổi vị trí của cell thành tọa độ màn hình
                    System.Drawing.Point screenPoint = view.GridControl.PointToScreen(cellRect.Location);

                    // Đặt vị trí cho UserControl ngay dưới cell
                    suggestionControl1.Location = new System.Drawing.Point(screenPoint.X + 80, 0 + cellRect.Height + 30); // Thêm khoảng cách 5 pixels
                                                                                                                          // Hiển thị UserControl
                    suggestionControl1.Show();

                }
            }
        }
         
      

     
        private Dictionary<(int RowHandle, string ColumnName), Color> cellColors2 = new Dictionary<(int, string), Color>();

        private void LoadCustomDrawcell(object sender, DevExpress.XtraGrid.Views.Base.RowCellCustomDrawEventArgs e, int parentRowData, int type)
        {
            if(e.Column.FieldName == "Ten")
            {
                int rowHandle = e.RowHandle;
                var gridView = sender as GridView;

                FileImportDetail rowData = gridView.GetRow(rowHandle) as FileImportDetail;
                if (rowData != null)
                {
                    // Kiểm tra Percent không null
                    double percent;
                    bool isPercentValid = double.TryParse(rowData.Percent?.ToString(), out percent);

                    double tyLeChon;
                    bool isTyLeValid = double.TryParse(txtTylechonHH.Text, out tyLeChon);

                    if (isPercentValid && isTyLeValid && percent >= tyLeChon && percent < 100)
                    {
                        e.Appearance.ForeColor = Color.Blue;
                        cellColors2[(rowHandle, e.Column.FieldName)] = Color.Blue;
                    }
                }
            }
            if (e.Column.FieldName == "SoHieu")
            {
                if (e.CellValue == null)
                    return;

                var getValue = e.CellValue.ToString();

                var resultKm = lstvt.Where(m => m.SoHieu.ToLower() == getValue.ToLower()).FirstOrDefault();

                // Vẽ chữ màu đè lên (màu đỏ) nếu không tìm thấy kết quả
                if (resultKm == null)
                {
                    System.Drawing.Font boldFont = new System.Drawing.Font(e.Appearance.Font, FontStyle.Bold);
                    e.Cache.DrawString(
                        e.DisplayText,
                        boldFont,
                        Brushes.DarkBlue,  // Chữ màu đỏ
                        e.Bounds,
                        e.Appearance.GetStringFormat()
                    );
                        
                    // Lưu màu
                    cellColors2[(e.RowHandle, e.Column.FieldName)] = Color.DarkBlue; // Lưu màu chữ
                    e.Handled = true; // Ngăn vẽ mặc định
                }
            }

            if (e.Column.FieldName == "Soluong" && type == 2 && hienthimau)
            {
                int rowHandle = e.RowHandle;
                var gridView = sender as GridView;

                FileImportDetail rowData = gridView.GetRow(rowHandle) as FileImportDetail;

                if (e.CellValue != null)
                {
                    if (rowData != null)
                    {
                        var getVstTu = lstvt.FirstOrDefault(m => m.SoHieu.ToLower() == rowData.SoHieu.ToLower());
                        if (getVstTu != null)
                        {
                            if (getVstTu.SoLuong < (double)e.CellValue)
                            {
                                e.Appearance.ForeColor = Color.Red; // Tô màu chữ đỏ
                                cellColors2[(rowHandle, e.Column.FieldName)] = Color.Red; // Lưu màu
                            }
                        }
                    }
                }
            }
           
        }
        private void gridView2_CustomDrawCell(object sender, DevExpress.XtraGrid.Views.Base.RowCellCustomDrawEventArgs e)
        {
            
            var gridControl = (sender as GridView).GridControl;
            var gridView1 = gridControl.MainView as GridView;
            var parentRowData = (int)gridView1.GetRowCellValue(gridView1.FocusedRowHandle, "ID");
            LoadCustomDrawcell(sender, e, parentRowData, 1);
            GridView grv = sender as GridView; // Chuyển đổi sender thành GridView
            if (e.Column.FieldName == "Percent" && hienthimau) // Kiểm tra cột phần trăm
            {
                // Lấy văn bản hiện tại trong ô
                string currentText = e.DisplayText;
                if (!string.IsNullOrEmpty(currentText))
                {
                    var percentValue = grv.GetRowCellValue(e.RowHandle, "Percent") !=null? double.Parse(grv.GetRowCellValue(e.RowHandle, "Percent").ToString()):0;

                    string newText = $"{currentText}";

                    if (percentValue < 100)
                    {
                        e.Appearance.ForeColor = Color.Red;
                        e.Appearance.Font = new Font(e.Appearance.Font, FontStyle.Bold);
                    }
                    else
                    {
                        e.Appearance.ForeColor = Color.Black;
                        e.Appearance.Font = new Font(e.Appearance.Font, FontStyle.Regular);
                    }

                    e.Graphics.DrawString(newText, e.Appearance.Font, new SolidBrush(e.Appearance.ForeColor), e.Bounds, StringFormat.GenericDefault);

                    e.Handled = true; // Ngăn không cho vẽ mặc định
                }

            }
        }

