                }
            }
        }

        private void gridView3_MouseDown(object sender, MouseEventArgs e)
        {
            var hitInfo = gridView3.CalcHitInfo(e.Location);
            if (hitInfo.InColumn)
            {
                var column = hitInfo.Column;
                if (column.ToString() == "Chọn")
                {
                    if (checkedCtype == 0)
                    {
                        checkedCtype = 1;
                        //Bỏ check tất cả
                        foreach (var item in lstImportRa)
                        {
                            item.Checked = false;
                        }
                    }
                    else
                    {
                        checkedCtype = 0;
                        foreach (var item in lstImportRa)
                        {
                            item.Checked = true;
                        }
                    }
                    gridControl2.DataSource = lstImportRa;
                    gridControl2.RefreshDataSource();
                }
            }

            if (e.Button == MouseButtons.Right)
            {
                resetKey();
                GridView view = sender as GridView;
                hitInfo = view.CalcHitInfo(e.Location);
                int rowHandle = hitInfo.RowHandle; // Lấy chỉ số hàng
                string fieldName = hitInfo.Column.FieldName; // Lấy tên cột
                if (fieldName == "Mst")
                {

                    var cellValue = view.GetRowCellValue(rowHandle, fieldName);
                    keyMST2 = cellValue.ToString();
                    frmDinhdanh frmDinhdanh = new frmDinhdanh();
                    frmDinhdanh.frmMain = this;
                    frmDinhdanh.ShowDialog();
                }
                if (fieldName == "Noidung")
                {

                    var cellValue = view.GetRowCellValue(rowHandle, fieldName);
                    KeyDG2 = cellValue.ToString();
                    frmDinhdanh frmDinhdanh = new frmDinhdanh();
                    frmDinhdanh.frmMain = this;
                    frmDinhdanh.ShowDialog();
                }
            }
        }
