        private async void simpleButton3_Click(object sender, EventArgs e)
        {
            if (chktaituweb.Checked)
            {
                Thuchientaihoadontuweb();
                XtraMessageBox.Show("Đã tải xong hoá đơn đầu vào");
                return;
            }
            progressPanel1.Show();
            progressPanel1.Caption = "Đang bắt đầu tiến hành tải dữ liệu...";
            Application.DoEvents();

            if (!Kiemtranamtc())
                return;

            // ========== LOAD DATA LOCAL ==========
            existingTbChungtu = ExecuteQuerySQL("SELECT * FROM ChungTu inner join HoaDon on ChungTu.MaSo = HoaDon.MaSo");
            modeClick = 2;
            Create2026Structure(savedPath);

            LoadHoadonCT();
            Loadtbimport();

            tbimport = ExecuteQuerySQL("SELECT * FROM tbimport");
            tbimportdetail = ExecuteQuerySQL("SELECT * FROM tbimportdetail");

            // ========== KIỂM TRA TOKEN CŨ ==========
            bool needLogin = true;
            tbRegister = ExecuteQuerySQL("SELECT * FROM tbRegister", null);
            //if (tbRegister.Rows.Count > 0)
            //{
            //    string timeTK = tbRegister.Rows[0]["TimeTokken"].ToString();
            //    string tokenDB = tbRegister.Rows[0]["tokken"].ToString();

            //    if (!string.IsNullOrEmpty(timeTK))
            //    {
            //        var delta = DateTime.Now - DateTime.Parse(timeTK);

            //        // Token còn < 1 phút → KHÔNG ĐĂNG NHẬP LẠI
            //        if (delta.TotalMinutes <=  && !string.IsNullOrEmpty(tokenDB))
            //        {
            //            needLogin = false;
            //            this.tokken = tokenDB;
            //        }
            //    }
            //}

            // UI thông báo khi load đầu vào / đầu ra
            if (chkDauvao.Checked)
            {
                progressPanel1.Show();
                progressPanel1.Caption = "Đang chuẩn bị tải dữ liệu đầu vào...";
                Application.DoEvents();
            }

            if (chkDaura.Checked)
            {
                progressPanel2.Show();
                progressPanel2.Caption = "Đang chuẩn bị tải dữ liệu đầu ra...";
                Application.DoEvents();
            }

            // ========== LOGIN NẾU CẦN ==========
            if (needLogin)
            {
                try
                {
                    // ===== HttpClient + CookieContainer =====
                    var cookieContainer = new CookieContainer();
                    var handler = new HttpClientHandler()
                    {
                        UseCookies = true,
                        CookieContainer = cookieContainer,
                        AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate,
                        AllowAutoRedirect = true
                    };

                    using (var client = new HttpClient(handler))
                    {
                        // Set timeout
                        client.Timeout = TimeSpan.FromSeconds(30);

                        // ===== Header giống trình duyệt =====
                        client.DefaultRequestHeaders.Clear();
                        client.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36");
                        client.DefaultRequestHeaders.Add("Accept", "application/json, text/plain, */*");
                        client.DefaultRequestHeaders.Add("Accept-Language", "vi-VN,vi;q=0.9,en-US;q=0.8,en;q=0.7");
                        client.DefaultRequestHeaders.Add("Accept-Encoding", "gzip, deflate, br");
                        client.DefaultRequestHeaders.Add("Connection", "keep-alive");
                        client.DefaultRequestHeaders.Add("Origin", "https://hoadondientu.gdt.gov.vn");
                        client.DefaultRequestHeaders.Add("Referer", "https://hoadondientu.gdt.gov.vn/");
                        client.DefaultRequestHeaders.ExpectContinue = false;

                        // ================= STEP 1: GET CAPTCHA =================
                        if (chkDauvao.Checked) progressPanel1.Caption = "Đang tải captcha...";
                        if (chkDaura.Checked) progressPanel2.Caption = "Đang tải captcha...";
                        Application.DoEvents();

                        string capUrl = "https://hoadondientu.gdt.gov.vn/api/captcha";
                        var resCap = await client.GetAsync(capUrl);

                        if (!resCap.IsSuccessStatusCode)
                        {
                            ToastMeaasge("Không lấy được captcha");
                            return;
                        }

                        string capBody = await resCap.Content.ReadAsStringAsync();
                        MyJson capJson = JsonConvert.DeserializeObject<MyJson>(capBody);

                        string svgPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "captcha.svg");
                        File.WriteAllText(svgPath, capJson.Content);

                        // ===== LẤY XSRF-TOKEN (NẾU CÓ) =====
                        string xsrfToken = null;

                        // Lấy từ CookieContainer
                        var cookies = cookieContainer.GetCookies(new Uri("https://hoadondientu.gdt.gov.vn"));
                        xsrfToken = cookies["XSRF-TOKEN"]?.Value;

                        // Nếu có thì thêm vào header, không có thì bỏ qua
                        if (!string.IsNullOrEmpty(xsrfToken))
                        {
                            client.DefaultRequestHeaders.Remove("X-XSRF-TOKEN");
                            client.DefaultRequestHeaders.Add("X-XSRF-TOKEN", xsrfToken);
                        }

                        // ================= STEP 2: SOLVE CAPTCHA =================
                        if (chkDauvao.Checked) progressPanel1.Caption = "Đang giải mã captcha...";
                        if (chkDaura.Checked) progressPanel2.Caption = "Đang giải mã captcha...";
                        Application.DoEvents();

                        SvgCaptchaSolver solver = new SvgCaptchaSolver();
                        string cvalue = solver.SolveCaptcha(svgPath);

                        if (string.IsNullOrEmpty(cvalue))
                        {
                            ToastMeaasge("Không giải được captcha");
                            return;
                        }

                        // ================= STEP 3: LOGIN =================
                        if (chkDauvao.Checked) progressPanel1.Caption = "Đang đăng nhập hệ thống Thuế...";
                        if (chkDaura.Checked) progressPanel2.Caption = "Đang đăng nhập hệ thống Thuế...";
                        Application.DoEvents();

                        string loginUrl = "https://hoadondientu.gdt.gov.vn/api/security-taxpayer/authenticate";

                        var payload = new
                        {
                            username = txtuser.Text,
                            password = txtpass.Text,
                            cvalue = cvalue,
                            ckey = capJson.Key
                        };

                        var content = new StringContent(
                            JsonConvert.SerializeObject(payload),
                            Encoding.UTF8,
                            "application/json"
                        );

                        // GỬI REQUEST LOGIN
                        var loginRes = await client.PostAsync(loginUrl, content);

                        if (loginRes.StatusCode == HttpStatusCode.Unauthorized)
                        {
                            string err = await loginRes.Content.ReadAsStringAsync();
                            ToastMeaasge("Đăng nhập thất bại (401): " + err);
                            return;
                        }

                        loginRes.EnsureSuccessStatusCode();

                        string loginBody = await loginRes.Content.ReadAsStringAsync();
                        var tokenData = JsonConvert.DeserializeObject<TokenResponse>(loginBody);
                        this.tokken = tokenData.token;

                        // ================= STEP 4: PROFILE =================
                        try
                        {
                            var req = new HttpRequestMessage(
                                HttpMethod.Get,
                                "https://hoadondientu.gdt.gov.vn/api/security-taxpayer/profile"
                            );

                            req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", this.tokken);
                            var profRes = await client.SendAsync(req);

                            if (profRes.IsSuccessStatusCode)
                            {
                                string profBody = await profRes.Content.ReadAsStringAsync();
                                var prof = JsonConvert.DeserializeObject<ProfileResponse>(profBody);

                                if (!string.IsNullOrEmpty(prof.password_expire))
                                {
                                    DateTime expireDate = DateTime.Parse(prof.password_expire);
                                    TimeSpan remain = expireDate - DateTime.Now;

                                    if (remain.TotalDays <= 0)
                                    {
                                        XtraMessageBox.Show(
                                            $"Mật khẩu đã hết hạn ngày {expireDate:dd/MM/yyyy}.",
                                            "Hết hạn!",
                                            MessageBoxButtons.OK,
                                            MessageBoxIcon.Warning
                                        );
                                        return;
                                    }
                                    else if (remain.TotalDays <= 3)
                                    {
                                        XtraMessageBox.Show(
                                            $"⚠ Mật khẩu sẽ hết hạn sau {remain.Days} ngày!\nNgày: {expireDate:dd/MM/yyyy}",
                                            "Cảnh báo",
                                            MessageBoxButtons.OK,
                                            MessageBoxIcon.Warning
                                        );
                                    }
                                    else if (remain.TotalDays <= 7)
                                    {
                                        ToastMeaasge($"Mật khẩu sắp hết hạn {expireDate:dd/MM/yyyy} (còn {remain.Days} ngày)");
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            ToastMeaasge("Không kiểm tra được ngày hết hạn: " + ex.Message);
                        }

                        // ================= SAVE TOKEN TIME =================
                          ExecuteQueryResultSQL(
                         "UPDATE tbRegister SET TimeTokken = @TimeTokken",
                         new SqlParameter[]
                         {
                            new SqlParameter("@TimeTokken", DateTime.Now)
                         }
                     );

                        if (chkDauvao.Checked) progressPanel1.Caption = "Đang bắt đầu tải hoá đơn...";
                        if (chkDaura.Checked) progressPanel2.Caption = "Đang bắt đầu tải hoá đơn...";
                        Application.DoEvents();
                    }
                }
                catch (Exception ex)
                {
                    XtraMessageBox.Show("Lỗi đăng nhập hệ thống thuế: " + ex.Message);
                }
            }

            // ========== DOWNLOAD & PROCESS EXCEL ==========
            if (chkDauvao.Checked)
            {
                progressPanel1.Caption = "Đang tải hoá đơn điện tử.xlsx";
                Application.DoEvents();
                Xulyexelvao(tokken, 1);

                progressPanel1.Caption = "Đang tải hoá đơn không nhận mã.xlsx";
                Application.DoEvents();
                Xulyexelvao(tokken, 2);

                progressPanel1.Caption = "Đang tải hoá đơn máy tính tiền.xlsx";
                Application.DoEvents();
                Xulyexelvao(tokken, 3);

                progressPanel1.Caption = "Đang đọc dữ liệu Excel...";
                Application.DoEvents();
                await DocfileExcelVaoAsync();
            }
            else
            {
                progressPanel2.Caption = "Đang tải hoá đơn điện tử.xlsx";
                Application.DoEvents();
                Xulyexelra(tokken, 1);

                progressPanel2.Caption = "Đang tải hoá đơn máy tính tiền.xlsx";
                Application.DoEvents();
                Xulyexelra(tokken, 2);

                await DocfileExcelRaAsync();
            }
        }

