        private bool CheckExistKH(string mst)
        {
            
            //Nếu có Mã s61 thuế
            if (!string.IsNullOrEmpty(mst))
            {
                if (tbKhachhang.AsEnumerable().Any(row => row.Field<string>("MST") == mst || row.Field<string>("SoHieu")==mst) )
                {
                    return true;
                }
            }

            return false;
        }
