        // ──────────────────────────────── Helper siêu an toàn ────────────────────────────────
        // KHAI BÁO Ở ĐẦU CLASS (trong Form của bạn)
        private Dictionary<string, TbImportDetail> cacheMatHangTrongHoaDon;
        private string GetSafeText(XmlNode parent, string xpath)
        {
            try { return parent.SelectSingleNode(xpath)?.InnerText?.Trim() ?? ""; }
            catch { return ""; }
        }
        private double SafeDouble(string s) => double.TryParse(s, out double d) ? d : 0;
        private int SafeInt(string s) => int.TryParse(s, out int i) ? i : 0;
        // === Hàm helper an toàn ===
        private string GetNodeText(XmlNode parent, string xpath)
        {
            try
            {
                XmlNode node = parent.SelectSingleNode(xpath);
                return node?.InnerText?.Trim() ?? "";
            }
            catch { return ""; }
        }

        private double ParseDouble(string s)
        {
            if (double.TryParse(s?.Trim(), out double d)) return d;
            return 0;
        }

        private int ParseInt(string s)
        {
            if (int.TryParse(s?.Trim(), out int i)) return i;
            return 0;
        }
        private string CreateSearchKey(string productName)
        {
            // Chuẩn hóa giống như bạn đang làm
            return Helpers.RemoveVietnameseDiacritics(
                       Helpers.NormalizeVietnameseString(productName))
                   .ToLower()
                   .Replace(".", " ")
                   .Replace("-", " ")
                   .Replace("  ", " ")
                   .Trim();
        }
        private bool Loaiborow(string name)
        {
            if (name.ToLower().Contains("điều chỉnh"))
                return true;
            return false;
        }
        private Dictionary<string, (string TenVattu, string TenVattu2, string DonVi,double Dongia,double SoLuong)> vatTuLookup;

        // ==================== TOÀN CỤC (chỉ khai báo 1 lần) ====================
        private readonly Dictionary<string, (string SoHieu, double Percent)> _cacheToanCuc
            = new Dictionary<string, (string SoHieu, double Percent)>(StringComparer.OrdinalIgnoreCase);

        // ==================== HÀM ĐÃ SỬA CHUẨN 100% – GIỮ NGUYÊN LOGIC CỦA ANH ====================
        private void Xulysohieuvattugoc(TbImportDetail tbImportDetail)
        {
            string ten = tbImportDetail.Ten?.Trim() ?? "";
            VietnameseProductMatcher vietnameseProductMatcher = new VietnameseProductMatcher();
            ten = vietnameseProductMatcher.NormalizeVietnameseProduct(ten);
            if (string.IsNullOrEmpty(ten))
            {
                tbImportDetail.SoHieu = GenerateResultString(NormalizeVietnameseString(ten));
                tbImportDetail.Percent = 0;
                return;
            }

            // DÙNG ĐÚNG 1 HÀM CHUẨN HÓA CHO TẤT CẢ: NormalizeForLookup (giống như bạn đang dùng cho _lookupByTenChinh)
            string key = Helpers.NormalizeVietnameseString(ten).Trim();  // ← QUAN TRỌNG NHẤT: DÙNG CHUNG 1 KEY!!!

            // === TẦNG 0: CACHE TOÀN CỤC ===
            if (_cacheToanCuc.TryGetValue(key, out var cached))
            {
                tbImportDetail.SoHieu = cached.SoHieu;
                tbImportDetail.Percent = cached.Percent;
                return;
            }

            // === TẦNG 1: Tìm nhanh (bây giờ key giống nhau → vào 100%) ===
            if (_lookupByTenChinh.TryGetValue(key, out string sohieu) ||
              _lookupByTenPhu.TryGetValue(key, out sohieu))
            {
                tbImportDetail.SoHieu = sohieu;
                tbImportDetail.Percent = 100;
                _cacheToanCuc[key] = (sohieu, 100);
                return;
            }

            // === TẦNG 2: Fuzzy + quy cách (giữ nguyên logic cực chuẩn của anh) ===
            tbImportDetail.Percent = 0;
            double bestPercent = 0;
            string bestSoHieu = null;

            string getTen2 = key;
            Regex regex = new Regex(@"(\d+(g|ml|L|kg)|x\d+|(\d+\s*cái))", RegexOptions.IgnoreCase);
            var matchInput = regex.Match(getTen2).Value;

            foreach (var item in vatTuLookup)
            {
                string getTen = Helpers.NormalizeVietnameseString(item.Value.TenVattu);  // ← DÙNG CHUNG HÀM!!!
                double final = CalculateSimilarity(getTen, getTen2);  
                if (!string.IsNullOrEmpty(item.Value.TenVattu2))
                {
                    string getTenAlt = Helpers.NormalizeVietnameseString(item.Value.TenVattu2);
                    double alt = CalculateSimilarity(getTenAlt, getTen2);
                    if (alt > final) final = alt;
                }

                if (final >= 90 && matchInput == regex.Match(getTen).Value)
                {
                    if (final > bestPercent)
                    {
                        bestPercent = final;
                        bestSoHieu = item.Key;
                    }
                    if (final >= 100) break;
                }
            }

            if (bestSoHieu != null)
            {
                tbImportDetail.SoHieu = bestSoHieu;
                tbImportDetail.Percent = Math.Round(bestPercent);
            }
            else
            {
                tbImportDetail.SoHieu = GenerateResultString(NormalizeVietnameseString(ten));
                tbImportDetail.Percent = 0;
            }

            // LƯU VÀO CACHE TOÀN CỤC
            _cacheToanCuc[key] = (tbImportDetail.SoHieu, tbImportDetail.Percent);
        }

        // Cấu trúc Tuple mới thêm trường TenChuan và QuyCach
        private Dictionary<string, (string TenChuan, string TenPhuChuan, string QuyCach, string DonVi,double Dongia,double soluong)> _optimizedVatTu;

        private void InitializeVatTuOptimization()
        {
            _optimizedVatTu = new Dictionary<string, (string, string, string, string,double,double)>();
            Regex regex = new Regex(@"(\d+(g|ml|L|kg)|x\d+|(\d+\s*cái))", RegexOptions.IgnoreCase);

            foreach (var item in vatTuLookup)
            {
                string ten1 = Helpers.NormalizeVietnameseString(item.Value.TenVattu);
                string ten2 = Helpers.NormalizeVietnameseString(item.Value.TenVattu2);
                string quyCach = regex.Match(ten1).Value;

                _optimizedVatTu[item.Key] = (ten1, ten2, quyCach, item.Value.DonVi,item.Value.Dongia,item.Value.SoLuong);
            }
        }
        public static bool HasParentheses(string text)
        {
            if (string.IsNullOrEmpty(text))
                return false;

            return text.Contains('(') && text.Contains(')');
        }
        public static string RemoveParentheses(string input)
        {
            if (string.IsNullOrEmpty(input)) return input;

            return System.Text.RegularExpressions.Regex.Replace(input, @"\s*\(.*?\)", "");
        } 
        private bool Kiemtragia(string Sohieu,double price)
        {
            var findvt = lstvt.Where(m => m.SoHieu == Sohieu).FirstOrDefault();
            if(findvt != null)
            {
               var getPriceCT = existingTbChungtu.AsEnumerable().OrderByDescending(m=>m.Field<DateTime>("NgayCT")).Where(m => m["MaVattu"].ToString()==findvt.MaSo.ToString() && !m["SoHieu"].ToString().Contains("GV")).FirstOrDefault();
                if (getPriceCT != null)
                {
                    double sops = double.Parse(getPriceCT["SoPS"].ToString());
                    double spNo = double.Parse(getPriceCT["SoPS2No"].ToString());
                    double spCo = double.Parse(getPriceCT["SoPS2Co"].ToString());
                    double dongia = 0;
                    if (spNo > 0)
                    {
                        dongia= sops/ spNo;
                    }
                    else
                    {
                        dongia = sops / spCo;
                    }
                    if(price==dongia)
                    {
                        return true;
                    }
                    else
                    {
                        return false;
                    }
                }
            }
            return false;
        }
