        private static string Normalize(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
                return "";

            text = text.ToLowerInvariant();

            // ===== TÁCH DÍNH =====

            // smcánh -> sm cánh
            text = Regex.Replace(
                text,
                @"(sm)([a-z])",
                "$1 $2"
            );

            // cánh20 -> cánh 20
            text = Regex.Replace(
                text,
                @"([a-zA-Z])(\d)",
                "$1 $2"
            );

            // 20g -> 20 g
            text = Regex.Replace(
                text,
                @"(\d)([a-zA-Z])",
                "$1 $2"
            );

            // cánhx20 -> cánh x 20
            text = Regex.Replace(
       text,
       @"([a-zA-Z])x(\d+)",
       "$1 x $2"
   );
            text = Regex.Replace(
    text,
    @"([a-zA-Z])\s*x\s*(\d+)",
    "$1 x $2"
);
            // ===== ALIAS =====

            var aliases = new Dictionary<string, string>
    {
                 { "st", "sieu tham" },
        { "kdr", "kem danh rang" },
        { "kđr", "kem danh rang" },
        { "sm", "sieu mong" },
        { "ss", "sach sau" },
        { "kd", "khong duong" },
    };

            foreach (var item in aliases)
            {
                text = Regex.Replace(
                    text,
                    $@"\b{item.Key}\b",
                    item.Value
                );
            }

            // bỏ ký tự đặc biệt
            text = Regex.Replace(
                text,
                @"[^\p{L}\p{N}\s]",
                " "
            );

            // bỏ space dư
            text = Regex.Replace(
                text,
                @"\s+",
                " "
            ).Trim();

            return text;
        }

        private static HashSet<string> GetImportantWords(string input)
        {
          
            input = Normalize(input);

            var result = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase);

            // alias
            foreach (var pair in BrandAliases)
            {
                if (pair.Value.ToString() == "C2")
                {
                    int a = 10;
                }
                foreach (var alias in pair.Value)
                {
                    if (input.Contains(alias))
                    {
                        result.Add(pair.Key);
                        break;
                    }
                }
            }

            // normal words
            foreach (var word in ImportantWords)
            {
                if (input.Contains(word))
                {
                    result.Add(word);
                }
            }

            return result;
        }

        public static double CompareProduct(string p1, string p2)
        {
            var set1 = GetImportantWords(p1);

            var set2 = GetImportantWords(p2);

            if (set1.Count == 0 || set2.Count == 0)
                return 0;

            int common = set1.Intersect(set2).Count();

            int total = set1.Union(set2).Count();

            return total == 0
                ? 0
                : (double)common / total;
        } 

