                            {
                                return;
                            }
                        }

                        //Load mặc định
                        if (tbDinhDanhtaikhoan.Rows.Count > 0)
                        {
                            string keyword = chkDauvao.Checked ? "Ưu tiên vào" : "Ưu tiên ra";

                            if (keyword != null)
