                                    TbImport.TkThue = foundRow["TKThue"].ToString();
                                }
                            }
                        }
                        TbImport.Status = 0;
                        TbImport.Ngaytao = DateTime.Now.ToShortDateString();

                        //Thông tin thanh toán
                        TbImport.TongTien = double.Parse(root.SelectSingleNode("//TgTTTBSo").InnerText);
                        TbImport.TgTCThue = root.SelectSingleNode("//TgTCThue") != null ? double.Parse(root.SelectSingleNode("//TgTCThue").InnerText) : 0;
                        TbImport.TgTThue = root.SelectSingleNode("//TgTThue") != null ? double.Parse(root.SelectSingleNode("//TgTThue").InnerText) : 0;

                        // Xử lý thuế suất với XmlReader cho hiệu quả
                        XmlNodeList nodeList = xmlDoc.SelectNodes("//LTSuat");
                        int index = 0;
                        foreach (XmlNode node in nodeList)
                        {
                            var suat = new SuatThue
