                                TSuat = node.SelectSingleNode("TSuat")?.InnerText,
                                ThTien = double.Parse(node.SelectSingleNode("ThTien")?.InnerText ?? "0"),
                                TThue = double.Parse(node.SelectSingleNode("TThue")?.InnerText ?? "0")
                            };
