                                var nodeGia = node.SelectSingleNode("DGia");
                                tbImportDetail.Dongia = nodeGia != null && double.TryParse(nodeGia.InnerText, out double value) ? value : 0;
                                if (tbImportDetail.TTien == 0)
                                    tbImportDetail.TTien = node.SelectSingleNode("ThTien") != null ? double.Parse(node.SelectSingleNode("ThTien")?.InnerText) : 0;

                                string keyCache = NormalizeVietnameseString(tbImportDetail.Ten);
