                                }
                                else
                                {
                                    Xulysohieuvattu(tbImportDetail);
                                    cacheMatHangTrongHoaDon[keyCache] = tbImportDetail;
                                }

                                tbImportDetail.Ten = Helpers.ConvertUnicodeToVni(tbImportDetail.Ten);
                                tbImportDetail.TKNo = TbImport.TKNo;
                                tbImportDetail.TKCo = TbImport.TKCo;
                                if (chkDauvao.Checked)
                                {
                                    if (tbImportDetail.Tchat == 3 || dagiam == true)
                                    {
                                        tbImportDetail.TKCo = "711";
                                    }
                                }
                                tbImportDetail.Percent = Math.Round(double.Parse(tbImportDetail.Percent.ToString()));
                                TbImport.tbImportDetails.Add(tbImportDetail);
                            }
                            catch (Exception ex)
                            {
                                XtraMessageBox.Show(node.SelectSingleNode("THHDVu")?.InnerText + "   " + TbImport.SHDon);
                            }
                        }

                        //Cập nhật nội dung cho Parent
                        if (string.IsNullOrEmpty(TbImport.Noidung))
                        {
                            if (TbImport.tbImportDetails.Count > 0)
                            {
                                TbImport.Noidung = TbImport.tbImportDetails.FirstOrDefault().Ten;
                            }
                        }

                        if (chkDauvao.Checked)
                        {
                            Xuly711(TbImport);
                            lstdsVao.Add(TbImport);
                            await SaveDataXmlOne(TbImport, chkDauvao.Checked ? 1 : 2);
