                                        TbImport.Ten = findKL.Field<string>("Ten");
                                        TbImport.Mst = findKL.Field<string>("SoHieu");
                                    }
                                }


                            }
                        }


                        //Chặn hoá đơn dc tải từ bước tải cơ quan thuế
                        if (chkDauvao.Checked)
                        {
                            if (lstdsVao.Any(m => m.SHDon == TbImport.SHDon && m.NLap.Date == TbImport.NLap.Date && m.Mst == TbImport.Mst))
                                return;
                        }
                        else
                        {
                            if (lstdsRa.Any(m => m.SHDon == TbImport.SHDon && m.NLap.Date == TbImport.NLap.Date && m.Mst == TbImport.Mst))
                                return;
                        }
                        //Kiểm tra hoá đon 
                        if (Kiemtrahoadon(TbImport.SHDon, TbImport.NLap, TbImport.Mst, type))
                            return;
                        if (KiemtrahoadonCT(TbImport.SHDon, TbImport.KHHDon, TbImport.NLap, TbImport.Mst, type))
                            return;

                        //if (chkDauvao.Checked)
                        //{
                        //    progressPanel1.Caption = $"Đang đọc file {stt}";
                        //    Application.DoEvents();
                        //}
                        //else
                        //{
                        //    progressPanel2.Caption = $"Đang đọc file {stt}";
                        //    Application.DoEvents();
                        //}
                        //Kiểm tra khách hàng có tạo chưa

                        if (TbImport.Mst != "KL")
                        {
                            if (CheckExistKH(TbImport.Mst) == false)
                            {
                                int maphanloai = 0;
                                maphanloai = type == 1 ? 2 : 3; //1 là mua, 2 là bán  
                                string diachi = "";
                                if (type == 1)
                                    diachi = root.SelectSingleNode("//NBan//DChi") != null ? root.SelectSingleNode("//NBan//DChi").InnerText : "";
                                else
                                    diachi = root.SelectSingleNode("//NMua//DChi") != null ? root.SelectSingleNode("//NMua//DChi").InnerText : "";

                                string sdt = "";
                                if (type == 1)
                                    sdt = root.SelectSingleNode("//NBan//SDThoai") != null ? root.SelectSingleNode("//NBan//SDThoai").InnerText : "";
                                else
                                    sdt = root.SelectSingleNode("//NMua//SDThoai") != null ? root.SelectSingleNode("//NMua//SDThoai").InnerText : "";
                                InitCustomer(maphanloai, Sohieu, TbImport.Ten, diachi, TbImport.Mst, "", sdt);
                            }
                        }
                        //Kiểm tra có tạo chưa
                        if (chkDauvao.Checked)
                        {
                            if (lstImportVao.Any(m => m.SHDon == TbImport.SHDon && m.NLap.Date == NLap.Date))
                            {
                                return;
                            }
                        }
                        else
                        {
                            if (lstImportRa.Any(m => m.SHDon == TbImport.SHDon && m.NLap.Date == NLap.Date))
                            {
                                return;
                            }
                        }


                        //Load mặc định
                        if (tbDinhDanhtaikhoan.Rows.Count > 0)
                        {
                            string keyword = chkDauvao.Checked ? "Ưu tiên vào" : "Ưu tiên ra";

                            if (keyword != null)
                            {
                                DataRow foundRow = tbDinhDanhtaikhoan.AsEnumerable()
                                    .FirstOrDefault(row => row.Field<string>("KeyValue")?.Contains(keyword) == true);

                                if (foundRow != null)
                                {
                                    TbImport.TKNo = foundRow["TKNo"].ToString();
                                    TbImport.TKCo = foundRow["TKCo"].ToString();
                                    TbImport.TkThue = foundRow["TKThue"].ToString();
                                }
                            }
                        }
                        TbImport.Status = 0;
                        TbImport.Ngaytao = DateTime.Now.ToShortDateString();


                        //Thông tin thanh toán
                        TbImport.TongTien = double.Parse(root.SelectSingleNode("//TgTTTBSo").InnerText);
                        TbImport.TgTCThue = root.SelectSingleNode("//TgTCThue") != null ? double.Parse(root.SelectSingleNode("//TgTCThue").InnerText) : 0;
                        TbImport.TgTThue = root.SelectSingleNode("//TgTThue") != null ? double.Parse(root.SelectSingleNode("//TgTThue").InnerText) : 0;
                        // TbImport.Vat = double.Parse(root.SelectSingleNode("//TSuat").InnerText.Replace("%",""));
                        //
                        XmlNodeList nodeList = xmlDoc.SelectNodes("//LTSuat");
                        int index = 0;
                        foreach (XmlNode node in nodeList)
                        {
                            var suat = new SuatThue
                            {
                                TSuat = node.SelectSingleNode("TSuat")?.InnerText,
                                ThTien = double.Parse(node.SelectSingleNode("ThTien")?.InnerText ?? "0"),
                                TThue = double.Parse(node.SelectSingleNode("TThue")?.InnerText ?? "0")
                            };
                            if (suat != null)
                            {
                                if (!string.IsNullOrEmpty(suat.TSuat))
                                {
                                    if (index == 0)
                                    {
                                        TbImport.TgTCThue1 = suat.ThTien;
                                        TbImport.TVat = suat.TThue;

                                        //KKKNT KCT
                                        if (suat.TSuat == "KCT" || suat.TSuat == "KKKNT")
                                        {
                                            TbImport.Vat = 0;
                                        }
                                        else
                                        {
                                            TbImport.Vat = double.Parse(suat.TSuat.Replace("%", ""));
                                        }
                                    }
                                    if (index == 1)
                                    {
                                        TbImport.TgTCThue2 = suat.ThTien;
                                        TbImport.TVat2 = suat.TThue;
                                        if (suat.TSuat == "KCT" || suat.TSuat == "KKKNT")
                                        {
                                            TbImport.Vat2 = "0";
                                        }
                                        else
                                        {
                                            TbImport.Vat2 = suat.TSuat.Replace("%", "");
                                        }
                                    }
                                    if (index == 2)
                                    {
                                        TbImport.TgTCThue3 = suat.ThTien;
                                        TbImport.TVat3 = suat.TThue;

                                        if (suat.TSuat == "KCT" || suat.TSuat == "KKKNT")
                                        {
                                            TbImport.Vat3 = "0";
                                        }
                                        else
                                        {
                                            TbImport.Vat3 = suat.TSuat.Replace("%", "");
                                        }
                                    }
                                }
                            }
                            index += 1;
                        }



                        //Trường hợp không chịu thuế
                        //if (vat == "KCT" || vat == "KKKNT")
                        //{
                        //    vat = "0";
                        //}

                        //KHMSHDon
                        TbImport.Khmshdon = root.SelectSingleNode("//KHMSHDon").InnerText;
                        string THDon = root.SelectSingleNode("//THDon").InnerText;
                         TbImport.hdon = "01";
                        if (Helpers.NormalizeVietnameseString(THDon.ToLower()).Contains("hóa đơn giá trị gia tăng") || Helpers.NormalizeVietnameseString(THDon.ToLower()).Contains("hóa đơn điện tử giá trị gia tăng"))
                        {
                            TbImport.hdon = "01";
                        }
                        if(Helpers.NormalizeVietnameseString(THDon.ToLower()).Contains("hóa đơn bán hàng"))
                        {
                            TbImport.hdon = "02";
                        }
                        XmlNodeList nodeListHHDVu = xmlDoc.SelectNodes("//HHDVu");
                        cacheMatHangTrongHoaDon = new Dictionary<string, TbImportDetail>(StringComparer.OrdinalIgnoreCase);

                        foreach (XmlNode node in nodeListHHDVu)
                        {
                            try
                            {
                                if (node.SelectSingleNode("THHDVu")?.InnerText == "Mì Cung Đình Koolspaghetti thố khuyến mãi")
                                {
                                    int tets = 10;
                                }
                                TbImportDetail tbImportDetail = new TbImportDetail();
                                if (Loaiborow(node.SelectSingleNode("THHDVu")?.InnerText))
                                    continue;
                                tbImportDetail.Tchat = int.Parse(node.SelectSingleNode("TChat")?.InnerText);
                                tbImportDetail.Ten = node.SelectSingleNode("THHDVu")?.InnerText;
                                bool dagiam = false;
                                if (tbImportDetail.Ten.Contains("Đã giảm"))
                                {
                                    dagiam = true;
                                    string pattern = @"\d{1,3}(?:\.\d{3})*(?:,\d+)?"; // Hỗ trợ cả định dạng số với dấu phẩy và dấu chấm
                                    Match match = Regex.Match(tbImportDetail.Ten, pattern);

                                    if (match.Success)
                                    {
                                        tbImportDetail.TTien = double.Parse(match.Value.Replace(".", ""));
                                    }
                                }
                                //Loại bỏ
                                if (tbImportDetail.Tchat == 4 && dagiam == false)
                                    continue;

                                var dvtNode = node.SelectSingleNode("DVTinh");
                                tbImportDetail.DVT = CapitalizeFirstLetter(
                                    Helpers.ConvertUnicodeToVni(dvtNode?.InnerText));

                                var slNode = node.SelectSingleNode("SLuong");
                                tbImportDetail.Soluong = slNode != null && double.TryParse(slNode.InnerText, out var qty) ? qty : 0;

                                var nodeGia = node.SelectSingleNode("DGia");
                                tbImportDetail.Dongia = nodeGia != null && double.TryParse(nodeGia.InnerText, out double value) ? value : 0;
                                if (tbImportDetail.TTien == 0)
                                    tbImportDetail.TTien = node.SelectSingleNode("ThTien") != null ? double.Parse(node.SelectSingleNode("ThTien")?.InnerText) : 0;


                                // —————— SIÊU TỐI ƯU TẠI ĐÂY (thay toàn bộ đoạn cũ) ——————
                                string keyCache = NormalizeVietnameseString(tbImportDetail.Ten); // dùng hàm chuẩn hóa của bạn
                                if (node.SelectSingleNode("THHDVu")?.InnerText == "Xăng RON 95 Mức 3")
                                {
                                    int a = 10;
                                }
                                if (cacheMatHangTrongHoaDon.TryGetValue(keyCache, out TbImportDetail daXuLy))
                                {
                                    // Đã xử lý rồi → copy kết quả
                                    tbImportDetail.SoHieu = daXuLy.SoHieu;
                                    tbImportDetail.Percent = daXuLy.Percent;
                                }
                                else
                                {
                                    // Chưa xử lý → gọi hàm gán mã (chỉ chạy 1 lần!)
                                    Xulysohieuvattu(tbImportDetail);

                                    // Lưu vào cache
                                    cacheMatHangTrongHoaDon[keyCache] = tbImportDetail;
                                }

                                //Kiem tra xem sản phẩm này đã xử lý chưa
                                //var checkExist = TbImport.tbImportDetails.Where(m => m.Ten == tbImportDetail.Ten).FirstOrDefault();
                                //if (checkExist == null)
                                //    Xulysohieuvattu(tbImportDetail);
                                //else
                                //{
                                //    tbImportDetail.SoHieu = checkExist.SoHieu;
                                //    tbImportDetail.Percent = checkExist.Percent;
                                //}
                                //Chuyển lại unicode sang vni cho tên
                                tbImportDetail.Ten = Helpers.ConvertUnicodeToVni(tbImportDetail.Ten);

                                //Điền tk nợ có
                                tbImportDetail.TKNo = TbImport.TKNo;
                                tbImportDetail.TKCo = TbImport.TKCo;
                                if (chkDauvao.Checked)
                                {
                                    if (tbImportDetail.Tchat == 3 || dagiam == true)
                                    {
                                        tbImportDetail.TKCo = "711";
                                    }
                                }
                                tbImportDetail.Percent = Math.Round(double.Parse(tbImportDetail.Percent.ToString()));
                                TbImport.tbImportDetails.Add(tbImportDetail);
                            }
                            catch (Exception ex)
                            {
                                XtraMessageBox.Show(node.SelectSingleNode("THHDVu")?.InnerText + "   " + TbImport.SHDon);
                            }

                        }

                        //Cập nhật nội dung cho Parent
                        if (string.IsNullOrEmpty(TbImport.Noidung))
                        {
                            if (TbImport.tbImportDetails.Count > 0)
                            {
                                TbImport.Noidung = TbImport.tbImportDetails.FirstOrDefault().Ten;
                            }

                        }

                        if (chkDauvao.Checked)
                        {
                            Xuly711(TbImport);
                            lstdsVao.Add(TbImport);
                            await SaveDataXmlOne(TbImport, chkDauvao.Checked ? 1 : 2);
                        }
                        else
                        {
                            //Xử lý 5211 trước
                            Xuly5211(TbImport);
                            lstdsRa.Add(TbImport);
                            await SaveDataXmlOne(TbImport, chkDauvao.Checked ? 1 : 2);
                        }

                        //Load chi tiết
                        stt += 1;
                    }
                }
            }
            catch (Exception ex)
            {
                XtraMessageBox.Show(pathXml);
            }
        }
        private async Task DocfileXmlOne2(string pathXml, int stt)
        {
            if (string.IsNullOrEmpty(pathXml)) return;

            string type = chkDauvao.Checked ? "1" : "2";
            TbImport tbImport = new TbImport { Type = type, Path = pathXml };

            try
            {
                // Sử dụng XmlReader để đọc nhanh, stream
                using (var reader = XmlReader.Create(pathXml, new XmlReaderSettings { IgnoreWhitespace = true }))
                {
                    // Cache các giá trị quan trọng
                    string nLapStr = null, shDon = null, khhDon = null, mstNban = null, mstNmua = null;
                    string tenNban = null, tenNmua = null, hvtNmua = null, cccd = null;
                    string tongTien = null, tgTCThue = null, tgTThue = null;
                    string khmshdon = null, thDon = null;
                    string noiDungDC = null;

                    var listSuatThue = new List<SuatThue>();
                    var listHHDVu = new List<HHDVuInfo>();

                    while (reader.Read())
                    {
                        if (reader.NodeType != XmlNodeType.Element) continue;

                        string localName = reader.LocalName;

                        if (localName == "NLap")
                        {
                            nLapStr = reader.ReadElementContentAsString();
                            tbImport.NLap = DateTime.Parse(nLapStr);
                        }
                        else if (localName == "SHDon")
                        {
                            shDon = reader.ReadElementContentAsString();
                            tbImport.SHDon = Helpers.RemoveLeadingZeros(shDon);
                        }
                        else if (localName == "KHHDon")
                        {
                            tbImport.KHHDon = reader.ReadElementContentAsString();
                        }
                        else if (localName == "MST")
                        {
                            string id = reader.GetAttribute("id");
                            if (id == "NBan") mstNban = reader.ReadElementContentAsString();
                            else if (id == "NMua") mstNmua = reader.ReadElementContentAsString();
                        }
                        else if (localName == "Ten")
                        {
                            string id = reader.GetAttribute("id");
                            if (id == "NBan") tenNban = reader.ReadElementContentAsString();
                            else if (id == "NMua") tenNmua = reader.ReadElementContentAsString();
                        }
                        else if (localName == "HVTNMHang")
                        {
                            hvtNmua = reader.ReadElementContentAsString();
                        }
                        else if (localName == "CCCDan")
                        {
                            cccd = reader.ReadElementContentAsString();
                        }
                        else if (localName == "TgTTTBSo")
                        {
                            tongTien = reader.ReadElementContentAsString();
                            tbImport.TongTien = double.Parse(tongTien);
                        }
                        else if (localName == "TgTCThue")
                        {
                            tgTCThue = reader.ReadElementContentAsString();
                            tbImport.TgTCThue = double.Parse(tgTCThue);
                        }
                        else if (localName == "TgTThue")
                        {
                            tgTThue = reader.ReadElementContentAsString();
                            tbImport.TgTThue = double.Parse(tgTThue);
                        }
                        else if (localName == "KHMSHDon")
                        {
                            tbImport.Khmshdon = reader.ReadElementContentAsString();
                        }
                        else if (localName == "THDon")
                        {
                            thDon = reader.ReadElementContentAsString();
                        }
                        else if (localName == "DLieu" && reader.ReadElementContentAsString().ToLower().Contains("điều chỉnh"))
                        {
                            noiDungDC = reader.ReadElementContentAsString();
                            tbImport.Noidung = Helpers.ConvertUnicodeToVni(noiDungDC);
                        }
                        // Suất thuế (giả sử cấu trúc LTSuat)
                        else if (localName == "TSuat" && reader.Depth == 4) // Trong LTSuat
                        {
                            string tSuat = reader.ReadElementContentAsString();
                            reader.ReadToNextSibling("ThTien");
                            double thTien = double.TryParse(reader.ReadElementContentAsString(), out double tt) ? tt : 0;
                            reader.ReadToNextSibling("TThue");
                            double tThue = double.TryParse(reader.ReadElementContentAsString(), out double tt2) ? tt2 : 0;
                            listSuatThue.Add(new SuatThue { TSuat = tSuat, ThTien = thTien, TThue = tThue });
                        }
                        // Hàng hóa dịch vụ
                        else if (localName == "HHDVu")
                        {
                            var hh = new HHDVuInfo();
                            while (reader.Read() && !(reader.NodeType == XmlNodeType.EndElement && reader.LocalName == "HHDVu"))
                            {
                                if (reader.NodeType != XmlNodeType.Element) continue;
                                string name = reader.LocalName;
                                if (name == "THHDVu") hh.Ten = reader.ReadElementContentAsString();
                                else if (name == "TChat") hh.TChat = int.Parse(reader.ReadElementContentAsString() ?? "0");
                                else if (name == "DVTinh") hh.DVT = reader.ReadElementContentAsString();
                                else if (name == "SLuong") hh.SoLuong = double.TryParse(reader.ReadElementContentAsString(), out double sl) ? sl : 0;
                                else if (name == "DGia") hh.DonGia = double.TryParse(reader.ReadElementContentAsString(), out double dg) ? dg : 0;
                                else if (name == "ThTien") hh.ThTien = double.TryParse(reader.ReadElementContentAsString() ?? "0", out double tt) ? tt : 0;
                            }
                            if (!string.IsNullOrEmpty(hh.Ten)) listHHDVu.Add(hh);
                        }
                    }

                    // Kiểm tra ngày sớm nhất
                    if (tbImport.NLap < dtTungay.DateTime || tbImport.NLap > dtDenngay.DateTime)
                        return;

                    // Kiểm tra trùng (dùng List.Any thay vì LINQ phức tạp)
                    var checkList = chkDauvao.Checked ? lstdsVao : lstdsRa;
                    if (checkList.Any(m => string.Equals(m.SHDon, tbImport.SHDon) && m.NLap.Date == tbImport.NLap.Date && string.Equals(m.Mst, tbImport.Mst)))
                        return;

                    if (Kiemtrahoadon(tbImport.SHDon, tbImport.NLap, tbImport.Mst, 1) || KiemtrahoadonCT(tbImport.SHDon, tbImport.KHHDon, tbImport.NLap, tbImport.Mst, 1))
                        return;

                    // Xử lý MST/Tên KH
                    if (type == "1") // Đầu vào
                    {
                        if (!string.Equals(mstcongty, mstNmua)) return;
                        tbImport.Ten = Helpers.ConvertUnicodeToVni(tenNban ?? "");
                        tbImport.Mst = mstNban ?? "";
                    }
                    else // Đầu ra
                    {
                        if (!string.Equals(mstcongty, mstNban)) return;
                        tbImport.Mst = mstNmua ?? "";
                        tbImport.Ten = !string.IsNullOrEmpty(tenNmua)
                            ? Helpers.ConvertUnicodeToVni(tenNmua)
                            : Helpers.ConvertUnicodeToVni(hvtNmua ?? "");

                        if (string.IsNullOrEmpty(tbImport.Ten) ||
                            tbImport.Ten.IndexOf("khách lẻ", StringComparison.OrdinalIgnoreCase) >= 0 ||
                            tbImport.Ten.IndexOf("không lấy hóa đơn", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            foreach (DataRow row in tbKhachhang.Rows)
                            {
                                if (string.Equals(row["SoHieu"] as string, "KL"))
                                {
                                    tbImport.Ten = row["Ten"] as string;
                                    tbImport.Mst = row["SoHieu"] as string;
                                    break;
                                }
                            }
                        }
                    }

                    // Xử lý MST rỗng
                    if (string.IsNullOrEmpty(tbImport.Mst))
                    {
                        tbImport.Mst = cccd ?? "";
                        if (string.IsNullOrEmpty(tbImport.Mst) && !string.IsNullOrEmpty(tbImport.Ten))
                        {
                            bool found = false;
                            foreach (DataRow row in tbKhachhang.Rows)
                            {
                                if (string.Equals(row["Ten"] as string, tbImport.Ten))
                                {
                                    tbImport.Mst = row["SoHieu"] as string;
                                    found = true;
                                    break;
                                }
                            }
                            if (!found)
                            {
                                string baseCode = GenerateAbbreviation(Helpers.ConvertVniToUnicode(tbImport.Ten), tbKhachhang.AsEnumerable().Select(r => r.Field<string>("SoHieu")).ToList()).ToUpper();
                                string finalCode = baseCode;
                                int suffix = 1;
                                while (tbKhachhang.AsEnumerable().Any(r => string.Equals(r.Field<string>("SoHieu"), finalCode)))
                                    finalCode = baseCode + "_" + suffix++;
                                tbImport.Mst = finalCode;
                            }
                        }
                    }

                    // Loại hóa đơn
                    string thDonNorm = Helpers.NormalizeVietnameseString(thDon?.ToLower() ?? "");
                    if (thDonNorm.Contains("giá trị gia tăng"))
                        tbImport.hdon = "01";
                    else if (thDonNorm.Contains("bán hàng"))
                        tbImport.hdon = "02";
                    else
                        tbImport.hdon = "01";

                    // Suất thuế
                    for (int i = 0; i < listSuatThue.Count && i < 3; i++)
                    {
                        var s = listSuatThue[i];
                        if (i == 0)
                        {
                            tbImport.TgTCThue1 = s.ThTien;
                            tbImport.TVat = s.TThue;
                            tbImport.Vat = (s.TSuat == "KCT" || s.TSuat == "KKKNT") ? 0 : double.Parse(s.TSuat.Replace("%", ""));
                        }
                        else if (i == 1)
                        {
                            tbImport.TgTCThue2 = s.ThTien;
                            tbImport.TVat2 = s.TThue;
                            tbImport.Vat2 = (s.TSuat == "KCT" || s.TSuat == "KKKNT") ? "0" : s.TSuat.Replace("%", "");
                        }
                        else if (i == 2)
                        {
                            tbImport.TgTCThue3 = s.ThTien;
                            tbImport.TVat3 = s.TThue;
                            tbImport.Vat3 = (s.TSuat == "KCT" || s.TSuat == "KKKNT") ? "0" : s.TSuat.Replace("%", "");
                        }
                    }

                    // Tài khoản mặc định
                    if (tbDinhDanhtaikhoan.Rows.Count > 0)
                    {
                        string keyword = chkDauvao.Checked ? "Ưu tiên vào" : "Ưu tiên ra";
                        foreach (DataRow row in tbDinhDanhtaikhoan.Rows)
                        {
                            string key = row["KeyValue"] as string;
                            if (key != null && key.IndexOf(keyword) >= 0)
                            {
                                tbImport.TKNo = row["TKNo"].ToString();
                                tbImport.TKCo = row["TKCo"].ToString();
                                tbImport.TkThue = row["TKThue"].ToString();
                                break;
                            }
                        }
                    }

                    tbImport.Status = 0;
                    tbImport.Ngaytao = DateTime.Now.ToShortDateString();

                    // Cache vật tư trong hóa đơn
                    var cacheMatHang = new Dictionary<string, TbImportDetail>(StringComparer.OrdinalIgnoreCase);

                    foreach (var hh in listHHDVu)
                    {
                        if (Loaiborow(hh.Ten)) continue;

                        var detail = new TbImportDetail
                        {
                            Tchat = hh.TChat,
                            Ten = hh.Ten,
                            DVT = CapitalizeFirstLetter(Helpers.ConvertUnicodeToVni(hh.DVT)),
                            Soluong = hh.SoLuong,
                            Dongia = hh.DonGia,
                            TTien = hh.ThTien
                        };

                        bool daGiam = detail.Ten.IndexOf("Đã giảm") >= 0;
                        if (daGiam && detail.TTien == 0)
                        {
                            var match = Regex.Match(detail.Ten, @"\d{1,3}(?:\.\d{3})*(?:,\d+)?");
                            if (match.Success)
                                detail.TTien = double.Parse(match.Value.Replace(".", "").Replace(",", ""));
                        }

                        if (detail.Tchat == 4 && !daGiam) continue;

                        string cacheKey = Helpers.NormalizeVietnameseString(detail.Ten);
                        if (cacheMatHang.TryGetValue(cacheKey, out var cached))
                        {
                            detail.SoHieu = cached.SoHieu;
                            detail.Percent = cached.Percent;
                        }
                        else
                        {
                            Xulysohieuvattu(detail);
                            cacheMatHang[cacheKey] = detail;
                        }

                        detail.Ten = Helpers.ConvertUnicodeToVni(detail.Ten);
                        detail.TKNo = tbImport.TKNo;
                        detail.TKCo = tbImport.TKCo;

                        if (chkDauvao.Checked && (detail.Tchat == 3 || daGiam))
                            detail.TKCo = "711";

                        detail.Percent = Math.Round(detail.Percent);

                        tbImport.tbImportDetails.Add(detail);
                    }

                    // Nội dung mặc định
                    if (string.IsNullOrEmpty(tbImport.Noidung) && tbImport.tbImportDetails.Count > 0)
                        tbImport.Noidung = tbImport.tbImportDetails[0].Ten;

                    // Lưu
                    if (chkDauvao.Checked)
                    {
                        Xuly711(tbImport);
                        lstdsVao.Add(tbImport);
                    }
                    else
                    {
                        Xuly5211(tbImport);
                        lstdsRa.Add(tbImport);
                    }

                    await SaveDataXmlOne(tbImport, int.Parse(type));
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Lỗi đọc file {pathXml}: {ex.Message}");
                // Nếu cần UI, dùng Invoke để tránh deadlock
                // this.Invoke(new Action(() => XtraMessageBox.Show($"Lỗi: {ex.Message}")));
            }
        }
