        public void Xuly5211(TbImport fileImport)
        {
            if (tbLicense.Rows[0].Field<string>("col711ra") == "1")
            {
                //Trường hợp có 5113
                var kiemtra5113 = fileImport.tbImportDetails.Where(m => m.TKCo.Contains("5113")).FirstOrDefault();
                if (kiemtra5113 != null)
                {
                    var find5211 = fileImport.tbImportDetails.Where(m => m.Tchat == 3).ToList();
                    if (find5211 != null && find5211.Count > 0)
                    {
                        //Cập nhật giảm trừ cho tk 5113 đầu tiên
                        kiemtra5113.TTien -= find5211.Sum(m => m.TTien);
                        //Cập nhật trong database 
                        //Thực hiện xoá dòng 5211
                        foreach (var r52 in find5211)
                        { 
                            fileImport.tbImportDetails.Remove(r52);
                        } 
                        return;
                    }
                }
            }
            foreach (var code in accountCodes)
            {
                if (fileImport.tbImportDetails.Any(m => m.TKCo.Contains(code)))
                {
                    var find5211 = fileImport.tbImportDetails.Where(m => m.Tchat == 3).ToList();
                    //Xoá và gộp 5211
                    var first5211 = find5211.FirstOrDefault();
                    var lst5211remain = find5211.Where(m => m != first5211).ToList();
                    if (first5211 != null)
                    {
                        first5211.TTien += lst5211remain.Sum(m => m.TTien);
                        first5211.TKNo = fileImport.tbImportDetails
                            .FirstOrDefault(m => m.TKCo.Contains(code))?.TKCo;
                        first5211.TKCo = "";
                    }
                    //Xoá remain
                    foreach (var it in lst5211remain)
                    { 
                        fileImport.tbImportDetails.Remove(it);
                    }
                    return;
                }
            }
        }
        public void GetKNMXML(string nbmst, string khhdon, string shdon, string tokken,DateTime GetNLap,string path,string filename)
        {
            GDTClient.UpdateToken(tokken);
            string url = $"https://hoadondientu.gdt.gov.vn/api/query/invoices/detail?nbmst={nbmst}&khhdon={khhdon}&shdon={shdon}&khmshdon=1";
             
            using (var client = new HttpClient())
            {
                //client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", tokken);
                //client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));

                try
                {
                    // Gửi yêu cầu GET đồng bộ
                    string responseBody = Task.Run(async () => await GDTClient.GetJsonAsync(url)).Result;
                    if (string.IsNullOrEmpty(responseBody))
                    {
                        currentProgress += 1;
                        return;
                    }
                    var rootObject = JsonConvert.DeserializeObject<Invoice>(responseBody);
                    // Tạo phần tử gốc <HDon>
                    TaoFileXmlChiCoDLHDon(path, filename.Replace(".zip",""), rootObject,GetNLap);
                    currentProgress += 1;

                   string ph = Path.Combine( path, filename.Replace(".zip","_KNM.xml"));
                    DocfileXmlOne(ph, currentIndex);
                    progressPanel1.Caption = $"Đang đọc file thứ {currentProgress} / {totalInvoices}";
                    if(currentProgress== totalInvoices)
                    {
                        modeClick = 2;
                        btnChonthang.PerformClick();
                    }
                }
                catch (HttpRequestException e)
                {
                    Console.WriteLine($"Request error: {e.Message}");
                }
            }
        }
        public static string TaoFileXmlChiCoDLHDon(string folderPath, string fileName = "HDon_44020.xml", Invoice Invoice=default,DateTime NLap=default)
        {
            // Tạo thư mục nếu chưa có
            if (!Directory.Exists(folderPath))
                Directory.CreateDirectory(folderPath); 
            fileName = $"{fileName}_KNM.xml";
            string fullPath = Path.Combine(folderPath, fileName);

            XmlDocument doc = new XmlDocument();
            XmlElement root = doc.CreateElement("HDon");
            doc.AppendChild(root);

            // ==================== <DLHDon> ====================
            XmlElement dlHDon = doc.CreateElement("DLHDon");
            dlHDon.SetAttribute("Id", "DuLieuKy");
            root.AppendChild(dlHDon);

            // ---- TTChung ----
            XmlElement ttChung = doc.CreateElement("TTChung");
            dlHDon.AppendChild(ttChung);

            ThemPhanTu(doc, ttChung, "PBan", $"{Invoice.Pban}");
            ThemPhanTu(doc, ttChung, "THDon", $"Hóa đơn GTGT");
            ThemPhanTu(doc, ttChung, "KHMSHDon", $"{Invoice.Khmshdon}");
            ThemPhanTu(doc, ttChung, "KHHDon", $"{Invoice.Khhdon}");
            ThemPhanTu(doc, ttChung, "SHDon", $"{Invoice.Shdon}");
            ThemPhanTu(doc, ttChung, "NLap", $"{NLap}");
            ThemPhanTu(doc, ttChung, "HDCTTChinh", "0");
            ThemPhanTu(doc, ttChung, "DVTTe", $"{Invoice.Dvtte}");
            ThemPhanTu(doc, ttChung, "TGia", $"{Invoice.Tgia}");
            ThemPhanTu(doc, ttChung, "HTTToan", $"{Invoice.Thtttoan}");
            ThemPhanTu(doc, ttChung, "MSTTCGP", $"{Invoice.Msttcgp}");

            // TTKhac trong TTChung
            XmlElement ttKhacChung = doc.CreateElement("TTKhac");
            XmlElement tTin1 = TaoTTin(doc, "Extra", "string", "ThuyUyen.Nguyen@britishcouncil.org");
            ttKhacChung.AppendChild(tTin1);
            ttChung.AppendChild(ttKhacChung);

            // ---- NDHDon ----
            XmlElement ndHDon = doc.CreateElement("NDHDon");
            dlHDon.AppendChild(ndHDon);

            // NBan
            XmlElement nBan = doc.CreateElement("NBan");
            ThemPhanTu(doc, nBan, "Ten", $"{Invoice.Nbten}");
            ThemPhanTu(doc, nBan, "MST", $"{Invoice.Nbmst}");
            ThemPhanTu(doc, nBan, "DChi", $"{Invoice.Nbdchi}");
            ThemPhanTu(doc, nBan, "SDThoai", $"{Invoice.Nbsdthoai}");
            ndHDon.AppendChild(nBan);

            // NMua
            XmlElement nMua = doc.CreateElement("NMua");
            ThemPhanTu(doc, nMua, "Ten", $"{Invoice.Nmten}");
            ThemPhanTu(doc, nMua, "MST", $"{Invoice.Nmmst}");
            ThemPhanTu(doc, nMua, "DChi", $"{Invoice.Nmdchi}");
            ThemPhanTu(doc, nMua, "MKHang", $"{Invoice.Mkhang}");
            ThemPhanTu(doc, nMua, "HVTNMHang", "");
            ndHDon.AppendChild(nMua);

            // DSHHDVu
            XmlElement dsHHDVu = doc.CreateElement("DSHHDVu");
            ndHDon.AppendChild(dsHHDVu);

            // Hàng hóa dịch vụ 1
            int stt = 1;
            foreach(var dt in Invoice.Hdhhdvu.ToList())
            {
                TaoHangHoa(doc, dsHHDVu, "0", $"{stt}",!string.IsNullOrEmpty(dt.Ten)? $"{dt.Ten}":"Hoá đơn không nhận mã", $"{dt.Dvtinh}", $"{dt.Sluong}", $"{dt.Dgia}", $"{dt.Tsuat.Value*100}", $"{dt.Thtien}",
              new[] { ("Amount", "numeric", $"{dt.Thtien}"), ("VATAmount", "numeric", "0") });
                stt++;
            }
          
 
            // TToan
            XmlElement tToan = doc.CreateElement("TToan");
            ndHDon.AppendChild(tToan);

            // TTKhac trong TToan
            XmlElement ttKhacToan = doc.CreateElement("TTKhac");
            ttKhacToan.AppendChild(TaoTTin(doc, "ServiceProvided", "String", "Le phi thi"));
            ttKhacToan.AppendChild(TaoTTin(doc, "Location", "String", "British Council Ho Chi Minh City"));
            ttKhacToan.AppendChild(TaoTTin(doc, "Datasource", "String", "ORS2"));
            tToan.AppendChild(ttKhacToan);

            // Tổng hợp thuế suất
            XmlElement tHTTLTSuat = doc.CreateElement("THTTLTSuat");
            XmlElement lTSuat = doc.CreateElement("LTSuat");
            ThemPhanTu(doc, lTSuat, "TSuat", $"{Invoice.Hdhhdvu.FirstOrDefault()?.Tsuat.Value*100}");
            ThemPhanTu(doc, lTSuat, "TThue", $"{Invoice.Tgtthue}");
            ThemPhanTu(doc, lTSuat, "ThTien", $"{Invoice.Tgtcthue}");
            tHTTLTSuat.AppendChild(lTSuat);
            tToan.AppendChild(tHTTLTSuat);
            if (Invoice.Tgtphi.HasValue)
            {
                XmlElement TPhi = doc.CreateElement("TPhi");
                ThemPhanTu(doc, TPhi, "ThTien", $"{Invoice.Tgtphi}");
                tToan.AppendChild(TPhi);
            }

            if(Invoice.Tgtphi.HasValue)
                ThemPhanTu(doc, tToan, "TgTCThue", $"{Invoice.Tgtcthue }");
            else
                ThemPhanTu(doc, tToan, "TgTCThue", $"{Invoice.Tgtcthue}");
            ThemPhanTu(doc, tToan, "TgTThue", $"{Invoice.Tgtthue}");
            ThemPhanTu(doc, tToan, "TTCKTMai", $"{Invoice.Ttcktmai}");
            ThemPhanTu(doc, tToan, "TgTTTBSo", $"{Invoice.Tgtttbso}");
            ThemPhanTu(doc, tToan, "TgTTTBChu", $"{Invoice.Tgtttbchu}");

            // Lưu file đẹp
            XmlWriterSettings settings = new XmlWriterSettings
            {
                Indent = true,
                IndentChars = "  ",
                NewLineChars = "\r\n",
                Encoding = System.Text.Encoding.UTF8
            };

            using (XmlWriter writer = XmlWriter.Create(fullPath, settings))
            {
                doc.Save(writer);
            }

            return fullPath;
        }

        // Hàm phụ trợ
        static void ThemPhanTu(XmlDocument doc, XmlElement parent, string ten, string giaTri)
        {
            XmlElement e = doc.CreateElement(ten);
            e.InnerText = giaTri;
            parent.AppendChild(e);
        }

        static XmlElement TaoTTin(XmlDocument doc, string tTruong, string kDLieu, string dLieu)
        {
            XmlElement ttin = doc.CreateElement("TTin");
            ThemPhanTu(doc, ttin, "TTruong", tTruong);
            ThemPhanTu(doc, ttin, "KDLieu", kDLieu);
            ThemPhanTu(doc, ttin, "DLieu", dLieu);
            return ttin;
        }

        static void TaoHangHoa(XmlDocument doc, XmlElement ds, string tChat, string stt, string tenHang, string dvTinh,
            string sl, string dGia, string tSuat, string thTien, (string truong, string kieu, string giaTri)[] extra)
        {
            XmlElement hh = doc.CreateElement("HHDVu");
            ThemPhanTu(doc, hh, "TChat", tChat);
            ThemPhanTu(doc, hh, "STT", stt);
            ThemPhanTu(doc, hh, "THHDVu", tenHang);
            if (!string.IsNullOrEmpty(dvTinh)) ThemPhanTu(doc, hh, "DVTinh", dvTinh);
            ThemPhanTu(doc, hh, "SLuong", sl);
            ThemPhanTu(doc, hh, "DGia", dGia);
            ThemPhanTu(doc, hh, "TSuat", tSuat);
            ThemPhanTu(doc, hh, "ThTien", thTien);

            XmlElement ttKhac = doc.CreateElement("TTKhac");
            foreach (var item in extra)
                ttKhac.AppendChild(TaoTTin(doc, item.truong, item.kieu, item.giaTri));

            hh.AppendChild(ttKhac);
            ds.AppendChild(hh);
        }
        public void DocfileExcelRa()
        {
            
            string directoryPath = Path.Combine(savedPath, "HDRa", dtTungay.DateTime.Month.ToString());

            var excelFiles = Directory.EnumerateFiles(directoryPath, "*.xlsx", SearchOption.AllDirectories).Where(m => m.Contains(mstcongty)).ToList();
            tongsohodadon = excelFiles.Count;
            int i = 1;
            foreach (var excelFile in excelFiles)
            {
                using (var workbook = new XLWorkbook(excelFile))

                {
                    var worksheet = workbook.Worksheet(1); // Lấy sheet đầu tiên
                    foreach (var row in worksheet.RowsUsed().Skip(3)) // Bỏ qua 6 hàng đầu tiên
                    {
                        string khhd = row.Cell("B").Value.ToString(); // Lấy giá trị của cột A trong hàng hiện tại
                        string getSHHD = row.Cell("C").Value.ToString(); // Lấy giá trị của cột A trong hàng hiện tại
                        string getSohd = Helpers.RemoveLeadingZeros(row.Cell("D").Value.ToString()); // Lấy giá trị của cột C trong hàng hiện tại 
                        string GetNLap = row.Cell("E").Value.ToString();
                        string mstnb = row.Cell("F").Value.ToString();

                        //Kiểm tra từ ngày đến ngày
                        DateTime getdate = DateTime.Parse(GetNLap);
                        if (getdate < dtTungay.DateTime || getdate > dtDenngay.DateTime)
                            continue;

                        //Kiểm tra xem hoá đơn đã có trong bảng tbimport chưa
                        //var checkFile=tbimport.AsEnumerable().Where()
                        //Tải file xml
                        string url = "";
                        if (i == 1)
                            url = $"https://hoadondientu.gdt.gov.vn/sco-query/invoices/export-xml?nbmst={mstcongty}&khhdon={getSHHD}&shdon={getSohd}&khmshdon={khhd}";
                        if (i ==2)
                        {
                            url = $"https://hoadondientu.gdt.gov.vn/query/invoices/export-xml?nbmst={mstcongty}&khhdon={getSHHD}&shdon={getSohd}&khmshdon={khhd}";
                            //https://hoadondientu.gdt.gov.vn/sco-query/invoices/export-xml?nbmst=0316158113-006&khhdon=C25MVX&shdon=660264&khmshdon=1

                        }
                        string pathravao = "HDRa";
                        string filename = $"{mstcongty}_{getSohd}_{getSHHD}.zip";
                        string filenameCheck = $"{mstcongty}_{getSohd}_{getSHHD}.html";
                        string path = Path.Combine(savedPath, pathravao, dtTungay.DateTime.Month.ToString(), filename);
                        string pathcheck = Path.Combine(savedPath, pathravao, dtTungay.DateTime.Month.ToString(), filenameCheck);

                        //Kiểm tra nếu hoá đơn chưa dc tải thì tải về
                        if (!File.Exists(pathcheck))
                        {
                            using (var client = new HttpClient())
                            {
                                client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", tokken);
                                client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/octet-stream"));

                                try
                                {
                                    HttpResponseMessage response = client.GetAsync(url).Result; // Sử dụng .Result
                                    response.EnsureSuccessStatusCode(); // Ném ngoại lệ nếu không thành công

                                    // Đọc nội dung phản hồi dưới dạng byte
                                    var fileBytes = response.Content.ReadAsByteArrayAsync().Result;

                                    // Lưu file ZIP bằng FileStream
                                    using (var fileStream = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize: 4096))
                                    {
                                        fileStream.Write(fileBytes, 0, fileBytes.Length);
                                    }

                                    Console.WriteLine($"File ZIP đã được lưu tại: {path}");
                                    ExtractZipXML(path); // Giải nén file ZIP
                                    //progressPanel1.Caption = $"Đang đọc hoá đơn";
                                    //Application.DoEvents();
                                }
                                catch (Exception ex)
                                {
                                    Console.WriteLine($"Đã xảy ra lỗi: {ex.Message}");
                                }
                            }
                        }
                    }
                }
                i++;
            }
        }
