        public void CustomDrawcellGrid(DevExpress.XtraGrid.Views.Base.RowCellCustomDrawEventArgs e, GridView grid, int type)
        {

            int rowHandle = e.RowHandle;
            if ((e.Column.FieldName == "Noidung" || e.Column.FieldName == "Index") && hienthimau)
            {
              

                var getcellValue = grid.GetRowCellValue(rowHandle, "Noidung");
                if (getcellValue!=null && (getcellValue.ToString().Contains("Điều chỉnh") || getcellValue.ToString().Contains("Thay thế")))
                {
                    e.Appearance.Font = new Font(e.Appearance.Font, FontStyle.Bold);
                    e.Appearance.ForeColor = Color.Red; // Tô màu chữ đỏ
                    return;
                }
            }
            if (e.Column.FieldName == "Index" && hienthimau)
            {
