                                        var ffindmpl = ListPhanloaiVattu.AsEnumerable().Where(m => m.Field<string>("SoHieu") == "TP").FirstOrDefault();
                                        int findmpl = 0;
                                        if (ffindmpl != null)
                                        {
                                            findmpl= ffindmpl.Field<int>("MaSo");
                                        }
                                        
                                    }
                                }
                               
                            }
                        }
                       // e.Appearance.ForeColor = Color.Red; // Tô màu chữ đỏ
                      //  cellColors[(rowHandle, e.Column.FieldName)] = Color.Red; // Lưu màu 
                        return;
                    }
                     
                        // Trường hợp hàng có sl <=0
                        var findVt = lstvt.FirstOrDefault(m => m.SoHieu.ToString().ToLower() == item["SoHieu"].ToString().ToLower());
                    if (findVt != null && findVt.SoLuong <= 0 && type == 2)
