    .FirstOrDefault(m => m.Field<string>("SoHieu") == "TP");

                        int findmpl = foundItem != null ? foundItem.Field<int>("MaSo") : -1; // Hoặc giá trị mặc định khác
                        if (findVt.MaPhanLoai!=findmpl)
                        {  //if(findVt.MaPhanLoai)
                          
                            hashh = true;
                        }
                        e.Appearance.ForeColor = Color.Red; // Tô màu chữ đỏ
