        static string RemoveDecimal(string number)
        {
            // Chỉ loại bỏ ".00" ở cuối
            if (number.EndsWith(".00"))
            {
                return number.Substring(0, number.Length - 3); // Cắt bỏ 3 ký tự cuối
            }
            return number; // Nếu không có ".00", trả về số nguyên
        }
        public int FindfirstrowBank(ClosedXML.Excel.IXLRow row)
        {
            string[] headers=null;
            //Acb header
            //if (lblTKNganHangTitle.Text.ToLower().Contains("acb") || lblTKNganHangTitle.Text.ToLower().Contains("á châu"))
            headers = new string[] {"Ngay hieu luc","Noi dung giao dich", "Ghi no","Ghi co", "Chi tiết giao dịch","Ngay giao dich","Ngày giá trị","Nợ","Có","Dien giai","So du","NGÀY GIAO DỊCH", "PHÁT SINH NỢ", "PHÁT SINH CÓ","SỐ DƯ", "Ngày giao dịch", "Debit", "Credit", "Balance", "Remark","Details", "Số tiền ghi nợ", "Số tiền ghi có", "Deposit", "Remarks", "Withdrawal","Số tiền rút ra","Số tiền gửi vào", "số dư", "GD", "Ghi nợ", "Ghi có", "Mô tả", "PHÁT SINH CÓ", "PHÁT SINH NỢ", "Số dư", "Nội dung", "Noi dung chi tiet", "Ngay GD" , "So tien ghi no", "So tien ghi co","Phát sinh co", "Số tiền rút", "Số tiền gửi" };
            int countcol = 0;
            bool isHeaderRow = false;
            for (int i = 1; i <= 12; i++)
            {
                if (isHeaderRow)
                    break;
                string cellValue1 = row.Cell(i).GetString();
                foreach (var item in headers)
                {
                    if (cellValue1.Contains(item))
                    {
                        countcol += 1;
                        if (countcol >= 3)
                        {
                            isHeaderRow = true;
                            break;
                        }
                    }
                }
            }

            return countcol;
        }
        public static DateTime? ExtractDateWithRegex(string cellContent)
        {
            if (string.IsNullOrEmpty(cellContent))
                return null;

            // Pattern cho ngày tháng: dd/mm/yyyy hoặc d/m/yyyy
            string pattern = @"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b";

            Match match = Regex.Match(cellContent, pattern);

            if (match.Success)
            {
                try
                {
                    int day = int.Parse(match.Groups[1].Value);
                    int month = int.Parse(match.Groups[2].Value);
                    int year = int.Parse(match.Groups[3].Value);

                    return new DateTime(year, month, day);
                }
                catch
                {
                    return null;
                }
            }

            return null;
        }
