        int stt = 0;
        public static string IncrementSuffix(string input)
        {
            // Tìm '/' và tách chuỗi
            int index = input.LastIndexOf('/');
            if (index == -1)
            {
                //throw new ArgumentException("Chuỗi không chứa ký tự '/'");
                return "";
            }

            string prefix = input.Substring(0, index + 1); // Lấy phần trước '/'
            int number = int.Parse(input.Substring(index + 1)); // Lấy phần sau '/'

            // Tăng số lên 1
            number++;

            // Ghép lại chuỗi
            return prefix + number.ToString("D2"); // Định dạng thành 2 chữ số
        }
