                    txtBankIndexNoidung.Text = "3";
                    txtBankIndexTT1.Text = "4";
                    txtBankIndexTT2.Text = "5";
                    break;

                case string s when s.Contains("agr"):
                    txtBankIndexNgay.Text = "1";
                    txtBankIndexNoidung.Text = "2";
                    txtBankIndexTT1.Text = "3";
                    txtBankIndexTT2.Text = "4";
                    break;
                case string s when s.Contains("hd"):
                    txtBankIndexNgay.Text = "2";
                    txtBankIndexNoidung.Text = "5";
                    txtBankIndexTT1.Text = "7";
                    txtBankIndexTT2.Text = "8";
                    break;
                case string s when s.Contains("bidv"):
                    txtBankIndexNgay.Text = "3";
                    txtBankIndexNoidung.Text = "11";
                    txtBankIndexTT1.Text = "5";
                    txtBankIndexTT2.Text = "6";
                    break;
            }


        }
        private void DocfileNganhangExcel(string path)
        {
            
            progressPanel4.Caption = "Đang đọc dữ liệu";
              var query = "SELECT * FROM tbMatdinhghichu"; // Giả sử bạn muốn lấy tất cả dữ liệu từ bảng KhachHang
            DataTable tbMatdinhghichu = ExecuteQuery(query);

            string tknganhang = labelControl23.Text.Split('-')[0].ToString();
            string[] headers = { "rút ra", "Ngày hạch toán", "Withdrawal", "Dr", "Debit amount", "Balance" };
            using (var workbook = new XLWorkbook(path))
            {
                stt = 0;
                bool generate = false;
                string getlastString = "";
                foreach (var worksheet in workbook.Worksheets)
                {
                  
                    int findrow =0;
                    //Tìm row
                    foreach (var row in worksheet.Rows())
                    {
                        //foreach (var cell in row.Cells())
                        //{

                        //}
                        string cellValue1 = row.Cell(txtBankIndexTT1.Text).GetString(); // Cột A
                        if (headers.Any(header => cellValue1.Contains(header)))
                        {
                            findrow= row.RowNumber();
                        } 
                    }

                    //Đọc nội dung
                  
                    foreach (var row in worksheet.Rows().Skip(findrow))
                    {
                      
                        //Lấy nội dung cột ngày
                        string getNgay = row.Cell(txtBankIndexNgay.Text).GetString(); // Cột A
                        string getNoidung = row.Cell(txtBankIndexNoidung.Text).GetString(); // Cột A
                        Nganhang nganhang = new Nganhang();
                        nganhang.Diengiai = getNoidung.Replace("\r\n", " ")
                  .Replace("\n", " ")
                  .Replace("\r", " ");                                               //Lấy nội dung cột nội dung
                        if (string.IsNullOrEmpty(nganhang.Diengiai))
                            continue;
                       
                        stt += 1;
                        if (!string.IsNullOrEmpty(getNgay) && DateTime.TryParse(getNgay, out DateTime parsedDate))
                        {
                            nganhang.NgayGD = parsedDate;
                        }
                        else
                        {
                            nganhang.NgayGD = DateTime.MinValue; // Hoặc giá trị mặc định khác nếu cần
                        } 
                        if (nganhang.NgayGD==DateTime.MinValue)
                        {
                            //continue;
                        }
                        
                        try
                        {
                            string number1 = row.Cell(txtBankIndexTT1.Text).GetString().Replace(".", "").Replace(",", "");
                            nganhang.ThanhTien = !string.IsNullOrEmpty(number1) ? double.Parse(number1) : 0;
                            string number2 = row.Cell(txtBankIndexTT2.Text).GetString().Replace(".", "").Replace(",", "");
                            nganhang.ThanhTien2 = !string.IsNullOrEmpty(number2) ? double.Parse(number2) : 0;
                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine(ex.Message);
                        }
                        //Kiểm tra chứng từ này đã import chưa
                        if (existingTbChungtu.AsEnumerable().Any(m => m.Field<DateTime>("NgayCT").Date == nganhang.NgayGD.Date && (m.Field<double>("SoPS") == nganhang.ThanhTien || m.Field<double>("SoPS") == nganhang.ThanhTien2)))
                            continue;
                        //Load mã số
                        var getLastctNganhang = existingTbChungtu.AsEnumerable().Where(m => m["MaLoai"].ToString() == "4" && m.Field<DateTime>("NgayCT").Month== nganhang.NgayGD.Month && nganhang.NgayGD!=DateTime.MinValue).LastOrDefault();
                        if (getLastctNganhang != null && !generate)
                        {
                            generate = true;
                            getlastString = getLastctNganhang.Field<string>("SoHieu");
                            nganhang.Maso = IncrementSuffix(getlastString);
                        }
                        else
                        {
                            if (generate)
                            {
                                getlastString = IncrementSuffix(getlastString);
                                nganhang.Maso = getlastString;
                            }
                            else
                            {
                                generate = true;
                                if (labelControl23.Text.ToLower().Contains("acb"))
                                {
                                    getlastString = $"ACB{nganhang.NgayGD.Month}/01";
                                }
                                if (labelControl23.Text.ToLower().Contains("agr"))
                                {
