                                        }
                                    }
                                    else
                                    {
                                        if (nganhang.ThanhTien2 > 0)
                                        {
                                            nganhang.TKCo = "1311";
                                        }
                                    }
                                    //
                                    //Tìm tk 3311
                                    var getTk331 = existingTbHeThongTK.AsEnumerable().Where(m => m.Field<string>("SoHieu").StartsWith("331")).ToList();
                                    if (getTk331.Count == 1)
                                    {
                                        if (nganhang.ThanhTien > 0)
                                        {
                                            nganhang.TKNo = "331";
                                        }
                                    }
                                    else
                                    {
                                        if (nganhang.ThanhTien > 0)
                                        {
                                            nganhang.TKNo = "3311";
                                        }
                                    }


