                            }

                            //Tìm mã khách hàng thông qua số hoá đơn
                            if (findMakh == false)
                            {
                                string number = Helpers.ExtractNumber(nganhang.Diengiai);
                                bool isFindSohd = false;
                                if (number != "Không tìm thấy số" && number != "")
                                {
                                    //Tìm bỏ số 0 trước
                                    int number2 = int.Parse(number);

                                    int countwhile = 3;
                                    string makh = "";
                                    nganhang.SoHD = number2.ToString();
                                    double TT = 0;
                                    //Kiem tra hoa don truoc


                                    var getlist = existingTbChungtu != null ? existingTbChungtu.AsEnumerable().Where(m => m.Field<string>("SoHieu").EndsWith(number2.ToString())).ToList() : null;
                                    if (getlist != null)
                                    {
                                        foreach (DataRow item in getlist)
                                        {
                                            var getlishd = existingTbHoadon.AsEnumerable().Where(m => m.Field<string>("SoHD").EndsWith(number2.ToString())).FirstOrDefault();
                                            if (getlishd != null)
                                            {
                                                int idkhachhang = int.Parse(getlishd["MaKhachHang"].ToString());
                                                var findcus = tbKhachhang.AsEnumerable().Where(m => m["MaSo"].ToString() == idkhachhang.ToString()).FirstOrDefault();
                                                if (findcus != null)
