                                                    makh = findcus["SoHieu"].ToString();
                                                }
                                            }


                                            if (makh != "0")
                                                TT += double.Parse(item["SoPS"].ToString());
                                        }
                                        var findct2 = getlist.Where(m => m["MaKH"].ToString() != "0").FirstOrDefault();
                                        while (findct2 == null && countwhile > 0)
                                        {
                                            string snumber2 = "0" + number2.ToString();
                                            findct2 = existingTbChungtu.AsEnumerable().Where(m => m.Field<string>("SoHieu").Contains(snumber2)).FirstOrDefault();
                                            countwhile -= 1;
                                        }
                                        var findct = getlist.Where(m => m["MaKH"].ToString() != "0").FirstOrDefault();
                                        // makh = findct["MaKH"].ToString();
                                    }



                                    if (countwhile > 0)
                                    {

                                        //Kiểm tra tổng tiền trước
                                        if ((nganhang.ThanhTien > 0 && TT == nganhang.ThanhTien) || (nganhang.ThanhTien2 > 0 && TT == nganhang.ThanhTien2))
                                        {

                                            var kh = tbKhachhang.AsEnumerable().Where(m => m.Field<string>("SoHieu").ToString().Contains(makh)).FirstOrDefault();
                                            string tenkh = Helpers.ConvertVniToUnicode(kh["Ten"].ToString());
                                            string getMaSo = Helpers.ConvertVniToUnicode(kh["Ten"].ToString());
                                            //nganhang.MaKH = tenkh + " | " + getMaSo;
                                            nganhang.MaKH = getMaSo;
                                            var getTk131 = existingTbHeThongTK.AsEnumerable().Where(m => m.Field<string>("SoHieu").StartsWith("131")).ToList();
                                            if (getTk131.Count == 1)
                                            {
