                        }

                        lstNganhan.Add(nganhang);
                       
                    }
                  
                }
                var bindingList = new BindingList<Nganhang>(lstNganhan);
                gridControl7.DataSource = bindingList;
                gridView11.Columns["Stt"].SortOrder = ColumnSortOrder.Ascending;


            }
