        private void btnThemdong_Click(object sender, EventArgs e)
        {
            //Lấy stt của dòng hiện tại
            if (typeBank == 1)
            {
                int currentSTT = int.Parse(gridCurrent.GetRowCellValue(currentIndex, "Stt").ToString());
                var currentitem = lstNganhan.Where(m => m.Stt == currentSTT).FirstOrDefault();
                Nganhang nh = new Nganhang();
                nh.Maso = currentitem.Maso;
                nh.Stt = currentSTT + 1; // STT của phần tử mới
                nh.NgayGD = currentitem.NgayGD;
                nh.Checked = true;
                nh.TKCo = currentitem.TKCo;
                nh.TKNo = currentitem.TKNo;
                // Tăng STT cho các phần tử còn lại
                foreach (var item in lstNganhan.Where(m => m.Stt > (currentSTT)).ToList())
                {
                    item.Stt++;
                }
                lstNganhan.Add(nh);
                gridControl3.DataSource = lstNganhan.OrderBy(m => m.Stt).ToList();
                gridControl3.RefreshDataSource();
            }
        }
