            foreach (var item in lstFileImporthd)
            {
                //Cập nhật lại nội dung
                item.Noidung = "Nhập kho ";
                foreach (var it in item.fileImportDetails)
                {
                    var index = item.fileImportDetails.IndexOf(it);
                    if (index < item.fileImportDetails.Count() - 1)
                        item.Noidung += it.Ten + ", ";
                    else
                        item.Noidung += it.Ten;
                }
                item.TongTien = item.fileImportDetails.Sum(m => m.TTien);
                var check = kq2.AsEnumerable().ToList().Where(m => m.Field<double>("TongTien") == item.TongTien && m.Field<string>("Ten") == Helpers.ConvertUnicodeToVni(item.Ten)).FirstOrDefault();
                if (check != null)
                {
                    XtraMessageBox.Show("Hóa đơn " + item.Ten + " đã tồn tại trong hệ thống.", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Warning);
