                }
                //Cập nhật lại tổng tiền
                item.TongTien = item.fileImportDetails.Sum(m => m.TTien);
                string query = @"INSERT INTO tbImport (SHDon, KHHDon, NLap, Ten, Noidung,TKNo,TKCo, TkThue, Mst, Status, Ngaytao, TongTien,Type,TPhi,TgTCThue,TgTThue,TVat3,TVat2,TVat,Vat3,Vat2)
