                    // Khởi tạo đối tượng FileImport
                    fileImport = new FileImport(true,path, shDon, khhDon, nLap, nLap, ten, noidung, tkNo, tkCo, tkThue, mst, tongTien, vat, 3, soHieuTP, hasChild, tpHi, tgTCThue, tgTThue, true, invoiceType, Tvat, vat2, Tvat2, vat3, Tvat3, Macdinhstatus,khautruthue);
                    fileImport.ID = int.Parse(item["ID"].ToString());
                    queryCheckVatTu = @"SELECT * FROM tbimportdetail WHERE   ParentId= ?";
                    parameterss = new OleDbParameter[]
                    {
                            new OleDbParameter("?",int.Parse(item["ID"].ToString()))
                    };
                    var kq2 = ExecuteQuery(queryCheckVatTu, parameterss);
                    foreach (DataRow it in kq2.Rows)
                    {
                        int vatdt = 0;
                        if (!string.IsNullOrEmpty(it["VAT"].ToString()))
                        {
                            vatdt = int.Parse(it["VAT"].ToString());
                        }
                        FileImportDetail fileImportDetail = new FileImportDetail(int.Parse(it["ID"].ToString()), Helpers.ConvertVniToUnicode(it["Ten"].ToString()), int.Parse(it["ParentId"].ToString()), (string)it["SoHieu"], double.Parse(it["SoLuong"].ToString()), double.Parse(it["DonGia"].ToString()), "", "", it["TKNo"].ToString(), it["TKCo"].ToString(), double.Parse(it["TTien"].ToString()), it["Percent"].ToString(), int.Parse(it["Tchat"].ToString()), vatdt);
                        fileImport.fileImportDetails.Add(fileImportDetail);
                    }
                    lstImportVao.Add(fileImport);
                }
                catch (Exception ex)
                {
                    // Xử lý lỗi ở đây, ví dụ như ghi log hoặc thông báo cho người dùng
                    XtraMessageBox.Show("Hóa đơn " + item["SHDon"].ToString() + " không thể đọc dữ liệu. Vui lòng kiểm tra lại.");
                    continue;
                }
            }
            if (lstImportVao.Count == 0)
                XtraMessageBox.Show("Đã hết hoá đơn để import");
            bindingSource.DataSource = lstImportVao;
            gridControl1.DataSource = bindingSource;
            gridControl1.RefreshDataSource();
            gridView1.OptionsDetail.EnableMasterViewMode = true;
        }

