        public void SetIsImport()
        {
            BindingList<FileImport> bdList = chkDauvao.Checked ? lstImportVao : lstImportRa;
            if (bdList.Count == 0) return;

            using (SqlConnection conn = new SqlConnection(connectionStringSQL))
            {
                conn.Open();
                using (SqlTransaction tran = conn.BeginTransaction())
                {
                    try
                    {
                        // 1️⃣ Reset IsImport = 0
                        using (SqlCommand cmd = new SqlCommand(
                            "UPDATE tbimport SET IsImport = 0", conn, tran))
                        {
                            cmd.ExecuteNonQuery();
                        }

                        // 2️⃣ Lấy danh sách ID được check
                        var checkedIds = bdList
                            .Where(x => x.Checked)
                            .Select(x => x.ID)
                            .ToList();

                        if (checkedIds.Count > 0)
                        {
                            // SQL Server có thể dùng parameter với IN (dùng string.Join)
                            string idList = string.Join(",", checkedIds);

                            string query = $"UPDATE tbimport SET IsImport = 1 WHERE ID IN ({idList})";
                            using (SqlCommand cmd = new SqlCommand(query, conn, tran))
                            {
                                cmd.ExecuteNonQuery();
                            }
                        }

                        tran.Commit();
                    }
                    catch
                    {
                        tran.Rollback();
                        throw;
                    }
                }
            }
        }
        public void SetIsImportKhautru()
        {
