        public void UpdateStatusImportVao_Safe(BindingList<FileImport> lstImportVao)
        {
            if (lstImportVao.Count == 0) return;

            var allIds = lstImportVao.Select(x => x.ID).ToList();
            var checkedIds = lstImportVao.Where(x => x.Checked).Select(x => x.ID).ToList();

            string allIdList = string.Join(",", allIds);
            string checkedIdList = checkedIds.Count > 0
                ? string.Join(",", checkedIds)
                : "NULL"; // tránh lỗi SQL

            using (SqlConnection conn = new SqlConnection(connectionStringSQL))
            {
                conn.Open();
                using (SqlTransaction tran = conn.BeginTransaction())
                {
                    try
                    {
                        // 1️⃣ Set Status = 3 cho các ID trong danh sách
                        string sqlReset = $@"
                    UPDATE tbimport 
                    SET Status = 3 
                    WHERE ID IN ({allIdList})";

                        using (SqlCommand cmd = new SqlCommand(sqlReset, conn, tran))
                        {
                            cmd.ExecuteNonQuery();
                        }

                        // 2️⃣ Set Status = 0 cho các ID được check
                        if (checkedIds.Count > 0)
                        {
                            string sqlChecked = $@"
                        UPDATE tbimport 
                        SET Status = 0 
                        WHERE ID IN ({checkedIdList})";

                            using (SqlCommand cmd = new SqlCommand(sqlChecked, conn, tran))
                            {
                                cmd.ExecuteNonQuery();
                            }
                        }

                        tran.Commit();
                    }
                    catch
                    {
                        tran.Rollback();
                        throw;
                    }
                }
            }
        }

