                                index++;

                                if (index % 10 == 0)
                                {
                                    progressPanel1.Caption = $"Đang xử lý file thứ {index} / {total}";
                                    Application.DoEvents();
                                }

                                if (!item.Checked) continue;

                                // ================= XỬ LÝ TK 15 / 154 =================
                                if (item.TKNo.Contains("15"))
                                {
                                    var items154 = item.fileImportDetails
                                        .Where(x => x.TKNo.Contains("154") && !x.TKNo.Contains("|"))
                                        .ToList();

                                    if (items154.Count > 1)
                                    {
                                        var first154 = items154.First();

                                        first154.Soluong = items154.Sum(x => x.Soluong);
                                        first154.TTien = items154.Sum(x => x.TTien);
                                        first154.Dongia = Math.Round(first154.TTien / first154.Soluong);

                                        cmdUpdateDetail154.Parameters["@SoLuong"].Value = first154.Soluong;
                                        cmdUpdateDetail154.Parameters["@Dongia"].Value = first154.Dongia;
                                        cmdUpdateDetail154.Parameters["@TTien"].Value = first154.TTien;
                                        cmdUpdateDetail154.Parameters["@ID"].Value = first154.ID;
                                        cmdUpdateDetail154.ExecuteNonQuery();

                                        var deleteIds = items154.Skip(1).Select(x => x.ID).ToList();

                                        if (deleteIds.Count > 0)
                                        {
                                            cmdDeleteDetail.CommandText =
                                                $"DELETE FROM tbimportdetail WHERE ID IN ({string.Join(",", deleteIds)})";
                                            cmdDeleteDetail.ExecuteNonQuery();

                                            item.fileImportDetails.RemoveAll(x => deleteIds.Contains(x.ID));
                                        }
                                    }

                                    if (item.TKNo.Contains("|"))
                                    {
                                        var split = item.TKNo.Split('|');
                                        item.TKNo = split[0];
                                        item.SoHieuTP = split[1];

                                        cmdUpdateImport.Parameters["@TKNo"].Value = item.TKNo;
                                        cmdUpdateImport.Parameters["@SohieuTP"].Value = item.SoHieuTP;
                                        cmdUpdateImport.Parameters["@ID"].Value = item.ID;
                                        cmdUpdateImport.ExecuteNonQuery();
                                    }
                                }

                                // ================= UPDATE STATUS =================
                                cmdUpdateStatus.Parameters["@ID"].Value = item.ID;
                                cmdUpdateStatus.ExecuteNonQuery();

                                // ================= DETAIL =================
                                foreach (var it in item.fileImportDetails)
                                {
                                    if (it.TKNo.Contains("|"))
                                    {
                                        var split = it.TKNo.Split('|');
                                        it.TKNo = split[0];
                                        it.MaCT = split[1];

                                        cmdUpdateDetailTK.Parameters["@TKNo"].Value = it.TKNo;
                                        cmdUpdateDetailTK.Parameters["@MaCT"].Value = it.MaCT;
                                        cmdUpdateDetailTK.Parameters["@ID"].Value = it.ID;
                                        cmdUpdateDetailTK.ExecuteNonQuery();
                                    }

                                    if (item.TKNo.Contains("15") || (item.TKNo.Contains("642") && item.isHaschild))
                                    {
                                        if (string.IsNullOrEmpty(it.SoHieu))
                                        {
                                            XtraMessageBox.Show($"Hóa đơn {item.SHDon}, Có sản phẩm chưa nhập Mã!");
                                            throw new Exception("Thiếu mã hàng");
                                        }

                                        if (!it.TKNo.Contains("154") && !it.TKNo.Contains("642"))
                                        {
                                            if (it.Ten == "Cöôùc dòch vuï vieãn thoâng traû sau (Dòch vuï chòu thueá)")
                                            {
                                                int a = 10;
                                            }
                                            InsertHangHoa2(
                                                Helpers.ConvertUnicodeToVni(it.DVT),
                                                it.SoHieu,
                                                Helpers.ConvertUnicodeToVni(it.Ten),
                                                it.TKNo, item.SHDon);
                                        }
                                    }
                                }
                            }

                            tran.Commit();
                        }
                        catch
                        {
                            tran.Rollback();
                            throw;
                        }
                    }
                }
            }
            else
            {
              
                UpdateStatusImportVao_Safe(lstImportRa); 

                string querys = "SELECT * FROM License";
                var getLc = ExecuteQuerySQL(querys, null);

                // int findmpl = ListPhanloaiVattu.AsEnumerable().Where(m => m.Field<string>("SoHieu") == "TP").FirstOrDefault().Field<int>("MaSo");
                using (SqlConnection conn = new SqlConnection(connectionStringSQL))
                {
                    conn.Open();
                    using (SqlTransaction tran = conn.BeginTransaction())
                    {
                        try
                        {
                            // ================= PREPARE COMMAND =================

                            SqlCommand cmdUpdateImport = new SqlCommand(
                                "UPDATE tbimport SET TKCo = @TKCo, SohieuTP = @SohieuTP WHERE ID = @ID",
                                conn, tran);
                            cmdUpdateImport.Parameters.Add("@TKCo", SqlDbType.NVarChar);
                            cmdUpdateImport.Parameters.Add("@SohieuTP", SqlDbType.NVarChar);
                            cmdUpdateImport.Parameters.Add("@ID", SqlDbType.Int);

                            SqlCommand cmdDeleteDetailByParent = new SqlCommand(
                                "DELETE FROM tbimportdetail WHERE ParentId = @ParentId",
                                conn, tran);
                            cmdDeleteDetailByParent.Parameters.Add("@ParentId", SqlDbType.Int);

                            SqlCommand cmdUpdateDetail = new SqlCommand(
                                "UPDATE tbimportdetail SET TKCo = @TKCo, MaCT = @MaCT WHERE ID = @ID",
                                conn, tran);
                            cmdUpdateDetail.Parameters.Add("@TKCo", SqlDbType.NVarChar);
                            cmdUpdateDetail.Parameters.Add("@MaCT", SqlDbType.NVarChar);
                            cmdUpdateDetail.Parameters.Add("@ID", SqlDbType.Int);

                            SqlCommand cmdUpdateHasChild = new SqlCommand(
                                "UPDATE tbimport SET IsHaschild = @IsHaschild WHERE ID = @ID",
                                conn, tran);
                            cmdUpdateHasChild.Parameters.Add("@IsHaschild", SqlDbType.NVarChar);
                            cmdUpdateHasChild.Parameters.Add("@ID", SqlDbType.Int);

                            // ================= PROCESS =================

                            int total = lstImportRa.Count;
                            int index = 0;

                            foreach (var item in lstImportRa)
                            {
                                if (item.fileImportDetails.Any(m => string.IsNullOrEmpty(m.DVT) && m.Dongia != 0 && m.Soluong != 0) && item.Checked)
                                {
                                    XtraMessageBox.Show("Hoá đơn " + item.SHDon + " có chi tiết chưa có đơn vị tính. Vui lòng kiểm tra lại!");
                                    DevExpress.XtraGrid.Views.Grid.GridView view = gridControl2.MainView as DevExpress.XtraGrid.Views.Grid.GridView;
                                    for (int i = 0; i < view.RowCount; i++)
                                    {
                                        if (view.GetRowCellValue(i, "ID").ToString().ToLower() == item.ID.ToString().ToLower())
                                        {
                                            this.BeginInvoke((MethodInvoker)delegate
                                            {
                                                if (gridView3.RowCount > i)
                                                {
                                                    gridView3.FocusedRowHandle = i;
                                                    gridView3.SelectRow(i);
                                                    gridView3.ExpandMasterRow(i);
                                                    gridView3.MakeRowVisible(i);
                                                }
                                            });
                                            return;
                                        }
                                    }
                                    return;
                                }
                                index++;

                                if (!item.Checked) continue;

                                if (index % 10 == 0)
                                {
                                    progressPanel2.Caption = $"Đang xử lý file thứ {index} / {total}";
                                    Application.DoEvents();
                                }

                                // ================= KIỂM TRA TÀI KHOẢN CON =================
                                if (Kiemtrataikhoancon(item.TKNo))
                                {
                                    XtraMessageBox.Show($"Tài khoản {item.TKNo} có chi tiết");
                                    throw new Exception("TK có tài khoản con");
                                }

                                // ================= SPLIT TKCo | SohieuTP =================
                                if (item.TKCo.Contains("|"))
                                {
                                    var split = item.TKCo.Split('|');
                                    item.TKCo = split[0];
                                    item.SoHieuTP = split[1];

                                    cmdUpdateImport.Parameters["@TKCo"].Value = item.TKCo;
                                    cmdUpdateImport.Parameters["@SohieuTP"].Value = item.SoHieuTP;
                                    cmdUpdateImport.Parameters["@ID"].Value = item.ID;
                                    cmdUpdateImport.ExecuteNonQuery();

                                    cmdDeleteDetailByParent.Parameters["@ParentId"].Value = item.ID;
                                    cmdDeleteDetailByParent.ExecuteNonQuery();

                                    item.fileImportDetails.Clear();
                                }

                                // ================= DELETE DETAIL KHÔNG CẦN =================
                                if (!item.isHaschild &&
                                    !item.fileImportDetails.Any(x => x.TKCo.Contains("5111")))
                                {
                                    cmdDeleteDetailByParent.Parameters["@ParentId"].Value = item.ID;
                                    cmdDeleteDetailByParent.ExecuteNonQuery();
                                }

                                // Xử lý IsHaschild
                                if (item.TKNo.Contains("5113"))
                                {
                                    var checkIsHaschild = item.fileImportDetails.Any(m => m.TKNo != item.TKNo);
                                    if (checkIsHaschild == false)
                                    {
                                        cmdUpdateHasChild.Parameters["@IsHaschild"].Value = "0";
                                        cmdUpdateHasChild.Parameters["@ID"].Value = item.ID;
                                        cmdUpdateHasChild.ExecuteNonQuery();
                                    }
                                }

                                // ================= DETAIL =================
                                foreach (var it in item.fileImportDetails)
                                {
                                    // Split TKCo | MaCT
                                    if (it.TKCo.Contains("|"))
                                    {
                                        var split = it.TKCo.Split('|');
                                        it.TKCo = split[0];
                                        it.MaCT = split[1];

                                        cmdUpdateDetail.Parameters["@TKCo"].Value = it.TKCo;
                                        cmdUpdateDetail.Parameters["@MaCT"].Value = it.MaCT;
                                        cmdUpdateDetail.Parameters["@ID"].Value = it.ID;
                                        cmdUpdateDetail.ExecuteNonQuery();
                                    }

                                    // Insert hàng hóa
                                    if (!it.TKCo.Contains("5113"))
                                    {
                                        if (it.Ten == "Cöôùc dòch vuï vieãn thoâng traû sau (Dòch vuï chòu thueá)")
                                        {
                                            int a = 10;
                                        }
                                        InsertHangHoa2(
                                            Helpers.ConvertUnicodeToVni(it.DVT),
                                            it.SoHieu,
                                            Helpers.ConvertUnicodeToVni(it.Ten),
                                            it.TKCo, item.SHDon);
                                    }
                                }
                            }

                            tran.Commit();
                        }
                        catch
                        {
                            tran.Rollback();
                            throw;
                        }
                    }
                }

            }
            //Nếu isHAschild


            isClick = true;
           
            this.Close();
        } 
