        List<Nhapkhotp> lstNhapkhotp = new List<Nhapkhotp>();
        List<Nhapkhotp> lstFindnk = new List<Nhapkhotp>();
        private List<Nhapkhotp> findDataNK(DateTime fromdate, DateTime todate)
        {
            lstFindnk = new List<Nhapkhotp>();
            // DataTable getTonkho=
            string query = "SELECT * FROM " +
                "((TonKho " +
                "INNER JOIN Vattu ON TonKho.MaVatTu = Vattu.MaSo) " +
                "INNER JOIN PhanLoaiVattu ON Vattu.MaPhanLoai = PhanLoaiVattu.MaSo) " +
                "WHERE PhanLoaiVattu.MaTK = 38 " +
                "ORDER BY Vattu.TenVattu ASC";
            var parameters = new OleDbParameter[]
                     {
            new OleDbParameter("?", "3"),
                     };
            var kq = ExecuteQuery(query, null);
            foreach (DataRow dr in kq.Rows)
            {
                Nhapkhotp nhapkhotp = new Nhapkhotp();
                nhapkhotp.TenThanhPham = Helpers.ConvertVniToUnicode(dr.Field<string>("TenVattu")) + "|" + dr.Field<string>("Vattu.SoHieu");
                if (nhapkhotp.TenThanhPham.Contains("Ba ba rang muối "))
                {
                    int a = 10;
                }
                //Tính tồn đầu kỳ
                //Lấy tháng trước đó
                int monthDauky = ngaylapNhapTP.DateTime.Month - 1;
                var getSLDauky = dr.Field<double>("Luong_" + monthDauky);
                var loctheongay = existingTbChungtu.AsEnumerable().Where(m => m.Field<int>("MaVattu") == dr.Field<int>("Vattu.MaSo") && DateTime.Parse(m["NgayGS"].ToString()) >= dateEdit1.DateTime && DateTime.Parse(m["NgayGS"].ToString()) <= dateEdit2.DateTime && !m["SoHieu"].ToString().Contains("GV")).ToList();
                //Tính số lượng hoá đơn từ đầu tháng đến hiện tại
                //Tổng nhập
                double totalNo = 0;
                double totalCo = 0;
                if (loctheongay.Count > 0)
                {
                    totalNo = loctheongay.AsEnumerable().Sum(m => m.Field<double>("SoPS2No"));
                    totalCo = loctheongay.AsEnumerable().Sum(m => m.Field<double>("SoPS2Co"));
                    var getlast = existingTbChungtu.AsEnumerable().Where(m => m.Field<int>("MaVattu") == dr.Field<int>("Vattu.MaSo") && !m["SoHieu"].ToString().Contains("GV")).AsEnumerable().Where(m => double.Parse(m["SoPS2Co"].ToString()) > 0).AsEnumerable().LastOrDefault();
                    if (getlast != null)
                    {
                        var sops = getlast.Field<double>("SoPS");
                        var sl = getlast.Field<double>("SoPS2Co");
                        nhapkhotp.GiaBan = sops / sl;
                    }
                }
                else
                {
                    //Lấy giá bán theo hoá đơn cuối
                    var regain = existingTbChungtu.AsEnumerable().Where(m => m.Field<int>("MaVattu") == dr.Field<int>("Vattu.MaSo") && !m["SoHieu"].ToString().Contains("GV")).Where(m => double.Parse(m["SoPS2Co"].ToString()) > 0).ToList().LastOrDefault();
                    if (regain != null)
                    {
                        var sops = double.Parse(regain["SoPS"].ToString());
                        var sl = double.Parse(regain["SoPS2Co"].ToString());
                        nhapkhotp.GiaBan = sops / sl;
                    }
                }
                var soluogton = Math.Round(getSLDauky + totalNo - totalCo, 2);
                //if (soluogton < 0)
                //    soluogton = soluogton * (-1);
                nhapkhotp.SoLuongTon = soluogton;

                nhapkhotp.Percent = 80;
                nhapkhotp.DonGia = Math.Round(nhapkhotp.GiaBan * 80 / 100);
                nhapkhotp.Checked = true;
                nhapkhotp.ps1 = 70;
                nhapkhotp.ps2 = 10;
                lstFindnk.Add(nhapkhotp);

            }

            //Bước sàng lọc
            if (comboBoxEdit3.SelectedIndex == 1)
            {
                lstNhapkhotp = lstNhapkhotp.Where(m => m.SoLuongTon < 0).ToList();
            }
            if (comboBoxEdit3.SelectedIndex == 2)
            {
                lstNhapkhotp = lstNhapkhotp.Where(m => m.SoLuongTon >= 0).ToList();
            }

            //Lấy nguyên liệu đã lưu trước đó cho thành phẩm
            foreach (var it in lstFindnk)
            {
                string getsohieu = it.TenThanhPham.Split('|')[1];
                if (!string.IsNullOrEmpty(getsohieu))
                {
                    var getdsNLTP = existtbNguyenLieuThanhPham.AsEnumerable().Where(m => m.Field<double>("TiLe") > 0).Where(m => m.Field<string>("TPSoHieu") == getsohieu).ToList();
                    if (getdsNLTP != null && getdsNLTP.Count > 0)
                    {
                        foreach (var item in getdsNLTP)
                        {
                            for (int i = 1; i <= 5; i++)
                            {
                                string nlProperty = $"nl{i}";
                                string psProperty = $"ps{i}";
                                string slProperty = $"sl{i}";
                                string dgProperty = $"dg{i}";

                                // Kiểm tra xem thuộc tính nl[i] có trống hay không
                                if (string.IsNullOrEmpty(it.GetType().GetProperty(nlProperty)?.GetValue(it)?.ToString()))
                                {
                                    // Gán giá trị
                                    it.GetType().GetProperty(nlProperty).SetValue(it, item["SoHieuNguyenLieu"].ToString());
                                    it.GetType().GetProperty(psProperty).SetValue(it, item.Field<double>("TiLe"));

                                    var getvt = lstvt.FirstOrDefault(m => m.SoHieu == it.GetType().GetProperty(nlProperty).GetValue(it)?.ToString());
                                    var findlastCt = existingTbChungtu.AsEnumerable()
                                        .Where(m => m.Field<int>("MaVattu") == getvt.MaSo && m["SoPS2No"].ToString() != "0")
                                        .LastOrDefault();

                                    if (findlastCt != null)
                                    {
                                        double getSoPS = double.Parse(findlastCt["SoPS"].ToString());
                                        double SoPSNo = double.Parse(findlastCt["SoPS2No"].ToString());
                                        double DonGia = getSoPS / SoPSNo;
                                        double tt = it.DonGia * (it.SoLuongTon < 0 ? it.SoLuongTon * -1 : it.SoLuongTon);
                                        double percent2 = (double)it.GetType().GetProperty(psProperty).GetValue(it);
                                        var tt1 = (tt * percent2 / 100);
                                        double sL = Math.Round(tt1 / DonGia, 2);
                                        sL = sL < 0 ? sL * -1 : sL;

                                        // Gán giá trị cho số lượng và đơn giá
                                        it.GetType().GetProperty(slProperty).SetValue(it, sL);
                                        it.GetType().GetProperty(dgProperty).SetValue(it, DonGia);

                                    }
                                    break; // Thoát khỏi vòng lặp sau khi đã gán giá trị
                                }
                            }
                            var index = getdsNLTP.IndexOf(item);
                            if (index > 4)
                            {
                                Nguyenlieu nguyenlieu = new Nguyenlieu();
                                nguyenlieu.ParentId = it.ID;
                                nguyenlieu.SoHieu = item["SoHieuNguyenLieu"].ToString();
                                nguyenlieu.TiLe = item.Field<double>("TiLe");
                                nguyenlieu.Ten = lstvt.Where(m => m.SoHieu == nguyenlieu.SoHieu).FirstOrDefault().TenVattu;
                                it.Nguyenlieus.Add(nguyenlieu);
                            }
                        }
                    }
                }
            }
            return lstFindnk;
        }
