        private void gridView6_CellValueChanged(object sender, DevExpress.XtraGrid.Views.Base.CellValueChangedEventArgs e)
        {
            gridView = sender as DevExpress.XtraGrid.Views.Grid.GridView;
            string columnName = e.Column.FieldName; // Tên cột
            int rowHandle = e.RowHandle;
            var changedObject = gridView6.GetRow(rowHandle);

            if (isEditgia) return;
            try
            {
                isEditgia = true;  // THIẾU DÒNG NÀY!
                if (columnName.Contains("Percent"))
                {
                    var myObject = changedObject as Nhapkhotp;
                    //Lấy cột Giá bán
                    var GiaBan = double.Parse(gridView.GetRowCellValue(rowHandle, "GiaBan").ToString());
                    var Percent = double.Parse(gridView.GetRowCellValue(rowHandle, "Percent").ToString());
                    gridView.SetRowCellValue(rowHandle, "DonGia", Math.Round(GiaBan * Percent / 100));
                    //Cập nhật data
                    string query = @"UPDATE Vattu SET PTGB=? where SoHieu=?";

                    var parameters = new OleDbParameter[]
                    {
                        new OleDbParameter("?",Percent.ToString()),
                         new OleDbParameter("?",myObject.TenThanhPham.Split('|')[1]),
                    }  ;
                    int rowsAffected = ExecuteQueryResult(query, parameters);
                    //Cập nhật lại cho lstVT
                    var findvt = lstvt.Where(m => m.SoHieu == myObject.TenThanhPham.Split('|')[1]).FirstOrDefault();
                    if (findvt != null)
                    {
                        findvt.PTGB = Percent.ToString();

                    }
                }
                else
                {
                    if (columnName.Contains("DonGia"))
                    {
                        var myObject = changedObject as Nhapkhotp;
                        //Lấy cột Giá bán
                        var GiaBan = double.Parse(gridView.GetRowCellValue(rowHandle, "GiaBan").ToString());
                        var DonGia = double.Parse(gridView.GetRowCellValue(rowHandle, "DonGia").ToString());
                        gridView.SetRowCellValue(rowHandle, "Percent", Math.Round(DonGia * 100 / GiaBan));
                    }
                }
            }
            finally
            {
                isEditgia = false;
            }



            if (changedObject != null)
            {
                // Thực hiện các thao tác với đối tượng đã lấy
                // Ví dụ: chuyển đổi đối tượng về kiểu dữ liệu cụ thể
                var myObject = changedObject as Nhapkhotp;

                if (myObject != null)
                {
                        if (columnName == "SoLuongTon" || columnName.Contains("ps") || columnName.Contains("Percent") || columnName.Contains("DonGia"))
                    {
                        myObject.SoLuongTon = Math.Abs(myObject.SoLuongTon);
                        var newtongtien = (myObject.DonGia * myObject.SoLuongTon);
                        myObject.sl1 = Math.Round((newtongtien * myObject.ps1 / 100) / myObject.dg1,1);
                        myObject.sl2 = Math.Round((newtongtien * myObject.ps2 / 100) / myObject.dg2, 1);
                        myObject.sl3 = Math.Round((newtongtien * myObject.ps3 / 100) / myObject.dg3, 1);
                        myObject.sl4 = Math.Round((newtongtien * myObject.ps4 / 100) / myObject.dg4, 1);
                        myObject.sl5 = Math.Round((newtongtien * myObject.ps5 / 100) / myObject.dg5, 1);
                    }
                    if (columnName == "ps1")
                    {

                    }
                }
                gridView6.RefreshData();
            }
            var getsohieu = gridView.GetRowCellValue(rowHandle, "TenThanhPham").ToString().Split('|')[1];

          
            if (columnName.Contains("nl"))
            {
                //Kiểm tra xem nguyên liệu thành phẩm đã có chưa
                var getcurruent = gridView.GetRowCellValue(rowHandle, columnName).ToString();
                var checkdata = _lookupBySoHieu.TryGetValue(getcurruent, out var vatTu);
                 
                if (checkdata)
                {
                    CapnhatNguyenlieuthanhphams();
                    //var getvattu = lstvt.Where(m => m.SoHieu == getcurruent).FirstOrDefault();
                    if (!existtbNguyenLieuThanhPham.AsEnumerable().Any(m => m.Field<string>("SoHieuNguyenLieu")==getsohieu) || !existtbNguyenLieuThanhPham.AsEnumerable().Any(m => m.Field<string>("SoHieuNguyenLieu") == getcurruent))
                    {
                        double tile = 0;
                        double dongia = 0;
                        int stt = 0;
                        if(columnName=="nl1")
                        {
                            tile = double.Parse(gridView.GetRowCellValue(rowHandle, "ps1").ToString());
                            dongia= double.Parse(gridView.GetRowCellValue(rowHandle, "dg1").ToString());
                            stt = 1;
                        }
                        if (columnName == "nl2")
                        {
                            tile = double.Parse(gridView.GetRowCellValue(rowHandle, "ps2").ToString());
                            dongia = double.Parse(gridView.GetRowCellValue(rowHandle, "dg2").ToString());
                            stt = 2;
                        }
                        if (columnName == "nl3")
                        {
                            tile = double.Parse(gridView.GetRowCellValue(rowHandle, "ps3").ToString());
                            dongia = double.Parse(gridView.GetRowCellValue(rowHandle, "dg3").ToString());
                            stt = 3;
                        }
                        if (columnName == "nl4")
                        {
                            tile = double.Parse(gridView.GetRowCellValue(rowHandle, "ps4").ToString());
                            dongia = double.Parse(gridView.GetRowCellValue(rowHandle, "dg4").ToString());
                            stt = 4;
                        }
                        if (columnName == "nl5")
                        {
                            tile = double.Parse(gridView.GetRowCellValue(rowHandle, "ps5").ToString());
                            dongia = double.Parse(gridView.GetRowCellValue(rowHandle, "dg5").ToString());
                            stt = 5;
                        }
                       
                        var myObject = changedObject as Nhapkhotp;
                        if (dongia != 0)
                        {
                            string queryCheckVatTu = @"SELECT * FROM tbNguyenLieuThanhPham WHERE TPSoHieu=?  and  stt=? ";
                            OleDbParameter[] parameterss = null;
                            parameterss = new OleDbParameter[]
                                         {
                                   new OleDbParameter("?",getsohieu), 
                                      new OleDbParameter("?",stt),
                                         }; 
                            var kq = ExecuteQuery(queryCheckVatTu, parameterss);

                            if (kq.Rows.Count == 0)
                            {
                                var qr = @"INSERT INTO tbNguyenLieuThanhPham (TPSoHieu, IDNguyenLieu, SoHieuNguyenLieu, TiLe,stt) VALUES (?, ?, ?, ?,?)";
                                var parameter = new OleDbParameter[]
                                {
                                new OleDbParameter("?", getsohieu),
                                new OleDbParameter("?", vatTu!=null?vatTu.MaSo.ToString():"0"),
                                new OleDbParameter("?", vatTu.SoHieu),
                                new OleDbParameter("?", tile),
                                new OleDbParameter("?", stt),
                                };

                                var rowsAffecteds = ExecuteQueryResult(qr, parameter);
                            }
                            else
                            {
                                var updateQr = @"UPDATE tbNguyenLieuThanhPham 
                                  SET TiLe = ?, SoHieuNguyenLieu = ? 
                                 WHERE TPSoHieu = ? AND stt = ?";
                                var updateParameters = new OleDbParameter[]
                                {
        new OleDbParameter("?", tile), // Cập nhật giá trị TiLe
        new OleDbParameter("?", getcurruent), // Cập nhật SoHieuNguyenLieu
           new OleDbParameter("?", getsohieu), // Điều kiện WHERE 
        new OleDbParameter("?", stt), // Điều kiện WHERE 

                                };

                                var updateRowsAffected = ExecuteQueryResult(updateQr, updateParameters);
                            }

                           
                            
                        }
                     
                    }
                }
            }
            for (int i = 1; i <= 5; i++)
            {
                string psColumn = $"ps{i}"; // Tên cột: ps1, ps2, ps3, ps4, ps5
                string nlColumn = $"nl{i}"; // Tên cột tương ứng: nl1, nl2, nl3, nl4, nl5

                // Kiểm tra nếu columnName chứa psColumn (ví dụ: ps1, ps2,...)
                if (columnName.Contains(psColumn))
                {
                    // Lấy giá trị từ cột nl tương ứng
                    string currentsh = gridView.GetRowCellValue(rowHandle, nlColumn)?.ToString();

                    // Kiểm tra currentsh không null hoặc rỗng
                    if (!string.IsNullOrEmpty(currentsh))
                    {
                        // Lấy giá trị từ cột ps tương ứng và chuyển thành double
                        double tile;
                        bool isValidTile = double.TryParse(gridView.GetRowCellValue(rowHandle, psColumn)?.ToString(), out tile);

                        // Chỉ thực hiện nếu giá trị tile hợp lệ
                        if (isValidTile)
                        {
                            string query = @"UPDATE tbNguyenLieuThanhPham SET TiLe=? WHERE TPSoHieu=? AND SoHieuNguyenLieu=?";

                            var parameters = new OleDbParameter[]
                            {
                            new OleDbParameter("?", tile.ToString()),
                            new OleDbParameter("?", getsohieu),
                            new OleDbParameter("?", currentsh)
                            };

                            // Gọi hàm ExecuteQueryResult (giả định đã có)
                            int rowsAffected = ExecuteQueryResult(query, parameters);
                        }
                    }
                }
            }

            if (columnName.Contains("ps"))
            {
                //Nếu bản thân nó >100 th
               var myObject = changedObject as Nhapkhotp;
                if ((myObject.ps1 + myObject.ps2 + myObject.ps3 + myObject.ps4 + myObject.ps5) > 100)
                {
                    XtraMessageBox.Show("Tỉ lệ phần trăm không vượt ngưỡng 100%");
                }
            }

           

        }
