            //}
            //Insert lại danh sách con
            foreach (var it in lstNhapkhotp)
            {
                if (it.Checked)
                {
                    foreach (var item in it.Nguyenlieus)
                    {
                        var qr = @"INSERT INTO tbNguyenLieuThanhPham (TPSoHieu, IDNguyenLieu, SoHieuNguyenLieu, TiLe) VALUES (@TPSoHieu, @IDNguyenLieu, @SoHieuNguyenLieu, @TiLe)";
                        var parameter = new SqlParameter[]
                        {
                            new SqlParameter("@TPSoHieu", it.TenThanhPham.Split('|')[1]),
                            new SqlParameter("@IDNguyenLieu", "0"),
                            new SqlParameter("@SoHieuNguyenLieu", item.SoHieu),
                            new SqlParameter("@TiLe", item.TiLe),
                        };

                        var rowsAffecteds = ExecuteQueryResultSQL(qr, parameter);
                    }
                }
               
            }

                var query = @"INSERT INTO tbNhapkhotp (NgayLap,NgayTao,SoHieu,Ghichu,SoHieu2,Ghichu2,Status) VALUES (@NgayLap, @NgayTao, @SoHieu, @Ghichu, @SoHieu2, @Ghichu2, @Status)";
            var parameters = new SqlParameter[]
             {
            new SqlParameter("@NgayLap",ngaylapNhapTP.DateTime.Date),
             new SqlParameter("@NgayTao",DateTime.Now.Date),
             new SqlParameter("@SoHieu",txtNKSohieu.Text),
             new SqlParameter("@Ghichu",Helpers.ConvertUnicodeToVni(txtNKNoidung.Text)),
                new SqlParameter("@SoHieu2",txtNKNLSohieu.Text),
             new SqlParameter("@Ghichu2",Helpers.ConvertUnicodeToVni(txtNKNLNoidung.Text)),
             new SqlParameter("@Status","0"),
             };
            var rowsAffected = ExecuteQueryResultSQL(query, parameters);

            query = "SELECT TOP 1 * FROM tbNhapkhotp  ORDER BY ID DESC ";
              kq = ExecuteQuerySQL(query, null);
            int parentid = kq.Rows[0].Field<int>("ID");
            foreach (var item in lstNhapkhotp)
            { 
                if (item.Checked == false)
                    continue;
                if (item.SoLuongTon < 0)
                    item.SoLuongTon = item.SoLuongTon * -1;
                query = @"INSERT INTO tbNhapkhotpChitiet (SoHieu,SOLuong,DonGia,ParentID) VALUES (@SoHieu,@SOLuong,@DonGia,@ParentID)";
                parameters = new SqlParameter[]
                {
            new SqlParameter("@SoHieu",item.TenThanhPham.Split('|')[1].ToString()),
             new SqlParameter("@SOLuong",item.SoLuongTon.ToString()),
             new SqlParameter("@DonGia",item.DonGia.ToString()),
             new SqlParameter("@ParentID",parentid.ToString()),
                };
                rowsAffected = ExecuteQueryResultSQL(query, parameters);
            }
            InsertNhapkhonguyenlieu();
            this.Close();
        }

        private void gridView6_RowCellClick(object sender, RowCellClickEventArgs e)
        {
            if (e.Column.FieldName == "Checked") // Thay đổi tên cột cho phù hợp
            {
                var getAcess = (bool)gridView6.GetRowCellValue(e.RowHandle, "Checked");
                Nhapkhotp currentObject = (Nhapkhotp)gridView6.GetRow(e.RowHandle);

                if (getAcess)
                {
                    // Đảo ngược giá trị
                    gridView6.SetRowCellValue(e.RowHandle, e.Column, !getAcess);
                    if (currentObject != null)
                    {
                        currentObject.Checked = false;
                    }
                }
                else
                {
                    gridView6.SetRowCellValue(e.RowHandle, e.Column, true);
                    if (currentObject != null)
                    {
                        currentObject.Checked = true;
                    }
                }
                gridControl4.DataSource = lstNhapkhotp;
                gridControl4.RefreshDataSource();
            }
            gridView6.ShowEditor(); // Hiển thị chế độ chỉnh sửa

        }

        private void gridView6_KeyDown(object sender, KeyEventArgs e)
        {

            DevExpress.XtraGrid.Columns.GridColumn currentColumn = gridView6.FocusedColumn;
            int rowHandle = gridView6.FocusedRowHandle;
            DevExpress.XtraGrid.Views.Grid.GridView view = sender as DevExpress.XtraGrid.Views.Grid.GridView;
            if (!view.FocusedColumn.Name.Contains("nl") || e.KeyCode!=System.Windows.Forms.Keys.Enter)
            {
                return;
            }
            int focusedRow = view.FocusedRowHandle;
            Nhapkhotp dt = view.GetRow(focusedRow) as Nhapkhotp;



            if (!currentColumn.ToString().Contains("Nguyên liệu") && currentColumn.ToString() != "TÊN THÀNH PHẨM")
            {
                return;
            }
            frmHangHoa frmHangHoa = new frmHangHoa();
            frmHangHoa.frmMain = this;
            frmHangHoa.dtoVatTu = new DTO.VatTu();
            frmHangHoa.dtoVatTu.SoHieu = gridView6.GetRowCellValue(rowHandle, gridView6.FocusedColumn.FieldName)!=null? gridView6.GetRowCellValue(rowHandle,gridView6.FocusedColumn.FieldName).ToString():"";
            string queryCheckVatTu = @"SELECT * FROM PhanLoaiVattu WHERE SoHieu=? or SoHieu=?";
            OleDbParameter[] parameterss =null;

            if (currentColumn.ToString().Contains("Nguyên liệu"))
            {
                parameterss = new OleDbParameter[]
                {
        new OleDbParameter("?", "NL"),  // Tham số cho nguyên liệu
        new OleDbParameter("?", "NVL")   // Tham số cho nguyên vật liệu
                };
            }
            else if (currentColumn.ToString() == "TÊN THÀNH PHẨM")
            {
                parameterss = new OleDbParameter[]
                {
                  new OleDbParameter("?", "TP") ,   // Tham số cho tên thành phẩm,
                     new OleDbParameter("?", "TP")   // Tham số cho nguyên vật liệu
                };
            }

            var kq = ExecuteQuery(queryCheckVatTu, parameterss);
            if (kq.Rows.Count > 0)
            {
                this.currentselectId = kq.Rows[0].Field<int>("MaSo");
            }
            else
            {
                this.currentselectId = 0;
            }
                frmHangHoa.ShowDialog();
            //frmMain.hiddenValue3
            if (rowHandle >= 0 && currentColumn != null )
            {
                Capnhatsoluongnguyenlieu(currentColumn,dt);
            }
               
        }
        private void Capnhatsoluongnguyenlieu(DevExpress.XtraGrid.Columns.GridColumn currentColumn, Nhapkhotp dt)
        {

            //Tính số lượng
            var getvt = lstvt.Where(m => m.SoHieu == this.hiddenValue).FirstOrDefault();
            if (getvt != null)
            {
                //Tìm chứng từ cuối cùng
                //var findlastCt = existingTbChungtu.AsEnumerable().Where(m => m.Field<int>("MaVattu")==getvt.MaSo && m["SoPS2No"].ToString()!="0").LastOrDefault();
                var getTien = tbTonkho.AsEnumerable().Where(m => m.Field<int>("MaVatTu") == getvt.MaSo).FirstOrDefault();

                if (getTien != null)
                {
                    for (int i = 1; i <= 5; i++)
                    {
                        if (currentColumn.ToString() == $"Nguyên liệu {i}")
                        {
                            double getLuong = 0;
                            var gettien = getTien.Field<double>($"Tien_{dateEdit1.DateTime.Month}");
                            int getmonth = dateEdit1.DateTime.Month - 1;
                            if (gettien == 0)
                            {

                                while (gettien == 0 && getmonth >= 0)

                                {
                                    gettien = getTien.Field<double>($"Tien_{getmonth}");
                                    getLuong = getTien.Field<double>($"Luong_{getmonth}");
                                    getmonth -= 1;
                                }
                            }
                            else
                            {
                                getLuong = getTien.Field<double>($"Luong_{dateEdit1.DateTime.Month}");
                            }
                            if (gettien == 0 && getLuong == 0)
                            {
                                XtraMessageBox.Show("Nguyên liệu này chưa có giá bán!");
                                return;
                            }
                            var DonGia = Math.Round(gettien / getLuong);
                            double tt = double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, "DonGia").ToString()) *
                                         double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, "SoLuongTon").ToString());
                            double percent2 = double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, $"ps{i}").ToString());
                            var tt1 = (tt * percent2 / 100);
                            double sL = Math.Round(tt1 / DonGia, 2);
                            sL = sL < 0 ? sL * -1 : sL;

                            gridView6.SetRowCellValue(gridView6.FocusedRowHandle, $"sl{i}", sL);
                            gridView6.SetRowCellValue(gridView6.FocusedRowHandle, $"dg{i}", DonGia);

                            gridView6.SetRowCellValue(gridView6.FocusedRowHandle, currentColumn, this.hiddenValue);
                            break; // Kết thúc vòng lặp nếu tìm thấy trường hợp phù hợp
                        }
                    }
                    if (currentColumn.ToString() == "TÊN THÀNH PHẨM")
                    {
                        gridView6.SetRowCellValue(gridView6.FocusedRowHandle, currentColumn, this.hiddenValue3 + " | " + this.hiddenValue);
                        DateTime currentDate = DateTime.Now;
                        DateTime firstDayOfMonth = new DateTime(currentDate.Year, currentDate.Month, 1);

                        var aa = findDataNK(firstDayOfMonth, currentDate).Where(m => m.TenThanhPham.Split('|')[1] == this.hiddenValue).FirstOrDefault();
                        if (aa != null)
                        {
                            // Sao chép dữ liệu từ aa sang dt
                            dt.SoHieu = aa.SoHieu;
                            dt.ID = aa.ID;
                            dt.TenThanhPham = aa.TenThanhPham;
                            dt.GiaBan = aa.GiaBan;
                            dt.SoLuongTon = aa.SoLuongTon;
                            dt.SoLuongNhap = aa.SoLuongNhap;
                            dt.Percent = aa.Percent;
                            dt.DonGia = aa.DonGia;

                            // Sao chép các thuộc tính nl và sl
                            dt.nl1 = aa.nl1; dt.sl1 = aa.sl1; dt.ps1 = aa.ps1; dt.dg1 = aa.dg1;
                            dt.nl2 = aa.nl2; dt.sl2 = aa.sl2; dt.ps2 = aa.ps2; dt.dg2 = aa.dg2;
                            dt.nl3 = aa.nl3; dt.sl3 = aa.sl3; dt.ps3 = aa.ps3; dt.dg3 = aa.dg3;
                            dt.nl4 = aa.nl4; dt.sl4 = aa.sl4; dt.ps4 = aa.ps4; dt.dg4 = aa.dg4;
                            dt.nl5 = aa.nl5; dt.sl5 = aa.sl5; dt.ps5 = aa.ps5; dt.dg5 = aa.dg5;
                            dt.Checked = aa.Checked;

                            // Sao chép danh sách Nguyenlieus nếu cần
                            dt.Nguyenlieus = aa.Nguyenlieus;
                            lstNhapkhotp.Add(dt);
                            if (dt.sl1 == 0)
                                XtraMessageBox.Show("Nguyên liệu này chưa có giá bán!");
                        }
                        gridControl4.DataSource = lstNhapkhotp;
                        gridView6.RefreshData();
                        // CapnhatNguyenlieuthanhpham();
                    }
                }
                else
                {
                    XtraMessageBox.Show("Nguyên liệu này chưa có tồn tại trong kho!");
                    return;
                }
            }
            else
            {
                //  XtraMessageBox.Show("Không tìm thấy vật tư!");
            }
        }
        private void InsertNhapkhonguyenlieu()
        {

            foreach (var item in lstNhapkhotp.Where(m => m.Checked))
            {
                var query = "SELECT TOP 1 * FROM tbNhapkhotp  ORDER BY ID DESC ";
                var kq = ExecuteQuerySQL(query, null);
                var parentid = kq.Rows[0].Field<int>("ID");

                var nguyenlieus = new[]
  {
                        new { nl = item.nl1, dg = item.dg1, sl = item.sl1 },
                        new { nl = item.nl2, dg = item.dg2, sl = item.sl2 },
                        new { nl = item.nl3, dg = item.dg3, sl = item.sl3 },
                        new { nl = item.nl4, dg = item.dg4, sl = item.sl4 },
                        new { nl = item.nl5, dg = item.dg5, sl = item.sl5 }
                    };

                foreach (var nguyenlieu in nguyenlieus)
                {
                    if (!string.IsNullOrEmpty(nguyenlieu.nl))
                    {
                        query = @"INSERT INTO tbNhapkhonguyenlieu (ParentId, TTien, SL, SoHieu, SoHieuTP) VALUES (@ParentId, @TTien, @SL, @SoHieu, @SoHieuTP)";
                        var parameters = new SqlParameter[]
                         {
                                new SqlParameter("@ParentId", parentid.ToString()),
                                new SqlParameter("@TTien", nguyenlieu.dg.ToString()),
                                new SqlParameter("@SL", nguyenlieu.sl.ToString()),
                                new SqlParameter("@SoHieu", nguyenlieu.nl),
                                new SqlParameter("@SoHieuTP", item.TenThanhPham.Split('|')[1]),
                         };

                        var rowsAffected = ExecuteQueryResultSQL(query, parameters);
                    }
                }
            }

            XtraMessageBox.Show("Lưu dữ liệu thành công");
        }

