        private void gridView6_MouseDown(object sender, MouseEventArgs e)
        {
            var hitInfo = gridView6.CalcHitInfo(e.Location);
            if (hitInfo.InColumn)
            {
                var column = hitInfo.Column;
                if (column.ToString() == "Chọn")
                {
                    foreach (var item in lstNhapkhotp)
                    {
                        if (checkedtp == false)
                        {
                            item.Checked = false;
                        }
                        else
                        {
                            item.Checked = true;
                        }
                    }
                    if (checkedtp == false)
                        checkedtp = true;
                    else
                        checkedtp = false;
                    for(int i=0;i<gridView6.RowCount;i++)
                    {
                        gridView6.RefreshRow(i);
                    }
                }
               
            }

            if (hitInfo.RowHandle >= 0)
            {
                if (hitInfo.Column != null && hitInfo.Column.OptionsColumn.AllowEdit  && hitInfo.Column.ToString().Contains("Nguyên liệu"))
                {
                    // Lấy giá trị từ ô đã nhấp
                    var cellValue = gridView6.GetRowCellValue(hitInfo.RowHandle, hitInfo.Column)?.ToString();
                    var columnName = hitInfo.Column.FieldName;
                    if (columnName.Contains("nl"))
                    {
                        string getnumber = columnName.Replace("nl", "");
                        int focushandle = hitInfo.RowHandle;
                        var getvattu = lstvt.Where(m => m.SoHieu == cellValue).FirstOrDefault();
                        double getsl = double.Parse(gridView6.GetRowCellValue(focushandle, "sl" + getnumber).ToString());
                        double dg1 = double.Parse(gridView6.GetRowCellValue(focushandle, "dg" + getnumber).ToString());
                        if (getvattu != null)
                        {
                            string tooltipContent = $"Tên vật tư: {getvattu.TenVattu}\n" + $"Số lượng: {getsl.ToString("N2")}\n" +   $"Giá nhập: {dg1.ToString("N0")}";       // Định dạng số nguyên
                            toolTipController.ShowHint(tooltipContent, Cursor.Position);
                            Task.Delay(3500).ContinueWith(_ =>
                            {
                                this.Invoke(new Action(() =>
                                {
                                    toolTipController.HideHint();
                                }));
                            });
                        }
                    }
                  
                }
            }
            
        }

