        private void dateEdit1_EditValueChanged(object sender, EventArgs e)
        {
            // Lấy giá trị từ dateEdit1
            DateTime? selectedDate = dateEdit1.EditValue as DateTime?;

            if (selectedDate.HasValue)
            {
                // Lấy tháng và năm từ ngày đã chọn
                int year = selectedDate.Value.Year;
                int month = selectedDate.Value.Month;

                // Tính ngày cuối tháng
                DateTime lastDayOfMonth = new DateTime(year, month, DateTime.DaysInMonth(year, month));

                // Cập nhật dateEdit2 với ngày cuối tháng
                dateEdit2.EditValue = lastDayOfMonth;
            }
            else
            {
                // Nếu không có giá trị, có thể đặt dateEdit2 thành null hoặc giá trị mặc định
                dateEdit2.EditValue = null; // Hoặc một giá trị mặc định nào đó
            }
        }

