        private void XoaHoadonRaVao(BindingList<FileImport> fileImports)
        {
            if (fileImports.Count > 0)
            {
                try
                {
                    if(chkDauvao.Checked)
                    {
                        progressPanel1.Visible=true;
                    }
                    else
                    {
                        progressPanel2.Visible = true;
                    }
                        progressPanel1.Caption = $"Đang xoá hoá đơn đầu vào từ ngày {dateEdit1.DateTime} đến ngày {dateEdit2.DateTime}";
                    foreach (var item in fileImports)
                    {
                        if (item.Checked == false)
                            continue;
                        var queryDelete = @"DELETE FROM tbimport WHERE ID=?";
                        var parametersDelete = new OleDbParameter[]
                        {
          new OleDbParameter("?",item.ID.ToString())
                        };
                        var result = ExecuteQueryResult(queryDelete, parametersDelete); // Xóa trong database

                        //Xoá detail
                        queryDelete = @"DELETE FROM tbimportdetail WHERE ParentId=?";
                        parametersDelete = new OleDbParameter[]
                        {
           new OleDbParameter("?",item.ID.ToString())
                        };
                        result = ExecuteQueryResult(queryDelete, parametersDelete); // Xóa trong database

                    }
                    LoadHoadonCT();
                    Loadtbimport();
                    btnChonthang.PerformClick();
                    progressPanel1.Visible = false;
                    progressPanel2.Visible = false;
                }
                catch (Exception ex)
                {
                    XtraMessageBox.Show(ex.Message);
                }
            }
            else
            {
                XtraMessageBox.Show("Không có dữ liệu để xoá!");
            }
        }

