            gridView6.CloseEditor();

            // Xử lý double click
            int rowHandle = gridView6.FocusedRowHandle;
            var column = gridView6.FocusedColumn;
            DevExpress.XtraGrid.Columns.GridColumn currentColumn = gridView6.FocusedColumn; 
            DevExpress.XtraGrid.Views.Grid.GridView view = gridView6;
            
            int focusedRow = view.FocusedRowHandle;
            Nhapkhotp dt = view.GetRow(focusedRow) as Nhapkhotp;



            if (!currentColumn.ToString().Contains("Nguyên liệu") && currentColumn.ToString() != "TÊN THÀNH PHẨM")
            {
                return;
            }
            frmHangHoa frmHangHoa = new frmHangHoa();
            frmHangHoa.frmMain = this;
            frmHangHoa.dtoVatTu = new DTO.VatTu();
            frmHangHoa.dtoVatTu.SoHieu = gridView6.GetRowCellValue(rowHandle, gridView6.FocusedColumn.FieldName) != null ? gridView6.GetRowCellValue(rowHandle, gridView6.FocusedColumn.FieldName).ToString() : "";
            string queryCheckVatTu = @"SELECT * FROM PhanLoaiVattu WHERE SoHieu=? or SoHieu=?";
            OleDbParameter[] parameterss = null;

            if (currentColumn.ToString().Contains("Nguyên liệu"))
            {
                parameterss = new OleDbParameter[]
                {
        new OleDbParameter("?", "NL"),  // Tham số cho nguyên liệu
        new OleDbParameter("?", "NVL")   // Tham số cho nguyên vật liệu
                };
            }
            else if (currentColumn.ToString() == "TÊN THÀNH PHẨM")
            {
                parameterss = new OleDbParameter[]
                {
                  new OleDbParameter("?", "TP") ,   // Tham số cho tên thành phẩm,
                     new OleDbParameter("?", "TP")   // Tham số cho nguyên vật liệu
                };
            }

            var kq = ExecuteQuery(queryCheckVatTu, parameterss);
            if (kq.Rows.Count > 0)
            {
                this.currentselectId = kq.Rows[0].Field<int>("MaSo");
            }
            else
            {
                this.currentselectId = 0;
            }
            frmHangHoa.ShowDialog();
            //frmMain.hiddenValue3

            //Tính số lượng
            var getvt = lstvt.Where(m => m.SoHieu == this.hiddenValue).FirstOrDefault();
            if (getvt != null)
            {
                //Tìm chứng từ cuối cùng
                //var findlastCt = existingTbChungtu.AsEnumerable().Where(m => m.Field<int>("MaVattu")==getvt.MaSo && m["SoPS2No"].ToString()!="0").LastOrDefault();
                var getTien = tbTonkho.AsEnumerable().Where(m => m.Field<int>("MaVatTu") == getvt.MaSo).FirstOrDefault();

                if (getTien != null)
                {
                    for (int i = 1; i <= 5; i++)
                    {
                        if (currentColumn.ToString() == $"Nguyên liệu {i}")
                        {
                            double getLuong = 0;
                            var gettien = getTien.Field<double>($"Tien_{dateEdit1.DateTime.Month}");
                            int getmonth = dateEdit1.DateTime.Month - 1;
                            if (gettien == 0)
                            {

                                while (gettien == 0 && getmonth >= 0)

                                {
                                    gettien = getTien.Field<double>($"Tien_{getmonth}");
                                    getLuong = getTien.Field<double>($"Luong_{getmonth}");
                                    getmonth -= 1;
                                }
                            }
                            else
                            {
                                getLuong = getTien.Field<double>($"Luong_{dateEdit1.DateTime.Month}");
                            }
                            if (gettien == 0 && getLuong == 0)
                            {
                                XtraMessageBox.Show("Nguyên liệu này chưa có giá bán!");
                                return;
                            }
                            var DonGia = Math.Round(gettien / getLuong);
                            double tt = double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, "DonGia").ToString()) *
                                         double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, "SoLuongTon").ToString());
                            double percent2 = double.Parse(gridView6.GetRowCellValue(gridView6.FocusedRowHandle, $"ps{i}").ToString());
                            var tt1 = (tt * percent2 / 100);
                            double sL = Math.Round(tt1 / DonGia, 2);
                            sL = sL < 0 ? sL * -1 : sL;

                            gridView6.SetRowCellValue(gridView6.FocusedRowHandle, $"sl{i}", sL);
                            gridView6.SetRowCellValue(gridView6.FocusedRowHandle, $"dg{i}", DonGia);

                            gridView6.SetRowCellValue(gridView6.FocusedRowHandle, currentColumn, this.hiddenValue);
                            break; // Kết thúc vòng lặp nếu tìm thấy trường hợp phù hợp
                        }
                    }
                    if (currentColumn.ToString() == "TÊN THÀNH PHẨM")
                    {
                        gridView6.SetRowCellValue(gridView6.FocusedRowHandle, currentColumn, this.hiddenValue3 + " | " + this.hiddenValue);
                        DateTime currentDate = DateTime.Now;
                        DateTime firstDayOfMonth = new DateTime(currentDate.Year, currentDate.Month, 1);

                        var aa = findDataNK(firstDayOfMonth, currentDate).Where(m => m.TenThanhPham.Split('|')[1] == this.hiddenValue).FirstOrDefault();
                        if (aa != null)
                        {
                            // Sao chép dữ liệu từ aa sang dt
                            dt.SoHieu = aa.SoHieu;
                            dt.ID = aa.ID;
                            dt.TenThanhPham = aa.TenThanhPham;
                            dt.GiaBan = aa.GiaBan;
                            dt.SoLuongTon = aa.SoLuongTon;
                            dt.SoLuongNhap = aa.SoLuongNhap;
                            dt.Percent = aa.Percent;
                            dt.DonGia = aa.DonGia;

                            // Sao chép các thuộc tính nl và sl
                            dt.nl1 = aa.nl1; dt.sl1 = aa.sl1; dt.ps1 = aa.ps1; dt.dg1 = aa.dg1;
                            dt.nl2 = aa.nl2; dt.sl2 = aa.sl2; dt.ps2 = aa.ps2; dt.dg2 = aa.dg2;
                            dt.nl3 = aa.nl3; dt.sl3 = aa.sl3; dt.ps3 = aa.ps3; dt.dg3 = aa.dg3;
                            dt.nl4 = aa.nl4; dt.sl4 = aa.sl4; dt.ps4 = aa.ps4; dt.dg4 = aa.dg4;
                            dt.nl5 = aa.nl5; dt.sl5 = aa.sl5; dt.ps5 = aa.ps5; dt.dg5 = aa.dg5;
                            dt.Checked = aa.Checked;

                            // Sao chép danh sách Nguyenlieus nếu cần
                            dt.Nguyenlieus = aa.Nguyenlieus;
                            lstNhapkhotp.Add(dt);
                            if (dt.sl1 == 0)
                                XtraMessageBox.Show("Nguyên liệu này chưa có giá bán!");
                        }
                        gridControl4.DataSource = lstNhapkhotp;
                        gridView6.RefreshData();
                        // CapnhatNguyenlieuthanhpham();
                    }
                }
                else
                {
                    XtraMessageBox.Show("Nguyên liệu này chưa có tồn tại trong kho!");
                    return;
                }
            }
            else
            {
                //  XtraMessageBox.Show("Không tìm thấy vật tư!");
            }
        }
