        private void gridView6_CustomDrawCell(object sender, DevExpress.XtraGrid.Views.Base.RowCellCustomDrawEventArgs e)
        {
           

            if (e.Column.FieldName.Contains("ps"))
            {
                if (e.CellValue == null)
                    return;
                int rowhandle = e.RowHandle;
                double getValue = double.Parse(e.CellValue.ToString());
                if (getValue == 11)
                {
                    int a = 10;
                }
                if (getValue > 100)
                {
                    System.Drawing.Font boldFont = new System.Drawing.Font(e.Appearance.Font, FontStyle.Bold);
                    e.Cache.DrawString(
                        e.DisplayText,
                        boldFont,
                        Brushes.Red,  // Chữ màu đỏ
                       e.Bounds,
                    e.Appearance.GetStringFormat()
                    );
                    e.Handled = true; // Ngăn vẽ mặc định
                }
                else
                {
                    //Lấy ra index 
                    int getIndex = int.Parse(e.Column.FieldName.Replace("ps", ""));
                    if (getIndex == 1)
                    {

                    }
                    else
                    {
                        double totalPercent = 0;
                         //Tính đằng trước
                         for(int i = 1; i < getIndex; i++)
                        {
                            var getvalue = gridView6.GetRowCellValue(rowhandle, "ps" + i);
                            totalPercent += double.Parse(getvalue.ToString());
                        }
                        if ((getValue + totalPercent) > 100)
                        {
                            System.Drawing.Font boldFont = new System.Drawing.Font(e.Appearance.Font, FontStyle.Bold);
                            e.Cache.DrawString(
                                e.DisplayText,
                                boldFont,
                                Brushes.Red,  // Chữ màu đỏ
                               e.Bounds,
                            e.Appearance.GetStringFormat()
                            );
                            e.Handled = true; // Ngăn vẽ mặc định
                        }
                    }
                }
               
            }
        }

