        private List<string> GetSubdirectoriesWithKeyword(string rootDir, string keyword)
        {
            List<string> matchingDirs = new List<string>();

            try
            {
                // Lấy tất cả thư mục con trực tiếp trong thư mục gốc
                var directories = Directory.GetDirectories(rootDir);

                foreach (var dir in directories)
                {
                    // Kiểm tra xem tên thư mục có chứa từ khóa không
                    if (dir.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        matchingDirs.Add(dir);
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("An error occurred: " + ex.Message);
            }

            return matchingDirs;
        }

