        private void AnalyzePDF(string filePath)
        {
            try
            {
                // 1. Đọc PDF MIỄN PHÍ
                string pdfText = ExtractTextFromPDF(filePath);

                // 2. Tự động phát hiện loại sao kê
                string bankType = DetectBankType(pdfText);

                // 3. Trích xuất giao dịch
                List<Transaction> transactions = ExtractTransactions(pdfText, bankType);

                // 4. Phân tích thông minh
                string analysis = GenerateAnalysis(transactions);

                // 5. Xuất Excel MIỄN PHÍ
                ExportToExcel(transactions, filePath);

                
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Lỗi: {ex.Message}", "Lỗi",
                    MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
        // =================== XUẤT EXCEL MIỄN PHÍ ===================
        private void ExportToExcel(List<Transaction> transactions, string originalPdfPath)
        {
            string excelPath = Path.ChangeExtension(originalPdfPath, ".xlsx");

            // Sử dụng EPPlus MIỄN PHÍ (cần cài package)
            // Hoặc xuất CSV đơn giản
            ExportToCSV(transactions, excelPath);

            MessageBox.Show($"Đã xuất file Excel: {excelPath}",
                "Thành công", MessageBoxButtons.OK, MessageBoxIcon.Information);
        }

        private void ExportToCSV(List<Transaction> transactions, string csvPath)
        {
            var csv = new StringBuilder();
            csv.AppendLine("Ngày,Mô tả,Ghi nợ,Ghi có,Số dư");

            foreach (var t in transactions.OrderByDescending(x => x.Date))
            {
                csv.AppendLine($"\"{t.Date:dd/MM/yyyy}\",\"{t.Description}\",{t.Debit},{t.Credit},{t.Balance}");
            }

            File.WriteAllText(csvPath.Replace(".xlsx", ".csv"), csv.ToString(), Encoding.UTF8);
        }

        // =================== PHÂN TÍCH TỰ ĐỘNG ===================
        private string GenerateAnalysis(List<Transaction> transactions)
        {
            if (transactions.Count == 0)
                return "Không tìm thấy giao dịch nào.";

            var sb = new StringBuilder();

            // Tính toán thống kê
            decimal totalDebit = transactions.Sum(t => t.Debit);
            decimal totalCredit = transactions.Sum(t => t.Credit);
            decimal startBalance = transactions.Last().Balance - totalCredit + totalDebit;
            decimal endBalance = transactions.First().Balance;
            int count = transactions.Count;

            sb.AppendLine("📊 PHÂN TÍCH SAO KÊ TỰ ĐỘNG");
            sb.AppendLine("=".PadRight(50, '='));
            sb.AppendLine($"Tổng số giao dịch: {count}");
            sb.AppendLine($"Số dư đầu kỳ: {startBalance:N0} VND");
            sb.AppendLine($"Số dư cuối kỳ: {endBalance:N0} VND");
            sb.AppendLine($"Tổng thu (Ghi có): {totalCredit:N0} VND");
            sb.AppendLine($"Tổng chi (Ghi nợ): {totalDebit:N0} VND");
            sb.AppendLine($"Chênh lệch: {(totalCredit - totalDebit):N0} VND");
            sb.AppendLine();

            // Phân loại giao dịch
            sb.AppendLine("🏷️ PHÂN LOẠI GIAO DỊCH:");
            var categories = CategorizeTransactions(transactions);
            foreach (var cat in categories.OrderByDescending(c => c.Value))
            {
                sb.AppendLine($"  {cat.Key}: {cat.Value:N0} VND");
            }
            sb.AppendLine();

            // Giao dịch lớn nhất
            var largestCredit = transactions.OrderByDescending(t => t.Credit).FirstOrDefault();
            var largestDebit = transactions.OrderByDescending(t => t.Debit).FirstOrDefault();

            if (largestCredit != null && largestCredit.Credit > 0)
            {
                sb.AppendLine("💰 GIAO DỊCH LỚN NHẤT:");
                sb.AppendLine($"  Thu lớn nhất: {largestCredit.Credit:N0} VND");
                sb.AppendLine($"    Ngày: {largestCredit.Date:dd/MM/yyyy}");
                sb.AppendLine($"    Mô tả: {largestCredit.Description}");
            }

            // Xu hướng
            sb.AppendLine();
            sb.AppendLine("📈 XU HƯỚNG:");
            if (totalCredit > totalDebit)
                sb.AppendLine("  ✅ Dòng tiền vào lớn hơn ra");
            else
                sb.AppendLine("  ⚠️ Dòng tiền ra lớn hơn vào");

            if (transactions.Count(t => t.Credit > 0) > transactions.Count(t => t.Debit > 0))
                sb.AppendLine("  📈 Số lần thu nhiều hơn chi");
            else
                sb.AppendLine("  📉 Số lần chi nhiều hơn thu");

            return sb.ToString();
        }
        private Dictionary<string, decimal> CategorizeTransactions(List<Transaction> transactions)
        {
            var categories = new Dictionary<string, decimal>
            {
                ["Chuyển khoản"] = 0,
                ["Thanh toán hóa đơn"] = 0,
                ["Rút tiền mặt"] = 0,
                ["Phí dịch vụ"] = 0,
                ["Thuế"] = 0,
                ["Lương"] = 0,
                ["Khác"] = 0
            };

            foreach (var t in transactions)
            {
                string desc = t.Description.ToLower();
                decimal amount = Math.Max(t.Debit, t.Credit);

                if (desc.Contains("chuyen") || desc.Contains("ck") || desc.Contains("transfer"))
                    categories["Chuyển khoản"] += amount;
                else if (desc.Contains("thanh toan") || desc.Contains("tt") || desc.Contains("hóa đơn"))
                    categories["Thanh toán hóa đơn"] += amount;
                else if (desc.Contains("rut tien") || desc.Contains("atm"))
                    categories["Rút tiền mặt"] += amount;
                else if (desc.Contains("phi") || desc.Contains("fee"))
                    categories["Phí dịch vụ"] += amount;
                else if (desc.Contains("thue") || desc.Contains("vat"))
                    categories["Thuế"] += amount;
                else if (desc.Contains("luong") || desc.Contains("salary"))
                    categories["Lương"] += amount;
                else
                    categories["Khác"] += amount;
            }

            return categories;
        }
        private DateTime ParseDate(string dateStr)
        {
            if (DateTime.TryParseExact(dateStr, "dd/MM/yyyy", null,
                System.Globalization.DateTimeStyles.None, out DateTime result))
                return result;
            return DateTime.Now;
        }

        private decimal ParseAmount(string amountStr)
        {
            if (string.IsNullOrWhiteSpace(amountStr)) return 0;
            string clean = amountStr.Replace(",", "").Replace(".", "");
            if (decimal.TryParse(clean, out decimal result))
                return result;
            return 0;
        }
        public class Transaction
        {
            public DateTime Date { get; set; }
            public string Description { get; set; }
            public decimal Debit { get; set; }
            public decimal Credit { get; set; }
            public decimal Balance { get; set; }
        }
        // =================== TRÍCH XUẤT GIAO DỊCH THÔNG MINH ===================
        private List<Transaction> ExtractTransactions(string text, string bankType)
        {
            var transactions = new List<Transaction>();
            var lines = text.Split('\n');

            // Regex cho các pattern phổ biến
            string datePattern = @"(\d{2}/\d{2}/\d{4})";
            string amountPattern = @"([\d,]+\.?\d*)";

            for (int i = 0; i < lines.Length; i++)
            {
                string line = lines[i].Trim();

                // Tìm dòng có ngày tháng
                var dateMatch = Regex.Match(line, datePattern);
                if (dateMatch.Success)
                {
                    string date = dateMatch.Value;
                    string description = "";
                    decimal debit = 0, credit = 0, balance = 0;

                    // Tách phần mô tả (từ sau ngày đến trước số tiền đầu tiên)
                    int dateEnd = dateMatch.Index + dateMatch.Length;
                    string remaining = line.Substring(dateEnd).Trim();

                    // Tìm tất cả số tiền trong dòng
                    var amountMatches = Regex.Matches(remaining, amountPattern);

                    if (amountMatches.Count >= 3)
                    {
                        // Mô tả là phần trước số tiền đầu tiên
                        description = remaining.Substring(0, amountMatches[0].Index).Trim();

                        // Xác định đâu là Ghi nợ, Ghi có, Số dư dựa trên vị trí
                        // Logic thông minh: thường format là Date | Desc | Debit | Credit | Balance
                        // Hoặc Date | Desc | Amount | Balance (tùy bank)

                        if (bankType == "VIB" || bankType == "VIETCOMBANK")
                        {
                            // Format phổ biến: Date | Description | Debit | Credit | Balance
                            if (amountMatches.Count >= 3)
                            {
                                debit = ParseAmount(amountMatches[0].Value);
                                credit = ParseAmount(amountMatches[1].Value);
                                balance = ParseAmount(amountMatches[2].Value);
                            }
                        }
                    }

                    // Nếu không parse được theo pattern, dùng heuristic
                    if (description == "" && amountMatches.Count == 0)
                    {
                        var reader = new SmartPDFReader();
                       // description = reader.ExtractDescriptionHeuristic(line, date);
                       // reader.ParseAmountsHeuristic(line, ref debit, ref credit, ref balance);
                    }

                    transactions.Add(new Transaction
                    {
                        Date = ParseDate(date),
                        Description = description,
                        Debit = debit,
                        Credit = credit,
                        Balance = balance
                    });
                }
            }

            return transactions;
        }

        // =================== PHÁT HIỆN NGÂN HÀNG ===================
        private string DetectBankType(string text)
        {
            if (text.Contains("VIETCOMBANK") || text.Contains("VCB"))
                return "VIETCOMBANK";
            if (text.Contains("VIETINBANK"))
                return "VIETINBANK";
            if (text.Contains("TECHCOMBANK") || text.Contains("TCB"))
                return "TECHCOMBANK";
            if (text.Contains("BIDV"))
                return "BIDV";
            if (text.Contains("ACB"))
                return "ACB";
            if (text.Contains("VIB"))
                return "VIB";
            if (text.Contains("MBBANK") || text.Contains("MB"))
                return "MBBANK";
            if (text.Contains("VPBANK") || text.Contains("VP"))
                return "VPBANK";
            if (text.Contains("SACOMBANK"))
                return "SACOMBANK";

            return "UNKNOWN";
        }
        private string ExtractTextFromPDF(string pdfPath)
        {
            StringBuilder sb = new StringBuilder();

            using (var pdf =UglyToad.PdfPig.PdfDocument.Open(pdfPath))
            {
                foreach (var page in pdf.GetPages())
                {
                    sb.AppendLine(page.Text);
                }
            }

            return sb.ToString();
        }
        private string WaitAndRenameToOutput(string downloadFolder)
        {
            string outputPath = Path.Combine(downloadFolder, "output.xlsx");
            FileInfo downloadedFile = null;

            // Chờ tối đa 60 giây
            for (int i = 0; i < 60; i++)
            {
                downloadedFile = new DirectoryInfo(downloadFolder)
                    .GetFiles("*.xlsx")
                    .OrderByDescending(f => f.LastWriteTime)
                    .FirstOrDefault();

                if (downloadedFile != null && !IsFileLocked(downloadedFile.FullName))
                    break;

                Thread.Sleep(1000);
            }

            if (downloadedFile == null)
                throw new Exception("Không tìm thấy file Excel sau khi download");

            // Ghi đè nếu đã tồn tại
            if (File.Exists(outputPath))
                File.Delete(outputPath);

            File.Move(downloadedFile.FullName, outputPath);

            return outputPath;
        }
        private bool IsFileLocked(string filePath)
        {
            try
            {
                using (FileStream stream = File.Open(filePath, FileMode.Open, FileAccess.Read, FileShare.None))
                {
                    return false;
                }
            }
            catch
            {
                return true;
            }
        }

